umask 077
work=$(mktemp -d "${TMPDIR:-/tmp}/cm1406-vitrum-plus-installer.XXXXXXXX")
trap 'rm -rf -- "$work"' EXIT
trap 'exit 130' INT
trap 'exit 143' TERM HUP
cat > "$work/helper.py" <<'VITRUM_HELPER_EOF'
