MAX_IMAGE = 64 * 1024 * 1024
SYS_CLASS = Path(os.environ.get("VP_TEST_SYS_CLASS") or "/sys/class")
MANAGED = re.compile(r"wallpaper-[0-9a-f]{32}\.(jpg|png|webp|gif|bmp)")
FIELD_CODE = re.compile(r"%[fFuUdDnNickvm%]")
BOOT = ("import sys, importlib.util as u; s = u.spec_from_file_location('helper', sys.argv[1]); "
        "m = u.module_from_spec(s); s.loader.exec_module(m); m.entry(sys.argv[2:])")


def read(path):
    try:
        return Path(path).read_text().strip()
    except (OSError, ValueError):
        return ""


class Notice(ValueError):
    pass


LOG_LIMIT = 65536


def log_path():
    base = os.environ.get("VP_APP_RUNTIME") or os.environ.get("XDG_RUNTIME_DIR") or ""
    if not base or not os.path.isabs(base):
        return None
    folder = Path(base) / "cm1406-vitrum-plus"
    if folder.is_symlink() or not folder.is_dir():
        return None
    return folder / "helper.log"


def log(text):
    line = time.strftime("%Y-%m-%d %H:%M:%S") + " [" + str(os.getpid()) + "] " + text.rstrip("\n")
    try:
        print(line, file=sys.stderr, flush=True)
    except (OSError, ValueError):
        pass
    path = log_path()
    if path is None:
        return
    try:
        fd = os.open(path, os.O_RDWR | os.O_CREAT | os.O_APPEND | os.O_NOFOLLOW, 0o600)
        try:
            if os.fstat(fd).st_size > LOG_LIMIT:
                os.lseek(fd, -LOG_LIMIT // 2, os.SEEK_END)
                tail = os.read(fd, LOG_LIMIT // 2)
                tail = tail[tail.find(b"\n") + 1:]
                os.ftruncate(fd, 0)
                os.write(fd, tail)
            os.write(fd, (line + "\n").encode("utf-8", "replace"))
        finally:
            os.close(fd)
    except OSError:
        pass


def log_error(where):
    log(where + ": " + traceback.format_exc().strip())


def light_file(device):
    return Path(device) / "brightness"


def set_light(device, level, tool_args):
    top = read(Path(device) / "max_brightness")
    if not top.isdigit() or int(top) <= 0:
        raise Notice("Réglage indisponible")
    target = light_file(device)
    value = max(0, min(int(top), round(int(top) * level / 100)))
    if os.access(target, os.W_OK):
        try:
            with open(target, "w") as stream:
                stream.write(str(value))
            return "sysfs"
        except OSError as exc:
            log(f"write {target} failed: {exc}")
    if shutil.which("brightnessctl"):
        try:
            result = subprocess.run(["brightnessctl", "-q"] + tool_args + ["set", f"{level}%"],
                                    capture_output=True, text=True, timeout=3)
        except (OSError, subprocess.SubprocessError) as exc:
            log(f"brightnessctl failed: {exc}")
        else:
            if result.returncode == 0:
                return "brightnessctl"
            log("brightnessctl " + " ".join(tool_args) + f" exited {result.returncode}: " + (result.stderr or result.stdout).strip()[:300])
    raise Notice("Autorisation requise : lance --system-access")


def light_writable(device):
    return os.access(light_file(device), os.W_OK)


def battery(base=Path("/sys/class/power_supply")):
    cells = []
    for device in sorted(base.glob("*")):
        if read(device / "type") != "Battery" or read(device / "scope") == "Device":
            continue
        if read(device / "present") == "0":
            continue
        capacity = read(device / "capacity")
        if capacity.isdigit() and 0 <= int(capacity) <= 100:
            cells.append((int(capacity), read(device / "status")))
    if not cells:
        return "Batterie —"
    value = round(sum(c[0] for c in cells) / len(cells))
    state = "en charge" if any(c[1] == "Charging" for c in cells) else (
        "pleine" if all(c[1] == "Full" for c in cells) else "sur batterie" if any(
            c[1] == "Discharging" for c in cells) else "au repos")
    return f"{value} % · {state}" + (" · moyenne" if len(cells) > 1 else "")


def network(base=Path("/sys/class/net")):
    links = []
    for device in sorted(base.glob("*")):
        if device.name == "lo" or "/virtual/" in str(device.resolve()):
            continue
        state = read(device / "operstate")
        carrier = read(device / "carrier")
        if state == "up" and carrier == "1":
            links.append("Wi-Fi" if (device / "wireless").exists() else "Ethernet")
    return "Lien " + " + ".join(sorted(set(links))) if links else "Réseau · aucun lien"


def cpu_sample():
    try:
        fields = [int(x) for x in Path("/proc/stat").read_text().split("\n", 1)[0].split()[1:]]
    except (OSError, ValueError):
        return None
    idle = fields[3] + (fields[4] if len(fields) > 4 else 0)
    return sum(fields), idle


def cpu_percent(before, after):
    if not before or not after or after[0] <= before[0]:
        return -1
    total = after[0] - before[0]
    return round(100 * (total - (after[1] - before[1])) / total)


def memory_percent():
    info = {}
    try:
        for line in Path("/proc/meminfo").read_text().splitlines():
            key, _, value = line.partition(":")
            info[key] = int(value.split()[0])
        return round(100 * (1 - info["MemAvailable"] / info["MemTotal"]))
    except (OSError, ValueError, KeyError, ZeroDivisionError, IndexError):
        return -1


def temperature(base=Path("/sys/class/thermal")):
    values = []
    for zone in base.glob("thermal_zone*"):
        raw = read(zone / "temp")
        if raw.lstrip("-").isdigit() and 0 < int(raw) < 150000:
            values.append(int(raw))
    return round(max(values) / 1000) if values else -1


def backlight_device(base=SYS_CLASS / "backlight"):
    try:
        found = sorted(base.glob("*"))
    except OSError:
        return None
    for device in found:
        now, top = read(device / "brightness"), read(device / "max_brightness")
        if now.isdigit() and top.isdigit() and int(top) > 0:
            return device
    return None


def backlight(base=SYS_CLASS / "backlight"):
    device = backlight_device(base)
    if device is None:
        return -1
    return round(100 * int(read(device / "brightness")) / int(read(device / "max_brightness")))


def volume_level():
    if not shutil.which("wpctl"):
        return -1, False
    try:
        result = subprocess.run(["wpctl", "get-volume", "@DEFAULT_AUDIO_SINK@"],
                                capture_output=True, text=True, timeout=1, check=True)
    except (OSError, subprocess.SubprocessError):
        return -1, False
    match = re.fullmatch(r"Volume:\s+(\d+(?:\.\d+)?)\s*(\[MUTED\])?\s*", result.stdout)
    if not match:
        return -1, False
    return round(float(match[1]) * 100), bool(match[2])


def radios():
    wifi = None
    for device in sorted(Path("/sys/class/net").glob("*")):
        if (device / "wireless").exists():
            up = read(device / "operstate") == "up" and read(device / "carrier") == "1"
            wifi = "connecté" if up else "déconnecté"
    bluetooth = None
    for device in sorted(Path("/sys/class/rfkill").glob("rfkill*")):
        blocked = read(device / "soft") == "1" or read(device / "hard") == "1"
        if read(device / "type") == "bluetooth":
            bluetooth = "bloqué" if blocked else "actif"
        elif read(device / "type") == "wlan" and blocked and wifi is not None:
            wifi = "bloqué"
    return {"wifi": wifi or "absent", "bluetooth": bluetooth or "absent"}


def color_scheme():
    if not shutil.which("gsettings"):
        return ""
    try:
        result = subprocess.run(["gsettings", "get", "org.gnome.desktop.interface", "color-scheme"],
                                capture_output=True, text=True, timeout=1)
    except (OSError, subprocess.SubprocessError):
        return ""
    return result.stdout.strip().strip("'") if result.returncode == 0 else ""


def clean_appearance(value):
    mode = value.get("mode") if isinstance(value, dict) else None
    return mode if mode in ("auto", "light", "dark") else "auto"


def appearance_view(mode, scheme):
    dark = mode == "dark" or (mode == "auto" and scheme != "prefer-light")
    return {"mode": mode, "dark": dark, "system": scheme}


def mako_config():
    base = os.environ.get("XDG_CONFIG_HOME") or str(Path.home() / ".config")
    return Path(base) / "mako" / "config"


def dnd_state():
    if not shutil.which("makoctl"):
        return {"available": False, "on": False}
    try:
        configured = "[mode=do-not-disturb]" in mako_config().read_text(errors="replace")
    except OSError:
        configured = False
    try:
        result = subprocess.run(["makoctl", "mode"], capture_output=True, text=True, timeout=1)
        modes = result.stdout.split() if result.returncode == 0 else []
    except (OSError, subprocess.SubprocessError):
        modes = []
    return {"available": configured, "on": configured and "do-not-disturb" in modes}


def kernel_events():
    found = {}
    fake = os.environ.get("VP_TEST_UEVENT")
    if fake:
        channel = socket.socket(socket.AF_UNIX, socket.SOCK_DGRAM | socket.SOCK_NONBLOCK | socket.SOCK_CLOEXEC)
        channel.bind(fake)
        found["uevent"] = channel
    for name, kind, protocol in (("uevent", socket.SOCK_DGRAM, getattr(socket, "NETLINK_KOBJECT_UEVENT", 15)),
                                 ("link", socket.SOCK_RAW, getattr(socket, "NETLINK_ROUTE", 0))):
        if name in found:
            continue
        try:
            channel = socket.socket(socket.AF_NETLINK, kind | socket.SOCK_NONBLOCK | socket.SOCK_CLOEXEC, protocol)
        except (OSError, AttributeError):
            continue
        try:
            channel.bind((0, 1))
        except OSError:
            channel.close()
            continue
        found[name] = channel
    return found


def uevent_subsystems(channel):
    found = set()
    for _ in range(64):
        try:
            data = channel.recv(65536)
        except (BlockingIOError, InterruptedError):
            break
        if not data:
            break
        for field in data.split(b"\0")[1:]:
            if field.startswith(b"SUBSYSTEM="):
                found.add(field[10:].decode("ascii", "replace"))
                break
    return found


def drain(channel):
    count = 0
    for _ in range(64):
        try:
            if not channel.recv(65536):
                break
        except (BlockingIOError, InterruptedError):
            break
        count += 1
    return count


def watcher(command):
    if not shutil.which(command[0]):
        return None
    try:
        return subprocess.Popen(command, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
    except OSError:
        return None


def sink_event(line):
    text = line.decode("utf-8", "replace")
    return text.startswith("Event ") and (" on sink #" in text or " on server" in text)


def scheme_event(line):
    match = re.match(r"\s*color-scheme:\s*'?([a-z-]*)'?\s*$", line.decode("utf-8", "replace"))
    return match[1] if match else None


def wifi_name(backend=None):
    if backend and backend.get("name") == "iwd":
        code, out = run_tool(["iwctl", "station", backend["iface"], "show"], 3)
        match = re.search(r"Connected network\s+(.+?)\s*$", strip_ansi(out), re.M)
        return clean(match[1])[:40] if match else ""
    if backend and backend.get("name") == "wpa":
        state = wpa_status(backend["iface"])
        return clean(wpa_unescape(state.get("ssid", "")))[:40] if state.get("wpa_state") == "COMPLETED" else ""
    if not shutil.which("nmcli"):
        return ""
    try:
        result = subprocess.run(["nmcli", "-t", "-f", "TYPE,NAME", "connection", "show", "--active"],
                                capture_output=True, text=True, timeout=1)
    except (OSError, subprocess.SubprocessError):
        return ""
    for line in result.stdout.splitlines():
        kind, _, name = line.partition(":")
        if kind == "802-11-wireless" and name:
            return clean(name.replace("\\:", ":"))[:40]
    return ""


def all_apps():
    found = {}
    for base in data_dirs():
        directory = base / "applications"
        if not directory.is_dir():
            continue
        for path in sorted(directory.rglob("*.desktop"))[:2000]:
            key = str(path.relative_to(directory)).replace("/", "-")
            if key in found:
                continue
            parser = configparser.ConfigParser(interpolation=None, strict=False)
            parser.optionxform = str
            try:
                parser.read_string(path.read_text())
                entry = parser["Desktop Entry"]
                if (entry.get("Type") != "Application" or entry.getboolean("Hidden", False)
                        or entry.getboolean("NoDisplay", False)):
                    found[key] = None
                    continue
                executable = entry.get("TryExec", "")
                if executable and not shutil.which(executable):
                    found[key] = None
                    continue
                found[key] = desktop_entry(key)
            except (OSError, UnicodeError, ValueError, configparser.Error, KeyError):
                found[key] = None
    apps = [{"id": k, "name": v["name"], "icon": v["icon"], "path": v["path"]} for k, v in found.items() if v]
    return sorted(apps, key=lambda a: a["name"].casefold())[:400]


def short_layout(name):
    letters = re.sub(r"[^A-Za-z]", "", name.split("(")[0])[:2].upper()
    return letters or "?"


def request(payload):
    with socket.socket(socket.AF_UNIX) as client:
        client.settimeout(0.6)
        client.connect(os.environ["NIRI_SOCKET"])
        client.sendall((json.dumps(payload) + "\n").encode())
        with client.makefile("rb") as stream:
            reply = json.loads(stream.readline(1048576))
        if "Err" in reply:
            raise ValueError(reply["Err"])
        return reply["Ok"]


def body(event, name):
    value = event.get(name) if isinstance(event, dict) else None
    return value if isinstance(value, dict) else None


def valid_id(value):
    return isinstance(value, int) and not isinstance(value, bool)


def apply_event(workspaces, event):
    change = body(event, "WorkspacesChanged")
    if change is not None:
        found = change.get("workspaces")
        if isinstance(found, list):
            return [w for w in found if isinstance(w, dict) and valid_id(w.get("id"))]
        return workspaces
    change = body(event, "WorkspaceActivated")
    if change is not None:
        target = next((w for w in workspaces if w.get("id") == change.get("id")), None)
        if target:
            for workspace in workspaces:
                if workspace.get("output") == target.get("output"):
                    workspace["is_active"] = workspace.get("id") == target.get("id")
                if change.get("focused"):
                    workspace["is_focused"] = workspace.get("id") == target.get("id")
    change = body(event, "WorkspaceUrgencyChanged")
    if change is not None:
        for workspace in workspaces:
            if workspace.get("id") == change.get("id"):
                workspace["is_urgent"] = bool(change.get("urgent"))
    change = body(event, "WorkspaceActiveWindowChanged")
    if change is not None:
        for workspace in workspaces:
            if workspace.get("id") == change.get("workspace_id"):
                workspace["active_window_id"] = change.get("active_window_id")
    return workspaces


def apply_window_event(windows, event):
    change = body(event, "WindowsChanged")
    if change is not None:
        found = change.get("windows")
        if isinstance(found, list):
            return {w["id"]: w for w in found if isinstance(w, dict) and valid_id(w.get("id"))}
        return windows
    change = body(event, "WindowOpenedOrChanged")
    if change is not None:
        window = change.get("window")
        if isinstance(window, dict) and valid_id(window.get("id")):
            windows[window["id"]] = window
            if window.get("is_focused"):
                for other in windows.values():
                    if other.get("id") != window["id"]:
                        other["is_focused"] = False
        return windows
    change = body(event, "WindowClosed")
    if change is not None:
        windows.pop(change.get("id"), None)
        return windows
    change = body(event, "WindowFocusChanged")
    if change is not None:
        focused = change.get("id")
        for window in windows.values():
            window["is_focused"] = window.get("id") == focused
        return windows
    change = body(event, "WindowFocusTimestampChanged")
    if change is not None:
        if change.get("id") in windows:
            windows[change["id"]]["focus_timestamp"] = change.get("focus_timestamp")
        return windows
    change = body(event, "WindowUrgencyChanged")
    if change is not None and change.get("id") in windows:
        windows[change["id"]]["is_urgent"] = bool(change.get("urgent"))
    return windows


def workspace_index(workspace):
    value = workspace.get("idx")
    return value if valid_id(value) else 0


def visible_workspaces(workspaces, output):
    return [{"id": str(w.get("id")), "label": str(workspace_index(w)), "name": w.get("name") if isinstance(w.get("name"), str) else "",
             "active": bool(w.get("is_active")), "focused": bool(w.get("is_focused")),
             "urgent": bool(w.get("is_urgent"))}
            for w in sorted(workspaces, key=workspace_index) if isinstance(w, dict) and w.get("output") == output]


def private_file(directory, name):
    path = Path(directory) / name
    if not path.is_absolute():
        return None
    for part in (*reversed(path.parents), path):
        if part.is_symlink():
            return None
    try:
        info = path.lstat()
        parent = path.parent.lstat()
    except OSError:
        return None
    if parent.st_uid != os.getuid() or not stat.S_ISDIR(parent.st_mode):
        return None
    if not stat.S_ISREG(info.st_mode) or info.st_uid != os.getuid():
        return None
    return path, info


def chosen_wallpaper(directory):
    found = private_file(directory, "choice.json")
    if not found or found[1].st_size >= 65536:
        return ""
    try:
        name = json.loads(found[0].read_text()).get("file")
    except (OSError, ValueError, AttributeError):
        return ""
    if not isinstance(name, str) or not MANAGED.fullmatch(name):
        return ""
    image = private_file(directory, name)
    if not image or not 0 < image[1].st_size <= MAX_IMAGE:
        return ""
    return image[0].as_uri()


def fond(default_mode):
    if default_mode != "fond":
        return ""
    path = Path.home() / "Pictures" / "fond.jpg"
    return path.as_uri() if path.is_file() else ""


def private_dir(path):
    path = Path(path)
    if not path.is_absolute():
        raise ValueError("data directory must be absolute")
    for part in (*reversed(path.parents), path):
        if part.is_symlink():
            raise ValueError("symlinked data directory")
    path.mkdir(mode=0o700, parents=True, exist_ok=True)
    info = path.lstat()
    if not stat.S_ISDIR(info.st_mode) or info.st_uid != os.getuid():
        raise ValueError("data directory is not a private directory")
    if info.st_mode & 0o077:
        os.chmod(path, 0o700)
    return path


def atomic_write(directory, name, data):
    temporary = directory / (".tmp-" + secrets.token_hex(8))
    fd = os.open(temporary, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
    try:
        with os.fdopen(fd, "wb") as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, directory / name)
        dfd = os.open(directory, os.O_RDONLY | os.O_DIRECTORY)
        try:
            os.fsync(dfd)
        finally:
            os.close(dfd)
    finally:
        if temporary.exists():
            temporary.unlink()


def image_kind(head):
    if head.startswith(b"\xff\xd8\xff"):
        return "jpg"
    if head.startswith(b"\x89PNG\r\n\x1a\n"):
        return "png"
    if head[:4] == b"RIFF" and head[8:12] == b"WEBP":
        return "webp"
    if head[:6] in (b"GIF87a", b"GIF89a"):
        return "gif"
    if head[:2] == b"BM":
        return "bmp"
    return None


class Wallpapers:
    def __init__(self, directory, default_mode):
        self.directory = private_dir(directory)
        self.default_mode = default_mode
        self.current = None
        self.pending = {}
        choice = self.directory / "choice.json"
        try:
            info = choice.lstat()
            if stat.S_ISREG(info.st_mode) and info.st_uid == os.getuid() and info.st_size < 65536:
                name = json.loads(choice.read_text()).get("file")
                if isinstance(name, str) and MANAGED.fullmatch(name) and self.valid(self.directory / name):
                    self.current = name
        except (OSError, ValueError, AttributeError):
            self.current = None
        for entry in self.directory.iterdir():
            if entry.name.startswith(".tmp-") or (MANAGED.fullmatch(entry.name) and entry.name != self.current):
                if entry.is_file() and not entry.is_symlink():
                    entry.unlink()

    def valid(self, path):
        try:
            info = path.lstat()
        except OSError:
            return False
        return stat.S_ISREG(info.st_mode) and info.st_uid == os.getuid() and 0 < info.st_size <= MAX_IMAGE

    def url(self, name):
        return (self.directory / name).as_uri() if name else ""

    def fond(self):
        if self.default_mode != "fond":
            return ""
        path = Path.home() / "Pictures" / "fond.jpg"
        return path.as_uri() if path.is_file() else ""

    def stage(self, source):
        if not isinstance(source, str) or not source.startswith("/") or "\0" in source:
            raise ValueError("Chemin local invalide")
        fd = os.open(source, os.O_RDONLY | os.O_NONBLOCK | os.O_CLOEXEC)
        try:
            info = os.fstat(fd)
            if not stat.S_ISREG(info.st_mode):
                raise ValueError("Ce n’est pas un fichier image")
            if not 0 < info.st_size <= MAX_IMAGE:
                raise ValueError("Image vide ou trop lourde (64 Mo max)")
            chunks = []
            remaining = MAX_IMAGE + 1
            while remaining > 0:
                chunk = os.read(fd, min(1048576, remaining))
                if not chunk:
                    break
                chunks.append(chunk)
                remaining -= len(chunk)
            data = b"".join(chunks)
        finally:
            os.close(fd)
        if not 0 < len(data) <= MAX_IMAGE:
            raise ValueError("Image vide ou trop lourde (64 Mo max)")
        kind = image_kind(data[:16])
        if kind is None:
            raise ValueError("Format non reconnu (JPEG, PNG, WebP, GIF, BMP)")
        name = "wallpaper-" + hashlib.sha256(data).hexdigest()[:32] + "." + kind
        target = self.directory / name
        if not (self.valid(target) and target.read_bytes() == data):
            atomic_write(self.directory, name, data)
        token = secrets.token_hex(8)
        self.pending[token] = name
        return token, name

    def commit(self, token):
        name = self.pending.pop(token, None)
        if not name or not self.valid(self.directory / name):
            raise ValueError("Choix expiré")
        atomic_write(self.directory, "choice.json",
                     (json.dumps({"version": 1, "file": name}) + "\n").encode())
        previous, self.current = self.current, name
        self.discard_unused(previous)

    def discard(self, token):
        name = self.pending.pop(token, None)
        if name:
            self.discard_unused(name)

    def reset(self):
        atomic_write(self.directory, "choice.json", (json.dumps({"version": 1, "file": None}) + "\n").encode())
        previous, self.current = self.current, None
        self.discard_unused(previous)

    def discard_unused(self, name):
        if name and name != self.current and name not in self.pending.values():
            path = self.directory / name
            if self.valid(path):
                path.unlink()


WIDGET_KINDS = ("clock", "calendar", "battery", "notes", "media", "system", "photos", "todo")
MAC_KINDS = {"weather": ("liquid", "normal"), "calendar": ("liquid", "normal"), "clock": ("liquid", "light", "dark"),
             "player": ("liquid", "light", "dark"), "activity": ("liquid", "normal"), "batteries": ("liquid", "normal"),
             "timer": ("liquid", "normal"), "notes": ("liquid", "normal"), "reminders": ("liquid", "normal"),
             "image": ("liquid", "normal")}
LEGACY_KINDS = {"clock": "clock", "calendar": "calendar", "battery": "batteries", "notes": "notes", "todo": "reminders",
                "media": "player", "system": "activity", "photos": "image"}
WMO = {0: ("Ensoleillé", "Dégagé", "sun", "moon"), 1: ("Plutôt ensoleillé", "Plutôt dégagé", "sun", "moon"),
       2: ("Partiellement nuageux",) * 2 + ("partly", "partlyNight"), 3: ("Nuageux",) * 2 + ("cloud",) * 2,
       45: ("Brouillard",) * 2 + ("fog",) * 2, 48: ("Brouillard",) * 2 + ("fog",) * 2,
       51: ("Bruine",) * 2 + ("rain",) * 2, 53: ("Bruine",) * 2 + ("rain",) * 2, 55: ("Bruine",) * 2 + ("rain",) * 2,
       56: ("Bruine verglaçante",) * 2 + ("rain",) * 2, 57: ("Bruine verglaçante",) * 2 + ("rain",) * 2,
       61: ("Pluie légère",) * 2 + ("rain",) * 2, 63: ("Pluie",) * 2 + ("rain",) * 2, 65: ("Forte pluie",) * 2 + ("rain",) * 2,
       66: ("Pluie verglaçante",) * 2 + ("rain",) * 2, 67: ("Pluie verglaçante",) * 2 + ("rain",) * 2,
       71: ("Neige légère",) * 2 + ("snow",) * 2, 73: ("Neige",) * 2 + ("snow",) * 2, 75: ("Forte neige",) * 2 + ("snow",) * 2,
       77: ("Forte neige",) * 2 + ("snow",) * 2, 80: ("Averses",) * 2 + ("rain",) * 2, 81: ("Averses",) * 2 + ("rain",) * 2,
       82: ("Fortes averses",) * 2 + ("rain",) * 2, 85: ("Averses de neige",) * 2 + ("snow",) * 2,
       86: ("Averses de neige",) * 2 + ("snow",) * 2, 95: ("Orages",) * 2 + ("storm",) * 2, 96: ("Orages",) * 2 + ("storm",) * 2,
       99: ("Orages",) * 2 + ("storm",) * 2}
DAYS = ("Lun", "Mar", "Mer", "Jeu", "Ven", "Sam", "Dim")


def load_json(directory, name, limit=262144):
    path = directory / name
    try:
        info = path.lstat()
        if not stat.S_ISREG(info.st_mode) or info.st_uid != os.getuid() or info.st_size > limit:
            return None
        return json.loads(path.read_text())
    except (OSError, ValueError):
        return None


def clean_widgets(value):
    result = []
    if not isinstance(value, list):
        return result
    for item in value[:24]:
        if not isinstance(item, dict) or item.get("kind") not in WIDGET_KINDS:
            continue
        try:
            x, y = int(item.get("x", 0)), int(item.get("y", 0))
        except (TypeError, ValueError):
            continue
        result.append({"id": str(item.get("id", ""))[:32] or secrets.token_hex(4), "kind": item["kind"],
                       "size": "medium" if item.get("size") == "medium" else "small",
                       "x": max(0, min(10000, x)), "y": max(0, min(10000, y))})
    return result


def clean_path(value):
    if not isinstance(value, str) or len(value) > 4096 or any(ord(c) < 32 for c in value):
        return ""
    value = value.strip()
    if value.startswith("file://"):
        value = urllib.parse.unquote(value[7:])
    return value if value.startswith("/") and ".." not in Path(value).parts else ""


def clean_mac_widgets(value):
    result = []
    if not isinstance(value, list):
        return result
    for item in value[:24]:
        if not isinstance(item, dict) or item.get("kind") not in MAC_KINDS:
            continue
        try:
            x, y = int(item.get("x", 0)), int(item.get("y", 0))
        except (TypeError, ValueError):
            continue
        kind = item["kind"]
        settings = item.get("settings") if isinstance(item.get("settings"), dict) else {}
        clean_settings = {}
        if kind == "activity" and settings.get("view") in ("rings", "graphs"):
            clean_settings["view"] = settings["view"]
        if kind == "image" and clean_path(settings.get("path")):
            clean_settings["path"] = clean_path(settings.get("path"))
        result.append({"id": re.sub(r"[^0-9a-zA-Z]", "", str(item.get("id", "")))[:32] or secrets.token_hex(4),
                       "kind": kind, "size": item.get("size") if item.get("size") in ("small", "medium", "large") else "small",
                       "style": item.get("style") if item.get("style") in MAC_KINDS[kind] else MAC_KINDS[kind][0],
                       "theme": "light" if item.get("theme") == "light" else "dark",
                       "x": max(0, min(10000, x)), "y": max(0, min(10000, y)), "settings": clean_settings})
    return result


def migrate_widgets(old, photos):
    result = []
    for item in clean_widgets(old):
        kind = LEGACY_KINDS[item["kind"]]
        settings = {"path": urllib.parse.unquote(photos[0][7:])} if kind == "image" and photos else {}
        result.append({"id": item["id"], "kind": kind, "size": item["size"], "style": "liquid", "theme": "dark",
                       "x": item["x"], "y": item["y"], "settings": settings})
    return clean_mac_widgets(result)


def clean_weather_settings(value):
    value = value if isinstance(value, dict) else {}
    city = clean(str(value.get("city", "")))[:80].strip()
    return {"mode": "city" if value.get("mode") == "city" and city else "auto", "city": city,
            "unit": "F" if value.get("unit") == "F" else "C"}


def fetch_json(url, parameters):
    import urllib.request
    request_url = url + "?" + urllib.parse.urlencode(parameters) if parameters else url
    query = urllib.request.Request(request_url, headers={"User-Agent": "cm1406-vitrum-plus (quickshell)",
                                                         "Accept": "application/json"})
    with urllib.request.urlopen(query, timeout=8) as response:
        data = response.read(1048577)
    if len(data) > 1048576:
        raise ValueError("Réponse trop grande")
    return json.loads(data)


def coordinates(value):
    latitude, longitude = float(value["latitude"]), float(value["longitude"])
    if not (math.isfinite(latitude) and math.isfinite(longitude) and -90 <= latitude <= 90 and -180 <= longitude <= 180):
        raise ValueError("Coordonnées invalides")
    return latitude, longitude


def weather_fetch(settings):
    if settings["mode"] == "city":
        location = fetch_json("https://geocoding-api.open-meteo.com/v1/search",
                              {"name": settings["city"], "count": 1, "language": "fr", "format": "json"})["results"][0]
        place, located = location["name"], False
    else:
        try:
            location = fetch_json("https://ipwho.is/", None)
            coordinates(location)
        except (OSError, ValueError, KeyError, TypeError):
            location = fetch_json("https://ipapi.co/json/", None)
        place, located = location.get("city") or location.get("region") or location.get("country") or "Ici", True
    latitude, longitude = coordinates(location)
    forecast = fetch_json("https://api.open-meteo.com/v1/forecast", {
        "latitude": latitude, "longitude": longitude, "current": "temperature_2m,weather_code,is_day",
        "hourly": "temperature_2m,weather_code,is_day", "daily": "temperature_2m_max,temperature_2m_min,weather_code",
        "temperature_unit": "fahrenheit" if settings["unit"] == "F" else "celsius", "timezone": "auto", "forecast_days": 6})
    return weather_view(forecast, place, located)


def wmo(code, day):
    entry = WMO.get(code, ("Nuageux", "Nuageux", "cloud", "cloud"))
    return (entry[0], entry[2]) if day else (entry[1], entry[3])


def weather_view(o, place, located):
    current = o["current"]
    day = current.get("is_day") == 1
    cond, kind = wmo(current["weather_code"], day)
    hours, times = [], o["hourly"]["time"]
    start = next((i for i, t in enumerate(times) if t[:13] == str(current["time"])[:13]), 0)
    for i in range(start, min(len(times), start + 6)):
        hours.append({"h": "Maint." if not hours else str(int(times[i][11:13])) + " h",
                      "t": round(o["hourly"]["temperature_2m"][i]), "k": wmo(o["hourly"]["weather_code"][i], o["hourly"]["is_day"][i] == 1)[1]})
    days = []
    for i, date in enumerate(o["daily"]["time"][:5]):
        label = "Aujourd’hui" if i == 0 else DAYS[time.strptime(date, "%Y-%m-%d").tm_wday]
        days.append({"d": label, "lo": round(o["daily"]["temperature_2m_min"][i]), "hi": round(o["daily"]["temperature_2m_max"][i]),
                     "k": wmo(o["daily"]["weather_code"][i], True)[1]})
    return {"ready": True, "city": clean(str(place))[:60], "located": located, "temp": round(current["temperature_2m"]),
            "hi": round(o["daily"]["temperature_2m_max"][0]), "lo": round(o["daily"]["temperature_2m_min"][0]),
            "cond": cond, "kind": kind, "day": day, "hourly": hours, "daily": days}


def weather_child(settings):
    try:
        print(json.dumps(weather_fetch(settings), ensure_ascii=False), flush=True)
    except Exception:
        print(json.dumps({"ready": False, "error": "offline"}), flush=True)


def net_bytes(base=Path("/sys/class/net")):
    best = None
    for device in sorted(base.glob("*")):
        if device.name == "lo" or "/virtual/" in str(device.resolve()):
            continue
        if read(device / "operstate") != "up":
            continue
        rx, tx = read(device / "statistics/rx_bytes"), read(device / "statistics/tx_bytes")
        if rx.isdigit() and tx.isdigit() and (best is None or int(rx) > best[1]):
            best = (device.name, int(rx), int(tx))
    return best


def disk_bytes():
    best = None
    try:
        for line in Path("/proc/diskstats").read_text().splitlines():
            parts = line.split()
            if len(parts) < 10 or not re.fullmatch(r"(mmcblk\d+|nvme\d+n\d+|sd[a-z]+|vd[a-z]+)", parts[2]):
                continue
            read_bytes, written = int(parts[5]) * 512, int(parts[9]) * 512
            if best is None or read_bytes + written > best[1] + best[2]:
                best = (parts[2], read_bytes, written)
    except (OSError, ValueError):
        return None
    return best


def memory_bytes():
    info = {}
    try:
        for line in Path("/proc/meminfo").read_text().splitlines():
            key, _, value = line.partition(":")
            info[key] = int(value.split()[0]) * 1024
        return {"used": info["MemTotal"] - info["MemAvailable"], "total": info["MemTotal"]}
    except (OSError, ValueError, KeyError, IndexError):
        return None


def battery_entries(base=Path("/sys/class/power_supply")):
    for device in sorted(base.glob("*")):
        if read(device / "type") != "Battery" or read(device / "scope") == "Device" or read(device / "present") == "0":
            continue
        capacity = read(device / "capacity")
        status = read(device / "status")
        value = int(capacity) if capacity.isdigit() and int(capacity) <= 100 else -1
        return [{"id": "laptop", "name": "Laptop", "label": "Laptop", "kind": "laptop", "present": True, "connected": True,
                 "percentage": value, "left": -1, "right": -1, "caseCharge": -1, "status": "connected",
                 "charging": status == "Charging", "full": status == "Full" or value == 100, "detail": ""}]
    return []


def clock_city():
    try:
        zone = os.readlink("/etc/localtime").split("zoneinfo/", 1)[1]
    except (OSError, IndexError):
        zone = os.environ.get("TZ", "")
    city = re.sub(r"[^A-Za-z]", "", zone.rsplit("/", 1)[-1])
    return city[:3].upper() or "PAR"


def clean_todo(value):
    if not isinstance(value, list):
        return []
    return [{"text": clean(str(i.get("text", "")))[:120], "done": bool(i.get("done"))}
            for i in value[:50] if isinstance(i, dict) and str(i.get("text", "")).strip()]


def photo_list(home):
    folder = home / "Pictures"
    found = []
    try:
        for path in sorted(folder.iterdir())[:500]:
            if path.suffix.lower() in (".jpg", ".jpeg", ".png", ".webp") and path.is_file() and not path.is_symlink():
                found.append(path.as_uri())
    except OSError:
        return []
    return found[:60]


def data_dirs():
    paths = [os.environ.get("XDG_DATA_HOME") or str(Path.home() / ".local/share")]
    paths += (os.environ.get("XDG_DATA_DIRS") or "/usr/local/share:/usr/share").split(":")
    return list(dict.fromkeys(Path(p) for p in paths if p and Path(p).is_absolute()))


def clean(text):
    return "".join(c if c.isprintable() else " " for c in text)[:80]


def program_identity(command):
    try:
        argv = [a for a in shlex.split(command) if not FIELD_CODE.fullmatch(a)]
    except ValueError:
        return ""
    while argv:
        base = os.path.basename(argv[0])
        if base == "env":
            argv = argv[1:]
            while argv and ("=" in argv[0] or argv[0].startswith("-")):
                argv = argv[2:] if argv[0] in ("-u", "--unset", "-C", "--chdir", "-S", "--split-string") else argv[1:]
        elif base == "gpuapp":
            argv = argv[1:]
            if argv and argv[0] == "--":
                argv = argv[1:]
        elif base == "flatpak" and len(argv) > 1 and argv[1] == "run":
            rest = [a for a in argv[2:] if not a.startswith("-")]
            return rest[0].lower() if rest else ""
        elif base in ("sh", "bash", "dash"):
            return ""
        else:
            return base.lower()
    return ""


def icon_value(raw):
    raw = clean(raw).strip()
    if raw.startswith("/"):
        return raw if Path(raw).is_file() else ""
    return raw if re.fullmatch(r"[A-Za-z0-9_.+-]{1,80}", raw) else ""


def desktop_entry(key):
    if not key or "/" in key or key.startswith(".") or not key.endswith(".desktop"):
        return None
    for base in data_dirs():
        directory = base / "applications"
        candidates = [directory / key]
        parts = key.split("-")
        for split in range(1, len(parts)):
            candidates.append(directory / "/".join(parts[:split]) / "-".join(parts[split:]))
        found = [p for p in candidates if p.is_file()]
        if not found:
            continue
        path = found[0]
        parser = configparser.ConfigParser(interpolation=None, strict=True)
        parser.optionxform = str
        try:
            parser.read_string(path.read_text())
            entry = parser["Desktop Entry"]
            if entry.get("Type") != "Application" or entry.getboolean("Hidden", False):
                return None
            executable = entry.get("TryExec", "")
            if executable and not shutil.which(executable):
                return None
            locale = (os.environ.get("LC_ALL") or os.environ.get("LC_MESSAGES") or os.environ.get("LANG", "")).split(".")[0]
            names = ["Name[" + n + "]" for n in dict.fromkeys([locale, locale.split("@")[0], locale.split("_")[0]]) if n]
            name = next((entry[n] for n in names if n in entry), entry.get("Name", ""))
            if not name:
                return None
            ids = {key[:-8].lower()}
            program = program_identity(entry.get("Exec", ""))
            if program:
                ids.add(program)
            wm_class = entry.get("StartupWMClass", "").strip().lower()
            if wm_class:
                ids.add(wm_class)
            return {"path": str(path), "name": clean(name), "icon": icon_value(entry.get("Icon", "")),
                    "program": program, "ids": ids}
        except (OSError, UnicodeError, ValueError, configparser.Error, KeyError):
            return None
    return None


def pinned_keys():
    root = os.environ.get("VP_PINS_ROOT", "")
    if not root:
        return []
    pins_file = Path(root) / "pins.json"
    try:
        info = pins_file.lstat()
        if not stat.S_ISREG(info.st_mode) or info.st_uid != os.getuid() or info.st_size > 262144:
            return []
        pins = json.loads(pins_file.read_text())
    except (OSError, ValueError):
        return []
    if not isinstance(pins, list):
        return []
    return [k for k in pins[:24] if isinstance(k, str) and k.startswith("desktop:")]


def firefox_gpu():
    if not shutil.which("gtk-launch"):
        return False
    return any((base / "applications" / "firefox-gpu.desktop").is_file() for base in data_dirs())


def builtin_apps():
    gpu = os.access("/usr/local/bin/gpuapp", os.X_OK) and shutil.which("kitty") is not None
    firefox = firefox_gpu()
    apps = [
        {"key": "builtin:apps", "name": "Applications", "program": "fuzzel", "glyph": "apps",
         "icons": ["view-app-grid", "view-app-grid-symbolic", "applications-all", "start-here"],
         "command": ["fuzzel"], "ids": set(), "available": True},
        {"key": "builtin:kitty", "name": "Kitty", "program": "kitty", "glyph": "terminal",
         "icons": ["kitty", "utilities-terminal"],
         "command": ["/usr/local/bin/gpuapp", "kitty"] if gpu else ["kitty"], "ids": {"kitty"},
         "available": shutil.which("kitty") is not None},
        {"key": "builtin:firefox", "name": "Firefox", "program": "firefox", "glyph": "web",
         "icons": ["firefox", "org.mozilla.firefox"],
         "command": ["gtk-launch", "firefox-gpu"] if firefox else ["firefox"],
         "ids": {"firefox", "org.mozilla.firefox", "firefox-gpu"},
         "available": firefox or shutil.which("firefox") is not None},
        {"key": "builtin:files", "name": "Fichiers", "program": "pcmanfm", "glyph": "files",
         "icons": ["system-file-manager", "pcmanfm", "file-manager", "folder"],
         "command": ["pcmanfm"], "ids": {"pcmanfm", "pcmanfm-qt"},
         "available": shutil.which("pcmanfm") is not None},
    ]
    return [a for a in apps if a["available"]]


def dock_apps():
    apps = builtin_apps()
    for key in pinned_keys():
        entry = desktop_entry(key[8:])
        if not entry:
            continue
        twin = next((a for a in apps if entry["program"] and entry["program"] == a["program"]
                     or entry["ids"] & a["ids"]), None)
        if twin:
            twin["ids"] |= entry["ids"] - {""}
            if entry["icon"] and entry["icon"] not in twin["icons"]:
                twin["icons"].append(entry["icon"])
            continue
        apps.append({"key": key, "name": entry["name"], "program": entry["program"], "glyph": "app",
                     "icons": [entry["icon"]] if entry["icon"] else [], "desktop": entry["path"],
                     "ids": entry["ids"], "available": True})
    return apps


class Extras:
    def __init__(self):
        self.cache = {}
        self.groups = {}

    def lookup(self, app_id):
        if app_id not in self.cache:
            entry = None
            if re.fullmatch(r"[A-Za-z0-9_.+-]{1,120}", app_id):
                for candidate in dict.fromkeys([app_id + ".desktop", app_id.lower() + ".desktop"]):
                    entry = desktop_entry(candidate)
                    if entry:
                        break
            self.cache[app_id] = entry
        return self.cache[app_id]


def timestamp(window):
    stamp = window.get("focus_timestamp")
    if not isinstance(stamp, dict):
        return (0, 0)
    secs, nanos = stamp.get("secs"), stamp.get("nanos")
    return (secs if isinstance(secs, int) else 0, nanos if isinstance(nanos, int) else 0)


def app_id_of(window):
    value = window.get("app_id")
    return value if isinstance(value, str) else ""


def title_of(window):
    value = window.get("title")
    return value if isinstance(value, str) else ""


def matching(app, windows):
    return [w for w in windows.values() if app_id_of(w).lower() in app["ids"]]


def dock_state(apps, windows, extras):
    items = []
    claimed = set()
    for app in apps:
        found = matching(app, windows)
        claimed.update(w["id"] for w in found)
        items.append({"key": app["key"], "name": app["name"], "icons": app["icons"], "glyph": app["glyph"],
                      "running": len(found), "focused": any(w.get("is_focused") for w in found),
                      "urgent": any(w.get("is_urgent") for w in found), "launchable": True, "pinned": True})
    groups = {}
    for window in sorted(windows.values(), key=lambda w: w["id"]):
        if window["id"] in claimed:
            continue
        groups.setdefault(app_id_of(window).lower(), []).append(window)
    for group, found in groups.items():
        app_id = app_id_of(found[0])
        entry = extras.lookup(app_id) if app_id else None
        extras.groups[group] = entry
        name = entry["name"] if entry else clean(app_id or title_of(found[0]) or "Fenêtre")
        icons = ([entry["icon"]] if entry and entry["icon"] else []) + ([app_id] if app_id else [])
        items.append({"key": "window:" + group, "name": name, "icons": icons, "glyph": "app",
                      "running": len(found), "focused": any(w.get("is_focused") for w in found),
                      "urgent": any(w.get("is_urgent") for w in found), "launchable": bool(entry),
                      "pinned": False})
    return items


def window_group(key, apps, windows):
    if key.startswith("window:"):
        group = key[7:]
        claimed = {w["id"] for app in apps for w in matching(app, windows)}
        return [w for w in windows.values() if w["id"] not in claimed and app_id_of(w).lower() == group]
    app = next((a for a in apps if a["key"] == key), None)
    return matching(app, windows) if app else []


def pick_window(found):
    ordered = sorted(found, key=lambda w: w["id"])
    focused = next((i for i, w in enumerate(ordered) if w.get("is_focused")), None)
    if focused is not None:
        return ordered[(focused + 1) % len(ordered)]
    return max(found, key=timestamp)


def app_environment():
    return {k: v for k, v in os.environ.items() if not k.startswith("VP_")}


def spawn(command):
    subprocess.Popen(command, stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL,
                     stderr=subprocess.DEVNULL, start_new_session=True, env=app_environment())


def launch(key, apps, extras):
    if key.startswith("window:"):
        entry = extras.groups.get(key[7:])
        if not entry or not shutil.which("gio"):
            raise ValueError("Application indisponible")
        spawn(["gio", "launch", entry["path"]])
        return
    app = next((a for a in apps if a["key"] == key), None)
    if not app:
        raise ValueError("Application indisponible")
    if "desktop" in app:
        if not shutil.which("gio"):
            raise ValueError("Application indisponible")
        spawn(["gio", "launch", app["desktop"]])
    else:
        spawn(app["command"])


def media_process():
    if not shutil.which("playerctl"):
        return None
    try:
        return subprocess.Popen(["playerctl", "--follow", "metadata", "--format",
                                 "{{status}}\t{{artist}}\t{{title}}\t{{playerName}}\t{{album}}\t{{mpris:artUrl}}"],
                                stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
    except OSError:
        return None


def parse_media(line):
    parts = line.decode("utf-8", "replace").rstrip("\n").split("\t")
    if len(parts) < 3 or parts[0] not in ("Playing", "Paused"):
        return {}
    art = parts[5] if len(parts) > 5 else ""
    path = clean_path(art) if art.startswith("file:///") else ""
    return {"status": parts[0], "artist": clean(parts[1]), "title": clean(parts[2]),
            "album": clean(parts[4]) if len(parts) > 4 else "",
            "art": Path(path).as_uri() if path and Path(path).is_file() else ""}


def battery_time(base=Path("/sys/class/power_supply")):
    for device in sorted(base.glob("*")):
        if read(device / "type") != "Battery" or read(device / "scope") == "Device" or read(device / "present") == "0":
            continue
        status = read(device / "status")
        now = read(device / "energy_now") or read(device / "charge_now")
        full = read(device / "energy_full") or read(device / "charge_full")
        rate = read(device / "power_now") or read(device / "current_now")
        if not (now.isdigit() and full.isdigit() and rate.lstrip("-").isdigit()) or abs(int(rate)) < 1000:
            return ""
        if status == "Discharging":
            hours = int(now) / abs(int(rate))
        elif status == "Charging":
            hours = max(0, int(full) - int(now)) / abs(int(rate))
        else:
            return ""
        if not 0 < hours < 48:
            return ""
        minutes = round(hours * 60)
        text = f"{minutes // 60} h {minutes % 60:02d}" if minutes >= 60 else f"{minutes} min"
        return text + (" avant la charge complète" if status == "Charging" else " restantes")
    return ""


def keyboard_light(base=SYS_CLASS / "leds"):
    try:
        found = sorted(base.glob("*kbd_backlight*"))
    except OSError:
        found = []
    for device in found:
        now, top = read(device / "brightness"), read(device / "max_brightness")
        if now.isdigit() and top.isdigit() and int(top) > 0:
            return {"device": device.name, "path": str(device), "level": round(100 * int(now) / int(top))}
    return {"device": "", "path": "", "level": -1}


def launchers(apps):
    found = {}
    for app in apps:
        if "desktop" in app:
            if shutil.which("gio"):
                found[app["key"]] = ["gio", "launch", app["desktop"]]
        elif isinstance(app.get("command"), list) and app["command"]:
            found[app["key"]] = [str(part) for part in app["command"]]
    return found


def run_tool(command, timeout=8, stdin=None):
    try:
        result = subprocess.run(command, capture_output=True, text=True, timeout=timeout, input=stdin)
    except (OSError, subprocess.SubprocessError):
        return 127, ""
    return result.returncode, (result.stdout or "") + (result.stderr or "")


def wifi_interface(base=Path("/sys/class/net")):
    for device in sorted(base.glob("*")):
        if (device / "wireless").exists() and re.fullmatch(r"[A-Za-z0-9_.-]{1,15}", device.name):
            return device.name
    return ""


def wpa_socket(iface):
    for folder in ("/run/wpa_supplicant", "/var/run/wpa_supplicant"):
        path = Path(folder) / iface
        try:
            if stat.S_ISSOCK(path.stat().st_mode):
                return path
        except OSError:
            continue
    return None


def wifi_backend():
    iface = wifi_interface()
    if shutil.which("nmcli"):
        code, out = run_tool(["nmcli", "-t", "-f", "RUNNING", "general"], 3)
        if code == 0 and out.strip().startswith("running"):
            return {"name": "nm", "iface": iface, "label": "NetworkManager"}
    if shutil.which("iwctl") and iface:
        code, out = run_tool(["iwctl", "station", "list"], 3)
        if code == 0 and iface in out:
            return {"name": "iwd", "iface": iface, "label": "iwd"}
    if shutil.which("wpa_cli") and iface:
        sock = wpa_socket(iface)
        if sock is not None:
            if not os.access(sock, os.W_OK):
                return {"name": "none", "iface": iface, "label": "wpa_supplicant",
                        "error": "wpa_supplicant refuse l’accès : lancer l’installateur avec --wifi-access --apply"}
            return {"name": "wpa", "iface": iface, "label": "wpa_supplicant"}
    if not iface:
        return {"name": "none", "iface": "", "label": "", "error": "Aucune carte Wi-Fi"}
    return {"name": "none", "iface": iface, "label": "", "error": "Aucun service Wi-Fi (NetworkManager, iwd ou wpa_supplicant)"}


def split_escaped(line, separator=":"):
    fields, current, escape = [], "", False
    for char in line:
        if escape:
            current += char
            escape = False
        elif char == "\\":
            escape = True
        elif char == separator:
            fields.append(current)
            current = ""
        else:
            current += char
    fields.append(current)
    return fields


def wpa_unescape(text):
    out = bytearray()
    index = 0
    raw = text.encode("utf-8", "surrogateescape")
    while index < len(raw):
        byte = raw[index]
        if byte == 0x5C and index + 1 < len(raw):
            following = raw[index + 1]
            if following == 0x78 and index + 3 < len(raw):
                try:
                    out.append(int(raw[index + 2:index + 4].decode(), 16))
                    index += 4
                    continue
                except ValueError:
                    pass
            mapping = {0x6E: 0x0A, 0x72: 0x0D, 0x74: 0x09, 0x65: 0x1B}
            out.append(mapping.get(following, following))
            index += 2
            continue
        out.append(byte)
        index += 1
    return out.decode("utf-8", "replace")


def merge_networks(found):
    best = {}
    for item in found:
        if not item["ssid"]:
            continue
        old = best.get(item["ssid"])
        if old is None or item["active"] or (not old["active"] and item["signal"] > old["signal"]):
            merged = dict(item)
            if old:
                merged["known"] = merged["known"] or old["known"]
            best[item["ssid"]] = merged
        else:
            old["known"] = old["known"] or item["known"]
    return sorted(best.values(), key=lambda n: (not n["active"], not n["known"], -n["signal"], n["ssid"].lower()))[:30]


def nm_scan(iface, rescan=True):
    code, out = run_tool(["nmcli", "-t", "-e", "yes", "-f", "IN-USE,SSID,SIGNAL,SECURITY", "device", "wifi", "list"]
                         + (["--rescan", "yes"] if rescan else []), 20)
    if code != 0:
        return None
    known = set()
    code2, saved = run_tool(["nmcli", "-t", "-e", "yes", "-f", "NAME,TYPE", "connection", "show"], 5)
    for line in saved.splitlines():
        fields = split_escaped(line)
        if len(fields) >= 2 and fields[1] == "802-11-wireless":
            known.add(fields[0])
    found = []
    for line in out.splitlines():
        fields = split_escaped(line)
        if len(fields) < 4:
            continue
        signal = int(fields[2]) if fields[2].isdigit() else 0
        security = fields[3].strip()
        found.append({"ssid": clean(fields[1])[:64] if fields[1] else "", "raw": fields[1], "signal": signal,
                      "secure": security not in ("", "--"), "active": fields[0].strip() == "*",
                      "known": fields[1] in known})
    return found


def strip_ansi(text):
    return re.sub(r"\x1b\[[0-9;]*[A-Za-z]", "", text)


def iwd_scan(iface, rescan=True):
    if rescan:
        run_tool(["iwctl", "station", iface, "scan"], 10)
        time.sleep(3)
    code, out = run_tool(["iwctl", "station", iface, "get-networks"], 10)
    if code != 0:
        return None
    code2, saved = run_tool(["iwctl", "known-networks", "list"], 5)
    known_lines = [strip_ansi(l) for l in saved.splitlines()]
    found = []
    started = False
    for raw in out.splitlines():
        line = strip_ansi(raw).rstrip()
        if re.fullmatch(r"\s*-{6,}\s*", line):
            started = True
            continue
        if not started or not line.strip():
            continue
        active = line.lstrip().startswith(">")
        body = line.lstrip()[1:] if active else line
        parts = [p for p in re.split(r"\s{2,}", body.strip()) if p]
        if len(parts) < 2:
            continue
        ssid, security = parts[0], parts[1]
        signal = min(100, raw.count("*") * 25) if "*" in raw else 50
        found.append({"ssid": clean(ssid)[:64], "raw": ssid, "signal": signal, "secure": security not in ("open",),
                      "active": active, "known": any(re.match(r"\s*" + re.escape(ssid) + r"\s{2,}", k) for k in known_lines)})
    return found


def wpa(iface, *arguments, timeout=5):
    return run_tool(["wpa_cli", "-i", iface] + [str(a) for a in arguments], timeout)


def wpa_saved(iface):
    code, out = wpa(iface, "list_networks")
    saved = []
    for line in out.splitlines()[1:]:
        fields = line.split("\t")
        if len(fields) >= 2 and fields[0].isdigit():
            saved.append({"id": fields[0], "ssid": wpa_unescape(fields[1]), "flags": fields[3] if len(fields) > 3 else ""})
    return saved


def wpa_status(iface):
    code, out = wpa(iface, "status")
    values = {}
    for line in out.splitlines():
        key, _, value = line.partition("=")
        values[key] = value
    return values


def wpa_scan(iface, rescan=True):
    if rescan:
        code, out = wpa(iface, "scan")
        if code != 0 or "FAIL-BUSY" not in out and "OK" not in out:
            return None
        time.sleep(4)
    code, out = wpa(iface, "scan_results")
    if code != 0:
        return None
    current = wpa_status(iface)
    saved = {n["ssid"] for n in wpa_saved(iface)}
    found = []
    for line in out.splitlines()[1:]:
        fields = line.split("\t")
        if len(fields) < 5:
            continue
        ssid = wpa_unescape(fields[4])
        try:
            level = int(fields[2])
        except ValueError:
            level = -90
        signal = max(0, min(100, 2 * (level + 100))) if level < 0 else min(100, level)
        flags = fields[3]
        found.append({"ssid": clean(ssid)[:64], "raw": ssid, "signal": signal,
                      "secure": any(k in flags for k in ("WPA", "WEP", "SAE", "RSN")),
                      "active": current.get("wpa_state") == "COMPLETED" and wpa_unescape(current.get("ssid", "")) == ssid,
                      "known": ssid in saved})
    return found


def wifi_scan(backend, rescan=True):
    scanner = {"nm": nm_scan, "iwd": iwd_scan, "wpa": wpa_scan}.get(backend["name"])
    if scanner is None:
        return {"ok": False, "message": backend.get("error", "Wi-Fi indisponible"), "networks": []}
    found = scanner(backend["iface"], rescan)
    if found is None:
        return {"ok": False, "message": "Recherche impossible", "networks": []}
    return {"ok": True, "message": "", "networks": merge_networks(found)}


def wifi_connect(backend, ssid, password, hidden):
    name, iface = backend["name"], backend["iface"]
    if not isinstance(ssid, str) or not 0 < len(ssid.encode()) <= 32:
        return {"ok": False, "message": "Nom de réseau invalide"}
    if password and not 8 <= len(password) <= 63:
        return {"ok": False, "message": "Le mot de passe doit faire 8 à 63 caractères", "ask": True}
    if name == "nm":
        code, saved = run_tool(["nmcli", "-t", "-e", "yes", "-f", "NAME,TYPE", "connection", "show"], 5)
        known = any(split_escaped(l)[:2] == [ssid, "802-11-wireless"] for l in saved.splitlines())
        if known and not password:
            code, out = run_tool(["nmcli", "--wait", "30", "connection", "up", "id", ssid], 40)
        else:
            command = ["nmcli", "--wait", "30", "device", "wifi", "connect", ssid]
            if password:
                command += ["password", password]
            if hidden:
                command += ["hidden", "yes"]
            if iface:
                command += ["ifname", iface]
            code, out = run_tool(command, 40)
        if code == 0:
            return {"ok": True, "message": "Connecté à " + clean(ssid)}
        wrong = "secrets" in out.lower() or "password" in out.lower() or "802-1x" in out.lower()
        if wrong and not known:
            run_tool(["nmcli", "connection", "delete", "id", ssid], 5)
        return {"ok": False, "message": "Mot de passe incorrect ?" if wrong else "Connexion impossible", "ask": wrong}
    if name == "iwd":
        command = ["iwctl"] + (["--passphrase", password] if password else []) + ["station", iface,
                   "connect-hidden" if hidden else "connect", ssid]
        code, out = run_tool(command, 40)
        if code == 0:
            return {"ok": True, "message": "Connecté à " + clean(ssid)}
        wrong = "passphrase" in out.lower() or "failed" in out.lower()
        return {"ok": False, "message": "Mot de passe incorrect ?" if wrong else "Connexion impossible", "ask": wrong}
    if name == "wpa":
        existing = next((n for n in wpa_saved(iface) if n["ssid"] == ssid), None)
        created = None
        if existing and not password:
            network = existing["id"]
        else:
            code, out = wpa(iface, "add_network")
            network = out.strip().splitlines()[-1].strip() if code == 0 and out.strip() else ""
            if not network.isdigit():
                return {"ok": False, "message": "wpa_supplicant refuse la commande"}
            created = network
            steps = [("ssid", ssid.encode().hex())]
            steps += [("psk", '"' + password + '"')] if password else [("key_mgmt", "NONE")]
            if hidden:
                steps.append(("scan_ssid", "1"))
            for key, value in steps:
                code, out = wpa(iface, "set_network", network, key, value)
                if code != 0 or "OK" not in out:
                    wpa(iface, "remove_network", network)
                    return {"ok": False, "message": "Réglage refusé par wpa_supplicant"}
        wpa(iface, "select_network", network)
        deadline = time.monotonic() + 20
        state = {}
        while time.monotonic() < deadline:
            time.sleep(1)
            state = wpa_status(iface)
            if state.get("wpa_state") == "COMPLETED" and wpa_unescape(state.get("ssid", "")) == ssid:
                break
        connected = state.get("wpa_state") == "COMPLETED" and wpa_unescape(state.get("ssid", "")) == ssid
        if not connected and created is not None:
            wpa(iface, "remove_network", created)
        wpa(iface, "enable_network", "all")
        if connected:
            wpa(iface, "save_config")
            return {"ok": True, "message": "Connecté à " + clean(ssid)}
        return {"ok": False, "message": "Mot de passe incorrect ?" if password else "Connexion impossible", "ask": bool(password)}
    return {"ok": False, "message": backend.get("error", "Wi-Fi indisponible")}


def wifi_forget(backend, ssid):
    name, iface = backend["name"], backend["iface"]
    if name == "nm":
        code, out = run_tool(["nmcli", "connection", "delete", "id", ssid], 10)
    elif name == "iwd":
        code, out = run_tool(["iwctl", "known-networks", ssid, "forget"], 10)
    elif name == "wpa":
        found = [n for n in wpa_saved(iface) if n["ssid"] == ssid]
        code = 0 if found else 1
        for network in found:
            code = max(code, wpa(iface, "remove_network", network["id"])[0])
        if found:
            wpa(iface, "save_config")
    else:
        code = 1
    return {"ok": code == 0, "message": ("Réseau oublié : " if code == 0 else "Impossible d’oublier ") + clean(ssid)}


def wifi_disconnect(backend):
    name, iface = backend["name"], backend["iface"]
    command = {"nm": ["nmcli", "device", "disconnect", iface], "iwd": ["iwctl", "station", iface, "disconnect"],
               "wpa": ["wpa_cli", "-i", iface, "disconnect"]}.get(name)
    code = run_tool(command, 10)[0] if command else 1
    return {"ok": code == 0, "message": "Déconnecté" if code == 0 else "Déconnexion impossible"}


def wifi_power(backend, on):
    name, iface = backend["name"], backend["iface"]
    if name == "nm":
        code = run_tool(["nmcli", "radio", "wifi", "on" if on else "off"], 10)[0]
    elif name == "iwd":
        code = run_tool(["iwctl", "device", iface, "set-property", "Powered", "on" if on else "off"], 10)[0]
    else:
        code = run_tool(["rfkill", "unblock" if on else "block", "wlan"], 5)[0]
        if code == 0 and name == "wpa":
            wpa(iface, "reconnect" if on else "disconnect")
    return {"ok": code == 0, "message": "" if code == 0 else "Impossible de changer le Wi-Fi"}


def bt_ready():
    if not shutil.which("bluetoothctl"):
        return {"available": False, "powered": False, "error": "bluetoothctl manquant (paquet bluez-utils)"}
    code, out = run_tool(["bluetoothctl", "show"], 5)
    if code != 0 or "Controller" not in out:
        return {"available": False, "powered": False,
                "error": "Service Bluetooth arrêté (bluetooth.service)" if "No default controller" not in out
                else "Aucun adaptateur Bluetooth"}
    powered = re.search(r"^\s*Powered:\s*yes", out, re.M) is not None
    blocked = re.search(r"^\s*PowerState:\s*off-blocked", out, re.M) is not None
    return {"available": True, "powered": powered, "error": "Bluetooth bloqué (rfkill)" if blocked else ""}


MAC = re.compile(r"[0-9A-F]{2}(:[0-9A-F]{2}){5}")


def bt_devices():
    code, out = run_tool(["bluetoothctl", "devices"], 5)
    devices = []
    for line in out.splitlines():
        match = re.match(r"\s*Device\s+([0-9A-Fa-f:]{17})\s*(.*)$", line)
        if not match or not MAC.fullmatch(match[1].upper()):
            continue
        mac = match[1].upper()
        code, info = run_tool(["bluetoothctl", "info", mac], 5)
        values = {}
        for row in info.splitlines():
            key, _, value = row.strip().partition(": ")
            if key and key not in values:
                values[key] = value.strip()
        name = values.get("Alias") or values.get("Name") or match[2].strip()
        if not name or name.replace("-", ":").upper() == mac:
            name = values.get("Name") or mac
        battery = re.search(r"\((\d+)\)", values.get("Battery Percentage", ""))
        devices.append({"mac": mac, "name": clean(name)[:48], "paired": values.get("Paired") == "yes",
                        "connected": values.get("Connected") == "yes", "trusted": values.get("Trusted") == "yes",
                        "icon": values.get("Icon", ""), "battery": int(battery[1]) if battery else -1,
                        "named": name != mac})
    devices.sort(key=lambda d: (not d["connected"], not d["paired"], not d["named"], d["name"].lower()))
    return devices[:40]


def bt_job(op, mac):
    state = bt_ready()
    if not state["available"]:
        return dict(state, ok=False, message=state["error"], devices=[])
    message = ""
    ok = True
    if op == "power":
        if not state["powered"] and state["error"]:
            run_tool(["rfkill", "unblock", "bluetooth"], 5)
            time.sleep(1)
        code, out = run_tool(["bluetoothctl", "power", "off" if state["powered"] else "on"], 8)
        ok = code == 0 and "succeeded" in out
        message = "" if ok else ("Bluetooth bloqué (rfkill)" if "Blocked" in out or "rfkill" in out.lower() else "Impossible de changer le Bluetooth")
        state = bt_ready()
    elif op == "scan" and state["powered"]:
        run_tool(["bluetoothctl", "--timeout", "8", "scan", "on"], 12)
    elif op in ("pair", "connect", "disconnect", "remove") and isinstance(mac, str) and MAC.fullmatch(mac):
        if op == "pair":
            code, out = run_tool(["bluetoothctl", "--timeout", "25", "pair", mac], 30)
            ok = code == 0 and ("Pairing successful" in out or "AlreadyExists" in out)
            if ok:
                run_tool(["bluetoothctl", "trust", mac], 5)
                code, out = run_tool(["bluetoothctl", "--timeout", "15", "connect", mac], 20)
            message = "Jumelé" if ok else "Jumelage refusé (code ou appareil non visible ?)"
        else:
            code, out = run_tool(["bluetoothctl", "--timeout", "15", op, mac], 20)
            ok = code == 0 and ("successful" in out or "Device has been removed" in out or "Successful" in out)
            message = "" if ok else {"connect": "Connexion impossible", "disconnect": "Déconnexion impossible",
                                    "remove": "Impossible d’oublier l’appareil"}[op]
    return {"ok": ok, "available": True, "powered": state["powered"], "message": message or state["error"],
            "devices": bt_devices() if state["powered"] else []}


def sinks():
    if not shutil.which("wpctl"):
        return []
    code, out = run_tool(["wpctl", "status"], 3)
    found, section, audio = [], "", False
    for line in out.splitlines():
        text = line.replace("│", " ").replace("├", " ").replace("└", " ").replace("─", " ")
        stripped = text.strip()
        if stripped in ("Audio", "Video", "Settings"):
            audio = stripped == "Audio"
            section = ""
            continue
        if stripped.endswith(":"):
            section = stripped[:-1]
            continue
        if not audio or section != "Sinks":
            continue
        match = re.match(r"(\*)?\s*(\d+)\.\s+(.+?)(\s+\[vol:.*\])?$", stripped)
        if match:
            found.append({"id": int(match[2]), "name": clean(match[3])[:60], "default": bool(match[1])})
    return found[:12]


def run_job(request):
    kind = request.get("kind")
    if kind == "wifi":
        backend = wifi_backend()
        op = request.get("op")
        result = {"ok": True, "message": ""}
        if backend["name"] != "none":
            if op == "connect":
                result = wifi_connect(backend, request.get("ssid"), request.get("password") or "", bool(request.get("hidden")))
            elif op == "forget":
                result = wifi_forget(backend, request.get("ssid") or "")
            elif op == "disconnect":
                result = wifi_disconnect(backend)
            elif op == "power":
                result = wifi_power(backend, bool(request.get("on")))
        elif op == "power":
            result = wifi_power(backend, bool(request.get("on")))
        listing = wifi_scan(backend, op == "scan")
        message = result.get("message") or listing["message"]
        return {"kind": "wifi", "ok": result["ok"] and listing["ok"], "backend": backend["label"],
                "available": backend["name"] != "none", "message": message, "networks": listing["networks"],
                "ask": result.get("ask", False), "ssid": request.get("ssid") or ""}
    if kind == "bt":
        return dict(bt_job(request.get("op"), request.get("mac")), kind="bt")
    if kind == "sound":
        if isinstance(request.get("id"), int):
            run_tool(["wpctl", "set-default", str(request["id"])], 4)
        return {"kind": "sound", "sinks": sinks()}
    return {"kind": "none"}


def job_child():
    try:
        request = json.loads(sys.stdin.readline() or "{}")
    except ValueError:
        request = {}
    request = request if isinstance(request, dict) else {}
    try:
        result = run_job(request)
    except Exception:
        log_error("job " + str(request.get("kind")) + " " + str(request.get("op")))
        result = {"kind": request.get("kind"), "ok": False, "message": "Opération impossible"}
    print(json.dumps(result, ensure_ascii=False), flush=True)


