    migrated = stored is None and bool(widgets)
    weather_settings = clean_weather_settings(load_json(store, "weather.json"))
    weather = {"ready": False}
    weather_proc = None
    weather_buffer = b""
    weather_started = 0
    next_weather = 0
    activity_history = []
    net_last = net_bytes()
    disk_last = disk_bytes()
    stats_time = time.monotonic()
    city_code = clock_city()
    todo = clean_todo(load_json(store, "todo.json"))
    notes_data = load_json(store, "notes.json")
    notes = notes_data.get("text", "")[:4000] if isinstance(notes_data, dict) and isinstance(notes_data.get("text"), str) else ""
    appearance_mode = clean_appearance(load_json(store, "appearance.json"))
    scheme = color_scheme()
    dnd = {"available": False, "on": False}
    backend = {"name": "none", "iface": "", "label": ""}
    ssid = ""
    mako_reloaded = False
    started = False
    prepared = False
    next_slow = 0
    watching = False
    streams = {}
    buffers = {}
    page = ""
    workers = {}
    pending = {}
    next_page = 0
    wifi = {"available": False, "backend": "", "networks": [], "message": "", "busy": False, "ask": "", "ready": False}
    bt = {"available": False, "powered": False, "devices": [], "message": "", "busy": False, "ready": False}
    sound_outputs = []
    kbd = keyboard_light()
    home = Path.home()
    places = [{"label": label, "url": path.as_uri()} for label, path in (
        ("Images", home / "Pictures"), ("Téléchargements", home / "Downloads"), ("Dossier personnel", home))
        if path.is_absolute() and path.is_dir()]
    photos = photos_first
    staged = {}
    apps = dock_apps()
    extras = Extras()
    catalog = []
    selector = selectors.DefaultSelector()
    selector.register(sys.stdin.buffer, selectors.EVENT_READ, "input")
    kernel = kernel_events()
    for name, channel in kernel.items():
        selector.register(channel, selectors.EVENT_READ, "kernel:" + name)
    calm = "uevent" in kernel and "link" in kernel
    light_events = "uevent" in kernel
    light_hint = False
    media_proc = media_process()
    media_buffer = b""
    media = {}
    if media_proc:
        selector.register(media_proc.stdout, selectors.EVENT_READ, "media")
    for name, command in (("sound", ["pactl", "subscribe"]),
                          ("scheme", ["gsettings", "monitor", "org.gnome.desktop.interface", "color-scheme"])):
        proc = watcher(command)
        if proc:
            streams[name] = proc
            buffers[name] = b""
            selector.register(proc.stdout, selectors.EVENT_READ, name)
    event_socket = None
    event_buffer = b""
    input_buffer = b""
    workspaces = []
    windows = {}
    layouts = {"names": [], "current_idx": 0}
    overview = False
    next_stats = 0
    next_fast = 0
    next_volume = 0
    next_connect = 0
    stats = {}
    cpu_last = cpu_sample()
    light = backlight()
    sound = volume_level()
    next_volume = time.monotonic() + (2 if "sound" not in streams else 3600)
    osd = {"kind": "", "value": 0, "serial": 0}
    message = ""
    serial = 0
    timer_done = 0
    last_sent = None
    light_error = {"screen": "", "kbd": ""}
    tools = {"brightness": backlight_device() is not None, "kbd": bool(kbd["device"]), "media": media_proc is not None,
             "lock": os.access("/usr/local/bin/tarkin-lock", os.X_OK), "power": shutil.which("systemctl") is not None,
             "apps": False,
             "radio": shutil.which("rfkill") is not None}

    def start_job(request):
        kind = request["kind"]
        if kind in workers:
            pending[kind] = request
            return
        try:
            proc = subprocess.Popen(child("--job"), stdin=subprocess.PIPE,
                                    stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, env=app_environment())
            proc.stdin.write((json.dumps(request) + "\n").encode())
            proc.stdin.close()
        except OSError:
            return
        workers[kind] = {"proc": proc, "buffer": b"", "started": time.monotonic()}
        selector.register(proc.stdout, selectors.EVENT_READ, "job:" + kind)
        if kind == "wifi":
            wifi["busy"] = True
        elif kind == "bt":
            bt["busy"] = True

    def page_refresh(name, first):
        if name == "wifi":
            start_job({"kind": "wifi", "op": "scan" if first or not wifi["networks"] else "list"})
        elif name == "bluetooth":
            start_job({"kind": "bt", "op": "list"})
            if first:
                start_job({"kind": "bt", "op": "scan"})
        elif name == "sound":
            start_job({"kind": "sound"})

    def show_osd(kind, value):
        osd.update(kind=kind, value=value, serial=osd["serial"] + 1)

    def disconnect():
        nonlocal event_socket, workspaces, windows, next_connect, event_buffer
        if event_socket:
            selector.unregister(event_socket)
            event_socket.close()
        event_socket = None
        event_buffer = b""
        workspaces = []
        windows = {}
        next_connect = time.monotonic() + 10

    errors = []
    while True:
        try:
            now = time.monotonic()
            for kind, worker in list(workers.items()):
                if now - worker["started"] > 60 and worker["proc"].poll() is None:
                    worker["proc"].kill()
            if page and now >= next_page and page not in [k.replace("bt", "bluetooth") for k in workers]:
                page_refresh(page, False)
                next_page = now + (20 if page == "wifi" else 10 if page == "bluetooth" else 30)
            if now >= next_stats:
                activity = any(w["kind"] == "activity" for w in widgets)
                if watching or activity or "cpu" not in stats:
                    sample = cpu_sample()
                    cpu_value = cpu_percent(cpu_last, sample)
                    cpu_last = sample
                    load = {"cpu": cpu_value, "memory": memory_percent(), "temperature": temperature()}
                else:
                    load = {k: stats[k] for k in ("cpu", "memory", "temperature")}
                before_network = stats.get("network")
                stats = dict(load, battery=battery(), network=network(), radios=radios(),
                             batteryTime=battery_time() if watching else stats.get("batteryTime", ""))
                kbd = keyboard_light()
                if before_network is not None and stats["network"] != before_network:
                    next_slow = 0
                if activity:
                    elapsed = max(0.5, now - stats_time)
                    net_now, disk_now = net_bytes(), disk_bytes()
                    rates = lambda a, b: [max(0, (b[1] - a[1]) / elapsed), max(0, (b[2] - a[2]) / elapsed)] if a and b and a[0] == b[0] else [-1, -1]
                    point = {"time": round(time.time()), "gap": False, "cpu": cpu_value if cpu_value >= 0 else -1,
                             "memory": memory_bytes() or {}, "interface": net_now[0] if net_now else "",
                             "device": disk_now[0] if disk_now else "", "network": rates(net_last, net_now), "disk": rates(disk_last, disk_now)}
                    net_last, disk_last = net_now, disk_now
                    activity_history = (activity_history + [point])[-13:]
                    stats["activity"] = {"sample": point, "history": activity_history}
                else:
                    activity_history = []
                if any(w["kind"] == "batteries" for w in widgets):
                    stats["batteries"] = battery_entries()
                stats_time = now
                next_stats = now + (3 if watching and not activity else 5 if activity or not calm else 20)
            if started and now >= next_slow:
                if not prepared:
                    catalog = all_apps()
                    print(json.dumps({"apps": [{k: a[k] for k in ("id", "name", "icon")} for a in catalog],
                                      "launchers": launchers(apps)}, ensure_ascii=False), flush=True)
                    tools["apps"] = bool(catalog) and shutil.which("gio") is not None
                if "scheme" not in streams:
                    scheme = color_scheme()
                if watching or not prepared:
                    dnd = dnd_state()
                    backend = wifi_backend()
                    if not wifi["ready"]:
                        wifi.update(available=backend["name"] != "none", backend=backend["label"], message=backend.get("error", ""))
                    ssid = wifi_name(backend)
                prepared = True
                next_slow = now + (60 if watching or "scheme" not in streams else 3600)
            if weather_proc is None and now >= next_weather and any(w["kind"] == "weather" for w in widgets):
                try:
                    weather_proc = subprocess.Popen(child("--weather", json.dumps(weather_settings)), stdin=subprocess.DEVNULL,
                                                    stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
                    weather_buffer = b""
                    weather_started = now
                    selector.register(weather_proc.stdout, selectors.EVENT_READ, "weather")
                except OSError:
                    weather_proc = None
                    next_weather = now + 600
            if weather_proc is not None and now - weather_started > 25:
                weather_proc.kill()
            if now >= next_fast:
                value = backlight()
                if value != light and value >= 0 and light >= 0:
                    show_osd("brightness", value)
                    if light_events and not light_hint:
                        light_events = False
                        log("brightness changed without a kernel event: polling every second")
                light = value
                light_hint = False
                next_fast = now + (1 if not light_events else 3 if watching else 20)
            if now >= next_volume:
                value = volume_level()
                if value != sound and value[0] >= 0 and sound[0] >= 0:
                    show_osd("mute" if value[1] else "volume", value[0])
                sound = value
                next_volume = now + (2 if "sound" not in streams else 30 if watching else 3600)
            if event_socket is None and now >= next_connect:
                try:
                    event_socket = socket.socket(socket.AF_UNIX)
                    event_socket.settimeout(0.6)
                    event_socket.connect(os.environ["NIRI_SOCKET"])
                    event_socket.sendall(b'"EventStream"\n')
                    event_socket.setblocking(False)
                    selector.register(event_socket, selectors.EVENT_READ, "events")
                except (OSError, KeyError):
                    if event_socket:
                        event_socket.close()
                    event_socket = None
                    next_connect = now + 10
            names = [n for n in layouts.get("names") or [] if isinstance(n, str)] if isinstance(layouts.get("names"), list) else []
            index = layouts.get("current_idx", 0) if valid_id(layouts.get("current_idx")) else 0
            state = dict(stats, wifiPanel=wifi, bt=bt, sinks=sound_outputs, kbd=kbd["level"], lightError=light_error, batteryTime=stats.get("batteryTime", ""),
                         workspaces=visible_workspaces(workspaces, output),
                         connected=event_socket is not None, message=message, serial=serial,
                         wallpaper=wallpapers.url(wallpapers.current), fond=wallpapers.fond(), staged=staged,
                         places=places, widgets=widgets, todo=todo, notes=notes, photos=photos,
                         dock=dock_state(apps, windows, extras), weather=weather, weatherSettings=weather_settings,
                         clockCity=city_code, timer=timer_done, widgetsMigrated=migrated,
                         brightness=light, volume=sound[0], muted=sound[1],
                         audio="" if sound[0] < 0 else ("Son coupé" if sound[1] else f"Son {sound[0]} %"),
                         layout=short_layout(names[index]) if 0 <= index < len(names) else "",
                         layoutName=clean(names[index]) if 0 <= index < len(names) else "",
                         layouts=len(names), overview=overview, media=media, osd=osd, tools=tools,
                         appearance=appearance_view(appearance_mode, scheme), dnd=dnd, wifiName=ssid)
            serialized = json.dumps(state, ensure_ascii=False)
            if serialized != last_sent:
                print(serialized, flush=True)
                last_sent = serialized
            if not started:
                started = True
                next_slow = time.monotonic() + 0.25
            deadline = min(next_stats, next_fast, next_volume, next_slow)
            if weather_proc is not None:
                deadline = min(deadline, weather_started + 26)
            elif any(w["kind"] == "weather" for w in widgets):
                deadline = min(deadline, next_weather)
            if event_socket is None:
                deadline = min(deadline, next_connect)
            if page:
                deadline = min(deadline, next_page)
            if workers:
                deadline = min(deadline, time.monotonic() + 5)
            for key, _ in selector.select(max(0, deadline - time.monotonic())):
                if isinstance(key.data, str) and key.data.startswith("job:"):
                    kind = key.data[4:]
                    worker = workers[kind]
                    chunk = os.read(worker["proc"].stdout.fileno(), 65536)
                    worker["buffer"] = (worker["buffer"] + chunk)[-262144:]
                    if chunk:
                        continue
                    selector.unregister(worker["proc"].stdout)
                    worker["proc"].stdout.close()
                    worker["proc"].wait()
                    del workers[kind]
                    try:
                        result = json.loads(worker["buffer"].decode("utf-8", "replace").strip().splitlines()[-1])
                    except (ValueError, IndexError):
                        result = {"kind": kind, "ok": False, "message": "Opération interrompue"}
                    if kind == "wifi":
                        wifi.update(busy=False, ready=True, available=result.get("available", wifi["available"]),
                                    backend=result.get("backend", wifi["backend"]), message=result.get("message", ""),
                                    ask=result.get("ssid", "") if result.get("ask") else "")
                        if "networks" in result and (result.get("networks") or result.get("ok")):
                            wifi["networks"] = result["networks"]
                        active = next((n for n in wifi["networks"] if n.get("active")), None)
                        if active:
                            ssid = active["ssid"]
                        next_stats = 0
                    elif kind == "bt":
                        bt.update(busy=False, ready=True, available=result.get("available", False), powered=result.get("powered", False),
                                  message=result.get("message", ""), devices=result.get("devices", []))
                        next_stats = 0
                    elif kind == "sound":
                        sound_outputs = result.get("sinks", [])
                        next_volume = 0
                    if kind in pending:
                        start_job(pending.pop(kind))
                    elif kind == "bt" and bt["busy"]:
                        bt["busy"] = False
                    continue
                if isinstance(key.data, str) and key.data.startswith("kernel:"):
                    moment = time.monotonic()
                    if key.data == "kernel:uevent":
                        found = uevent_subsystems(key.fileobj)
                        if "backlight" in found:
                            light_hint = True
                            next_fast = min(next_fast, moment + 0.05)
                        if found & {"power_supply", "rfkill", "net"}:
                            next_stats = min(next_stats, moment + 0.3)
                    elif drain(key.fileobj):
                        next_stats = min(next_stats, moment + 0.5)
                    continue
                if key.data in streams:
                    name = key.data
                    chunk = os.read(streams[name].stdout.fileno(), 65536)
                    if not chunk:
                        selector.unregister(streams[name].stdout)
                        streams[name].stdout.close()
                        streams[name].wait()
                        del streams[name]
                        next_volume = 0
                        next_slow = 0
                        continue
                    buffers[name] = (buffers[name] + chunk)[-65536:]
                    while b"\n" in buffers[name]:
                        line, buffers[name] = buffers[name].split(b"\n", 1)
                        if name == "sound" and sink_event(line):
                            next_volume = min(next_volume, time.monotonic() + 0.05)
                        elif name == "scheme" and scheme_event(line) is not None:
                            scheme = scheme_event(line)
                elif key.data == "weather":
                    chunk = os.read(weather_proc.stdout.fileno(), 65536)
                    weather_buffer = (weather_buffer + chunk)[-262144:]
                    if chunk:
                        continue
                    selector.unregister(weather_proc.stdout)
                    weather_proc.stdout.close()
                    weather_proc.wait()
                    weather_proc = None
                    try:
                        result = json.loads(weather_buffer.decode("utf-8", "replace").strip().splitlines()[-1])
                    except (ValueError, IndexError):
                        result = {"ready": False, "error": "offline"}
                    if isinstance(result, dict) and result.get("ready"):
                        weather = result
                        next_weather = time.monotonic() + 1800
                    else:
                        weather = dict(weather, error="offline") if weather.get("ready") else {"ready": False, "error": "offline"}
                        next_weather = time.monotonic() + 600
                elif key.data == "media":
                    chunk = os.read(media_proc.stdout.fileno(), 65536)
                    if not chunk:
                        selector.unregister(media_proc.stdout)
                        media_proc = None
                        media = {}
                        tools["media"] = False
                        continue
                    media_buffer = (media_buffer + chunk)[-65536:]
                    while b"\n" in media_buffer:
                        line, media_buffer = media_buffer.split(b"\n", 1)
                        media = parse_media(line)
                elif key.data == "events":
                    try:
                        chunk = event_socket.recv(65536)
                        if not chunk:
                            disconnect()
                            continue
                        event_buffer += chunk
                        if len(event_buffer) > 4194304:
                            disconnect()
                            continue
                        while b"\n" in event_buffer:
                            line, event_buffer = event_buffer.split(b"\n", 1)
                            try:
                                event = json.loads(line)
                            except ValueError:
                                log("unreadable niri event skipped")
                                continue
                            if not isinstance(event, dict):
                                continue
                            if "Err" in event:
                                log("niri event stream error: " + str(event.get("Err"))[:200])
                                disconnect()
                                break
                            try:
                                workspaces = apply_event(workspaces, event)
                                windows = apply_window_event(windows, event)
                                change = body(event, "KeyboardLayoutsChanged")
                                if change is not None and isinstance(change.get("keyboard_layouts"), dict):
                                    layouts = dict(change["keyboard_layouts"])
                                change = body(event, "KeyboardLayoutSwitched")
                                if change is not None and valid_id(change.get("idx")):
                                    layouts["current_idx"] = change["idx"]
                                change = body(event, "OverviewOpenedOrClosed")
                                if change is not None:
                                    overview = bool(change.get("is_open"))
                            except Exception:
                                log_error("niri event " + ",".join(list(event)[:3]) + " skipped")
                    except OSError as exc:
                        log("niri event stream lost: " + str(exc))
                        disconnect()
                else:
                    chunk = os.read(sys.stdin.fileno(), 65536)
                    if not chunk:
                        log("stopping: Quickshell closed the helper input")
                        if media_proc:
                            media_proc.terminate()
                        for proc in streams.values():
                            proc.terminate()
                        for worker in workers.values():
                            worker["proc"].kill()
                        return
                    input_buffer += chunk
                    if len(input_buffer) > 65536:
                        log("input line too long, dropped")
                        input_buffer = b""
                        continue
                    while b"\n" in input_buffer:
                        line, input_buffer = input_buffer.split(b"\n", 1)
                        command = {}
                        try:
                            command = json.loads(line)
                            if not isinstance(command, dict):
                                command = {}
                            action = command.get("action")
                            target = command.get("key")
                            value = command.get("value")
                            if action == "workspace":
                                target_id = str(command.get("id", ""))
                                current = request("Workspaces")["Workspaces"]
                                found = next((w for w in current if str(w["id"]) == target_id
                                              and w["output"] == output), None)
                                if found is None:
                                    raise ValueError("workspace unavailable")
                                request({"Action": {"FocusWorkspace": {"reference": {"Id": found["id"]}}}})
                            elif action == "mute" and sound[0] >= 0:
                                subprocess.run(["wpctl", "set-mute", "@DEFAULT_AUDIO_SINK@", "toggle"],
                                               capture_output=True, timeout=1, check=True)
                                next_volume = 0
                            elif action == "volume" and sound[0] >= 0 and isinstance(value, (int, float)):
                                level = max(0, min(100, int(value)))
                                subprocess.run(["wpctl", "set-volume", "@DEFAULT_AUDIO_SINK@", f"{level / 100:.2f}"],
                                               capture_output=True, timeout=1, check=True)
                                next_volume = 0
                            elif action == "brightness" and tools["brightness"] and isinstance(value, (int, float)):
                                level = max(5, min(100, int(value)))
                                device = backlight_device()
                                if device is None:
                                    raise Notice("Réglage indisponible")
                                try:
                                    set_light(device, level, ["-d", device.name])
                                    light_hint = True
                                    light_error["screen"] = ""
                                except Notice as exc:
                                    light_error["screen"] = str(exc)
                                    raise
                                next_fast = 0
                            elif action == "media" and media_proc and value in ("play-pause", "next", "previous"):
                                subprocess.run(["playerctl", value], capture_output=True, timeout=2)
                            elif action == "overview":
                                request({"Action": {"ToggleOverview": {}}})
                            elif action == "layout" and len(layouts.get("names") or []) > 1:
                                request({"Action": {"SwitchLayout": {"layout": "Next"}}})
                            elif action == "power" and value == "lock" and tools["lock"]:
                                spawn(["/usr/local/bin/tarkin-lock"])
                            elif action == "power" and value == "logout":
                                request({"Action": {"Quit": {"skip_confirmation": True}}})
                            elif action == "power" and value in ("reboot", "poweroff") and tools["power"]:
                                spawn(["systemctl", value])
                            elif action == "open" and isinstance(target, str):
                                entry = next((a for a in catalog if a["id"] == target), None)
                                if not entry or not shutil.which("gio"):
                                    raise ValueError("Application indisponible")
                                spawn(["gio", "launch", entry["path"]])
                            elif action == "stage":
                                if staged:
                                    wallpapers.discard(staged["token"])
                                token, name = wallpapers.stage(command.get("path"))
                                staged = {"token": token, "url": wallpapers.url(name)}
                            elif action == "commit":
                                if not staged or command.get("token") != staged["token"]:
                                    raise ValueError("Choix expiré")
                                wallpapers.commit(staged["token"])
                                staged = {}
                            elif action == "discard":
                                if staged and command.get("token") == staged["token"]:
                                    wallpapers.discard(staged["token"])
                                    staged = {}
                                message = "Image illisible : fond conservé"
                                serial += 1
                                continue
                            elif action == "reset":
                                if staged:
                                    wallpapers.discard(staged["token"])
                                    staged = {}
                                wallpapers.reset()
                            elif action == "widgets":
                                had_weather = any(w["kind"] == "weather" for w in widgets)
                                widgets = clean_mac_widgets(value)
                                migrated = False
                                atomic_write(store, "widgets-v6.json", (json.dumps(widgets, ensure_ascii=False) + "\n").encode())
                                if not had_weather and not weather.get("ready"):
                                    next_weather = 0
                                next_stats = 0
                            elif action == "weather":
                                weather_settings = clean_weather_settings(value)
                                atomic_write(store, "weather.json", (json.dumps(weather_settings, ensure_ascii=False) + "\n").encode())
                                weather = {"ready": False}
                                next_weather = 0
                            elif action == "timer-done":
                                timer_done += 1
                                if shutil.which("notify-send"):
                                    spawn(["notify-send", "-a", "Vitrum Plus", "Minuteur", "Le minuteur est terminé."])
                            elif action == "todo":
                                todo = clean_todo(value)
                                atomic_write(store, "todo.json", (json.dumps(todo, ensure_ascii=False) + "\n").encode())
                            elif action == "notes" and isinstance(value, str):
                                notes = value[:4000]
                                atomic_write(store, "notes.json", (json.dumps({"text": notes}, ensure_ascii=False) + "\n").encode())
                            elif action == "appearance" and value in ("auto", "light", "dark"):
                                appearance_mode = value
                                atomic_write(store, "appearance.json", (json.dumps({"mode": value}) + "\n").encode())
                                scheme = color_scheme()
                            elif action == "dnd" and dnd["available"]:
                                if not mako_reloaded:
                                    subprocess.run(["makoctl", "reload"], capture_output=True, timeout=2)
                                    mako_reloaded = True
                                subprocess.run(["makoctl", "mode", "-t", "do-not-disturb"], capture_output=True, timeout=2, check=True)
                                dnd = dnd_state()
                            elif action == "radio" and target in ("wifi", "bluetooth") and tools["radio"] and isinstance(value, bool):
                                subprocess.run(["rfkill", "unblock" if value else "block", "wlan" if target == "wifi" else "bluetooth"],
                                               capture_output=True, timeout=4, check=True)
                                next_stats = 0
                                next_slow = time.monotonic() + 4
                            elif action == "watch" and isinstance(value, bool):
                                if value and not watching:
                                    next_stats = 0
                                    next_slow = 0
                                    start_job({"kind": "bt", "op": "list"})
                                watching = value
                                if not value:
                                    page = ""
                            elif action == "page" and value in ("", "wifi", "bluetooth", "sound"):
                                if value != page and value:
                                    page_refresh(value, True)
                                    next_page = time.monotonic() + (20 if value == "wifi" else 10 if value == "bluetooth" else 30)
                                page = value
                            elif action == "wifi" and isinstance(value, dict) and value.get("op") in ("scan", "connect", "forget", "disconnect", "power"):
                                job = {"kind": "wifi", "op": value["op"]}
                                for name in ("ssid", "password"):
                                    if isinstance(value.get(name), str):
                                        job[name] = value[name][:256]
                                job["hidden"] = bool(value.get("hidden"))
                                job["on"] = bool(value.get("on"))
                                wifi["message"] = "Connexion à " + clean(job.get("ssid", "")) + "…" if value["op"] == "connect" else ""
                                wifi["ask"] = ""
                                start_job(job)
                            elif action == "bt" and isinstance(value, dict) and value.get("op") in ("list", "scan", "power", "pair", "connect", "disconnect", "remove"):
                                job = {"kind": "bt", "op": value["op"]}
                                if isinstance(value.get("mac"), str):
                                    job["mac"] = value["mac"][:17]
                                bt["message"] = {"pair": "Jumelage…", "connect": "Connexion…", "scan": "Recherche…"}.get(value["op"], "")
                                start_job(job)
                            elif action == "sink" and isinstance(value, int):
                                start_job({"kind": "sound", "id": value})
                            elif action == "kbd" and kbd["device"] and isinstance(value, (int, float)):
                                level = max(0, min(100, int(value)))
                                try:
                                    set_light(kbd["path"], level, ["-d", kbd["device"]])
                                    light_error["kbd"] = ""
                                except Notice as exc:
                                    light_error["kbd"] = str(exc)
                                    raise
                                finally:
                                    kbd = keyboard_light()
                            elif action == "launch" and isinstance(target, str):
                                launch(target, apps, extras)
                            elif action == "activate" and isinstance(target, str):
                                found = window_group(target, apps, windows)
                                if found:
                                    request({"Action": {"FocusWindow": {"id": pick_window(found)["id"]}}})
                                else:
                                    launch(target, apps, extras)
                            else:
                                raise ValueError("Action indisponible")
                            message = ""
                        except ValueError as exc:
                            message = str(exc) if isinstance(exc, Notice) or str(exc) in ("Application indisponible", "Choix expiré") or command.get("action") == "stage" else "Action indisponible"
                            serial += 1
                            if command.get("action") == "stage":
                                staged = {}
                            if not isinstance(exc, Notice):
                                log("action " + str(command.get("action")) + " refused: " + str(exc)[:200])
                        except (OSError, KeyError, TypeError, AttributeError, subprocess.SubprocessError) as exc:
                            message = "Image inaccessible : fond conservé" if command.get("action") == "stage" else "Action indisponible"
                            serial += 1
                            if command.get("action") == "stage":
                                staged = {}
                            log("action " + str(command.get("action")) + " failed: " + type(exc).__name__ + ": " + str(exc)[:200])
                        except Exception:
                            message = "Action indisponible"
                            serial += 1
                            log_error("action " + str(command.get("action") if isinstance(command, dict) else ""))

        except (BrokenPipeError, SystemExit, KeyboardInterrupt):
            raise
        except Exception:
            log_error("main loop")
            moment = time.monotonic()
            errors = [e for e in errors if moment - e < 60] + [moment]
            if len(errors) >= 30:
                log("stopping: too many errors in one minute")
                sys.exit(3)
            time.sleep(0.5)

def child(*arguments):
    return [sys.executable, "-c", BOOT, os.path.abspath(__file__)] + list(arguments)


def entry(arguments):
    if arguments == ["--job"]:
        job_child()
    elif len(arguments) == 2 and arguments[0] == "--weather":
        weather_child(clean_weather_settings(json.loads(arguments[1])))
    else:
        def stop(number, frame):
            log(f"stopping: signal {number}")
            sys.exit(0)
        for number in (posix_signal.SIGTERM, posix_signal.SIGHUP, posix_signal.SIGINT):
            posix_signal.signal(number, stop)
        log("started (Vitrum Plus v10 helper)")
        try:
            main()
            log("stopped")
        except BrokenPipeError:
            log("stopping: output pipe closed")
        except SystemExit:
            raise
        except BaseException:
            log_error("crashed")
            sys.exit(1)


if __name__ == "__main__":
    entry(sys.argv[1:])
VITRUM_HELPER_EOF
