        app: glyph('<defs><linearGradient id="g" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#9aa6bd"/><stop offset="1" stop-color="#4a5367"/></linearGradient></defs><rect x="2" y="2" width="60" height="60" rx="15" fill="url(#g)"/><rect x="2.5" y="2.5" width="59" height="59" rx="14.5" fill="none" stroke="#fff" stroke-opacity=".25"/><rect x="18" y="18" width="28" height="28" rx="7" fill="none" stroke="#fff" stroke-width="3.5"/><circle cx="32" cy="32" r="4.5" fill="#fff"/>')
