    property var telemetry: ({battery: "Batterie —", network: "Réseau —", audio: "", workspaces: [], connected: false, message: "", serial: 0, wallpaper: "", fond: "", dock: [], cpu: -1, memory: -1, temperature: -1, brightness: -1, volume: -1, muted: false, radios: ({wifi: "absent", bluetooth: "absent"}), layout: "", layoutName: "", layouts: 0, overview: false, media: ({}), tools: ({}), places: [], widgets: [], todo: [], notes: "", photos: [], staged: ({})})
    property var launcherApps: []
