        {type: "clock", label: "Horloge", styles: ["liquid", "light", "dark"]},
        {type: "player", label: "Lecteur", styles: ["liquid", "light", "dark"]},
        {type: "activity", label: "Activité", styles: ["liquid", "normal"]},
        {type: "batteries", label: "Batteries", styles: ["liquid", "normal"]},
        {type: "timer", label: "Minuteur", styles: ["liquid", "normal"]},
        {type: "notes", label: "Notes", styles: ["liquid", "normal"]},
        {type: "reminders", label: "Rappels", styles: ["liquid", "normal"]},
        {type: "image", label: "Image", styles: ["liquid", "normal"]}
    ]
    readonly property var styleNames: ({liquid: "Liquid Glass", normal: "Normal", light: "Clair", dark: "Sombre"})
    readonly property var sizeNames: ({small: "Petit", medium: "Moyen", large: "Grand"})

    function widgetType(type) {
        return widgetTypes.find(t => t.type === type) || widgetTypes[0];
    }

    function widgetDims(type, size) {
        const catalog = ["activity", "batteries", "timer", "notes", "reminders", "image"].indexOf(type) >= 0;
        if (catalog)
            return size === "large" ? [375, 385] : size === "medium" ? [395, 185] : [185, 185];
        return size === "large" ? [358, 354] : size === "medium" ? [358, 168] : [168, 168];
    }

    function saveWidgets(list) {
        widgetList = list;
        send({action: "widgets", value: list});
    }

    property real widgetArea: 1200

    function freeSpot(type, size, skip) {
        const d = widgetDims(type, size);
        for (let y = 16; y < 3000; y += 24) {
            for (let x = 32; x + d[0] <= Math.max(widgetArea - 16, 32 + d[0]); x += 24) {
                const hit = widgetList.some(o => {
                    if (o.id === skip)
                        return false;
                    const e = widgetDims(o.kind, o.size);
                    return x < o.x + e[0] + 16 && o.x < x + d[0] + 16 && y < o.y + e[1] + 16 && o.y < y + d[1] + 16;
                });
                if (!hit)
                    return {x: x, y: y};
            }
        }
        return {x: 32, y: 16};
    }

    function addWidget(kind, size, style) {
        const spot = freeSpot(kind, size, "");
        const list = widgetList.slice();
        list.push({id: Math.random().toString(16).slice(2, 10), kind: kind, size: size, style: style, theme: "dark",
                   x: spot.x, y: spot.y, settings: ({})});
        saveWidgets(list);
    }

    function packWidgets() {
        const placed = [];
        const saved = widgetList;
        widgetList = [];
        for (const item of saved) {
            const spot = freeSpot(item.kind, item.size, "");
            const next = Object.assign({}, item, spot);
            placed.push(next);
            widgetList = placed.slice();
        }
        saveWidgets(placed);
    }

    function updateWidget(id, change) {
        saveWidgets(widgetList.map(o => o.id === id ? Object.assign({}, o, change) : o));
    }

    function removeWidget(index) {
        const list = widgetList.slice();
        list.splice(index, 1);
        saveWidgets(list);
    }

    function moveWidget(index, x, y) {
        const list = widgetList.slice();
        list[index] = Object.assign({}, list[index], {x: Math.max(0, x), y: Math.max(0, y)});
        saveWidgets(list);
    }

    function cycle(values, current) {
        return values[(values.indexOf(current) + 1) % values.length];
    }

    function saveTodo(list) {
        send({action: "todo", value: list});
    }

    property var timerBackend: QtObject {
        property bool ready: true
        property bool busy: false
        property string timerStatus: "normal"
        property string state: "idle"
        property string sessionId: ""
        property double endsAt: 0
        property double left: 0
        property double timerRemaining: 0
        readonly property var timing: ({timer: {state: state, sessionId: sessionId}})
        function refresh() {
            timerRemaining = state === "running" ? Math.max(0, endsAt - Date.now()) : left;
            if (state === "running" && timerRemaining <= 0) {
                state = "idle";
                left = 0;
                timerRemaining = 0;
                root.send({action: "timer-done"});
            }
        }
        function startTimer(ms) {
            sessionId = Math.random().toString(16).slice(2, 10);
            endsAt = Date.now() + ms;
            left = ms;
            state = "running";
            refresh();
            return true;
        }
        function timerAction(action) {
            if (action === "pause" && state === "running") {
                left = Math.max(0, endsAt - Date.now());
                state = "paused";
            } else if (action === "resume" && state === "paused") {
                endsAt = Date.now() + left;
                state = "running";
            } else if (action === "cancel") {
                state = "idle";
                left = 0;
            }
            refresh();
            return true;
        }
    }

    Timer {
        interval: 1000
        repeat: true
        running: root.timerBackend.state === "running"
        onTriggered: root.timerBackend.refresh()
    }

    property string openPanel: ""
    property int osdSerial: -1
    property string osdKind: ""
    property real osdValue: 0
    property bool osdVisible: false
    readonly property var icons: ({
        grid: icon('<rect x="4" y="4" width="6" height="6" rx="1.5"/><rect x="14" y="4" width="6" height="6" rx="1.5"/><rect x="4" y="14" width="6" height="6" rx="1.5"/><rect x="14" y="14" width="6" height="6" rx="1.5"/>'),
        volume: icon('<path d="M4 9h4l5-4v14l-5-4H4z"/><path d="M16.5 8.5a5 5 0 0 1 0 7M19 6a8.5 8.5 0 0 1 0 12"/>'),
        mute: icon('<path d="M4 9h4l5-4v14l-5-4H4z"/><path d="M17 9l5 6M22 9l-5 6"/>'),
        sun: icon('<circle cx="12" cy="12" r="4"/><path d="M12 2v2.5M12 19.5V22M2 12h2.5M19.5 12H22M4.9 4.9l1.8 1.8M17.3 17.3l1.8 1.8M4.9 19.1l1.8-1.8M17.3 6.7l1.8-1.8"/>'),
