        keyboard: icon('<rect x="2.5" y="6" width="19" height="12" rx="2.5"/><path d="M6 10h1M10 10h1M14 10h1M18 10h0.5M7 14h10"/>'),
        left: icon('<path d="M15 5l-7 7 7 7"/>'),
