        calendar: icon('<rect x="3.5" y="5" width="17" height="15" rx="2.5"/><path d="M3.5 10h17M8 3v4M16 3v4"/>'),
        battery: icon('<rect x="2.5" y="7" width="17" height="10" rx="2.5"/><path d="M22 10.5v3"/><rect x="5" y="9.5" width="9" height="5" rx="1" fill="#fff"/>'),
        notes: icon('<path d="M6 3h9l4 4v14H6z"/><path d="M9 11h7M9 15h7M9 7h3"/>'),
        todo: icon('<circle cx="6" cy="7" r="2"/><circle cx="6" cy="17" r="2"/><path d="M11 7h9M11 17h9"/>'),
        photo: icon('<rect x="3" y="5" width="18" height="14" rx="2.5"/><circle cx="9" cy="10" r="1.8"/><path d="M21 16l-5-5-8 8"/>')
    })

    function icon(body) {
        return "data:image/svg+xml;utf8," + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' + body + '</svg>');
    }

    function toggle(name) {
        openPanel = openPanel === name ? "" : name;
    }

    function showOsd(kind, value) {
        osdKind = kind;
        osdValue = value;
        osdVisible = true;
        osdTimer.restart();
    }

    Timer {
        id: osdTimer
        interval: 1600
        onTriggered: root.osdVisible = false
    }
    property string spaceHint: ""
    property string notice: ""
    property int seenSerial: 0

    property var launchers: ({})
    property bool panelWatch: false
    property string panelPage: ""
    property int helperFailures: 0
    property double helperStarted: 0

    function send(payload) {
        if (payload.action === "watch")
            root.panelWatch = payload.value;
        else if (payload.action === "page")
            root.panelPage = payload.value;
        if (helper.running) {
            helper.write(JSON.stringify(payload) + "\n");
            return;
        }
        if ((payload.action === "launch" || payload.action === "activate") && root.launchers[payload.key]) {
            Quickshell.execDetached({command: root.launchers[payload.key], environment: root.appEnvironment});
            console.warn("Vitrum: assistant arrêté, lancement direct de " + payload.key);
        }
    }

    Timer {
        id: helperRestart
        interval: 1000
        onTriggered: helper.running = true
    }

    function syncDock(list) {
        let gaps = 0;
        for (let i = 0; i < list.length; ++i) {
            const item = list[i];
            const gap = i > 0 && list[i - 1].pinned && !item.pinned;
            gaps += gap ? 1 : 0;
            const roles = {key: item.key, name: item.name, icons: JSON.stringify(item.icons), glyph: item.glyph,
                running: item.running, focused: item.focused, urgent: item.urgent, launchable: item.launchable,
                gap: gap, gaps: gaps};
            let found = -1;
            for (let j = i; j < dockItems.count; ++j) {
                if (dockItems.get(j).key === item.key) {
                    found = j;
                    break;
                }
            }
            if (found === -1) {
                dockItems.insert(i, roles);
                continue;
            }
            if (found !== i)
                dockItems.move(found, i, 1);
            const current = dockItems.get(i);
            let changed = {};
            let any = false;
            for (const role in roles) {
                if (current[role] !== roles[role]) {
                    changed[role] = roles[role];
                    any = true;
                }
            }
            if (any)
                dockItems.set(i, changed);
        }
        if (dockItems.count > list.length)
            dockItems.remove(list.length, dockItems.count - list.length);
        root.dockGaps = gaps;
    }

    property int dockGaps: 0

    Process {
        id: helper
        command: ["python3", "-u", "-c", "import sys, importlib.util as u; s = u.spec_from_file_location('helper', sys.argv[1]); m = u.module_from_spec(s); s.loader.exec_module(m); m.entry(sys.argv[2:])", Quickshell.env("VP_HELPER")]
        environment: root.appEnvironment
        stdinEnabled: true
        running: true
        stdout: SplitParser {
            splitMarker: "\n"
            onRead: data => {
                try {
                    const update = JSON.parse(data);
                    if (update.apps !== undefined) {
                        root.launcherApps = update.apps;
                        if (update.launchers)
                            root.launchers = update.launchers;
                        return;
                    }
                    if (update.osd && update.osd.serial !== root.osdSerial) {
                        if (root.osdSerial >= 0)
                            root.showOsd(update.osd.kind, update.osd.value);
                        root.osdSerial = update.osd.serial;
                    }
                    const before = JSON.stringify(root.telemetry.workspaces);
                    const after = JSON.stringify(update.workspaces);
                    if (before !== after) {
                        let structureChanged = workspaceItems.count !== update.workspaces.length;
                        for (let i = 0; !structureChanged && i < workspaceItems.count; ++i)
                            structureChanged = workspaceItems.get(i).workspaceId !== update.workspaces[i].id;
                        if (structureChanged) {
                            root.spaceHint = "";
                            workspaceItems.clear();
                        }
                        for (let i = 0; i < update.workspaces.length; ++i) {
                            const item = update.workspaces[i];
                            const roles = {workspaceId: item.id, label: item.label, name: item.name, active: item.active, focused: item.focused, urgent: item.urgent};
                            if (structureChanged)
                                workspaceItems.append(roles);
                            else
                                workspaceItems.set(i, roles);
                        }
                    }
                    if (JSON.stringify(root.telemetry.dock) !== JSON.stringify(update.dock))
                        root.syncDock(update.dock);
                    if (update.serial !== root.seenSerial && update.message !== "") {
                        root.notice = update.message;
                        noticeTimer.restart();
                    }
                    root.seenSerial = update.serial;
                    if (!root.widgetsLoaded && update.widgets) {
                        root.widgetList = update.widgets;
                        if (update.widgetsMigrated)
                            Qt.callLater(root.packWidgets);
                        root.widgetsLoaded = true;
                    }
                    root.telemetry = update;
                } catch (error) {
                    console.error("Données locales illisibles : " + error);
                }
            }
        }
        stderr: SplitParser { onRead: data => console.error(data) }
        onStarted: {
            root.helperStarted = Date.now();
            if (root.helperFailures > 0) {
                if (root.panelWatch)
                    helper.write(JSON.stringify({action: "watch", value: true}) + "\n");
                if (root.panelPage !== "")
                    helper.write(JSON.stringify({action: "page", value: root.panelPage}) + "\n");
                if (root.notice === "Assistant local arrêté")
                    root.notice = "";
            }
        }
        onExited: (exitCode, exitStatus) => {
            if (Date.now() - root.helperStarted > 60000)
                root.helperFailures = 0;
            helperRestart.interval = [1000, 2000, 5000, 10000][Math.min(root.helperFailures, 3)];
            root.helperFailures += 1;
            console.error("Vitrum: assistant local arrêté (code " + exitCode + ", statut " + exitStatus + "), relance dans " + helperRestart.interval / 1000 + " s");
            helperRestart.restart();
            root.osdSerial = -1;
            workspaceItems.clear();
            root.notice = "Assistant local arrêté";
            root.telemetry = Object.assign({}, root.telemetry, {workspaces: [], connected: false, message: "", serial: root.seenSerial});
        }
    }

    Timer {
        id: noticeTimer
        interval: 3500
        onTriggered: root.notice = ""
    }

    ListModel { id: workspaceItems }
    ListModel { id: dockItems }

    SystemClock {
        id: clock
        precision: SystemClock.Minutes
    }

    component Glass: Rectangle {
        id: glass
        radius: 16
        property bool strong: false
        property bool opaque: false
        gradient: Gradient {
            GradientStop { position: 0; color: glass.opaque ? "#f22e3546" : glass.strong ? "#b02e3546" : "#5a2b3242" }
            GradientStop { position: 0.5; color: glass.opaque ? "#ee222836" : glass.strong ? "#a8222836" : "#4a202634" }
            GradientStop { position: 1; color: glass.opaque ? "#f41a1f2b" : glass.strong ? "#b41a1f2b" : "#5c1a1f2b" }
        }

        Rectangle {
            x: 1
            y: 1
            width: parent.width - 2
            height: Math.round(parent.height * 0.5)
            radius: Math.max(0, glass.radius - 1)
            gradient: Gradient {
                GradientStop { position: 0; color: "#2affffff" }
                GradientStop { position: 0.5; color: "#08ffffff" }
                GradientStop { position: 1; color: "#00ffffff" }
            }
        }

        Rectangle {
            x: glass.radius * 0.8
            y: 1
            width: Math.max(0, parent.width - glass.radius * 1.6)
            height: 1
            gradient: Gradient {
                orientation: Gradient.Horizontal
                GradientStop { position: 0; color: "#00ffffff" }
                GradientStop { position: 0.3; color: "#a6ffffff" }
                GradientStop { position: 0.7; color: "#a6ffffff" }
                GradientStop { position: 1; color: "#00ffffff" }
            }
        }

        Shape {
            anchors.fill: parent
            ShapePath {
                strokeWidth: -1
                strokeColor: "transparent"
                fillRule: ShapePath.OddEvenFill
                fillGradient: LinearGradient {
                    x1: 0; y1: 0; x2: 0; y2: glass.height
                    GradientStop { position: 0; color: "#99ffffff" }
                    GradientStop { position: 0.3; color: "#2effffff" }
                    GradientStop { position: 0.7; color: "#12ffffff" }
                    GradientStop { position: 1; color: "#4dffffff" }
                }
                PathRectangle { x: 0; y: 0; width: glass.width; height: glass.height; radius: glass.radius }
                PathRectangle { x: 1; y: 1; width: glass.width - 2; height: glass.height - 2; radius: Math.max(0, glass.radius - 1) }
            }
        }
    }

    component Panel: PanelWindow {
        id: panel
        property string name
        property real reveal: root.openPanel === name ? 1 : 0
        default property alias content: body.data
        property alias body: body
        visible: reveal > 0.01
        color: "transparent"
        exclusionMode: ExclusionMode.Ignore
        margins.top: root.topOffset + 48
        WlrLayershell.namespace: root.namespace + "-panel"
        WlrLayershell.layer: WlrLayer.Overlay
        WlrLayershell.keyboardFocus: WlrKeyboardFocus.None
        mask: Region { item: body }
        BackgroundEffect.blurRegion: Region { item: body; radius: 22 }
        Behavior on reveal { NumberAnimation { duration: 220; easing.type: Easing.OutCubic } }

        Glass {
            id: body
            strong: true
            radius: 22
            width: panel.width
            height: panel.height
            opacity: panel.reveal
            transform: Translate { y: (1 - panel.reveal) * -14 }
        }
    }

    component Glyph: Image {
        property string name
        source: root.icons[name] || ""
        sourceSize.width: 48
        sourceSize.height: 48
        width: 16
        height: 16
        smooth: true
        mipmap: true
    }

    component Chip: Rectangle {
        id: chip
        property bool active: false
        signal activated
        radius: height / 2
        color: chipMouse.pressed ? "#3affffff" : active ? "#30bed7e4" : chipMouse.containsMouse ? "#22ffffff" : "transparent"
        scale: chipMouse.pressed ? 0.94 : 1
        Behavior on color { ColorAnimation { duration: 140 } }
        Behavior on scale { NumberAnimation { duration: 120; easing.type: Easing.OutCubic } }
        MouseArea {
            id: chipMouse
            anchors.fill: parent
            hoverEnabled: true
            acceptedButtons: Qt.LeftButton
            cursorShape: Qt.PointingHandCursor
            onClicked: chip.activated()
        }
    }

    component Slider: Item {
        id: slider
        property real value: 0
        property string glyph
        property bool available: true
        signal moved(real value)
        height: 34
        opacity: available ? 1 : 0.4
        Rectangle {
            id: track
            anchors.fill: parent
            radius: height / 2
            color: "#26ffffff"
            border.width: 1
            border.color: "#26ffffff"
            Rectangle {
                width: Math.max(height, track.width * Math.max(0, Math.min(100, slider.dragging >= 0 ? slider.dragging : slider.value)) / 100)
                height: parent.height
                radius: height / 2
                gradient: Gradient {
                    orientation: Gradient.Horizontal
                    GradientStop { position: 0; color: "#a05f95c8" }
                    GradientStop { position: 1; color: "#d08fc1ea" }
                }
                Behavior on width {
                    enabled: slider.dragging < 0
                    NumberAnimation { duration: 180; easing.type: Easing.OutCubic }
                }
            }
            Glyph {
                name: slider.glyph
                x: 10
                anchors.verticalCenter: parent.verticalCenter
                opacity: 0.9
            }
        }
        property real dragging: -1
        MouseArea {
            anchors.fill: parent
            enabled: slider.available
            cursorShape: Qt.PointingHandCursor
            function level(x) { return Math.round(Math.max(0, Math.min(1, x / width)) * 100); }
            onPressed: mouse => slider.dragging = level(mouse.x)
            onPositionChanged: mouse => { if (pressed) slider.dragging = level(mouse.x); }
            onReleased: mouse => {
                slider.moved(level(mouse.x));
                slider.dragging = -1;
            }
        }
    }

    component MenuEntry: Rectangle {
        id: entry
        property string text
        property bool available: true
        signal activated
        width: parent ? parent.width : 220
        height: 34
        radius: 8
        color: !available ? "transparent" : entryMouse.pressed ? "#2cbed7e4" : entryMouse.containsMouse ? "#1cbed7e4" : "transparent"
        opacity: available ? 1 : 0.45
        Label {
            anchors.verticalCenter: parent.verticalCenter
            x: 12
            width: parent.width - 24
            elide: Text.ElideRight
            text: entry.text
        }
        MouseArea {
            id: entryMouse
            anchors.fill: parent
            enabled: entry.available
            hoverEnabled: true
            acceptedButtons: Qt.LeftButton
            cursorShape: Qt.PointingHandCursor
            onClicked: entry.activated()
        }
    }

    component PillButton: Rectangle {
        id: pill
        property string text
        property bool available: true
        property bool primary: false
        signal activated
        width: Math.max(96, pillLabel.implicitWidth + 28)
        height: 34
        radius: 9
        color: !available ? "#10ffffff" : pillMouse.pressed ? "#44bed7e4" : primary ? (pillMouse.containsMouse ? "#3cbed7e4" : "#2cbed7e4") : (pillMouse.containsMouse ? "#22ffffff" : "#12ffffff")
        opacity: available ? 1 : 0.45
        Label {
            id: pillLabel
            anchors.centerIn: parent
            text: pill.text
            font.weight: pill.primary ? Font.DemiBold : Font.Normal
        }
        MouseArea {
            id: pillMouse
            anchors.fill: parent
            enabled: pill.available
            hoverEnabled: true
            acceptedButtons: Qt.LeftButton
            cursorShape: Qt.PointingHandCursor
            onClicked: pill.activated()
        }
    }

    component Label: Text {
        color: root.ink
        font.family: root.fontFamily
        font.letterSpacing: -0.15
        font.features: ({"tnum": 1})
        font.pixelSize: 13
        renderType: Text.QtRendering
        textFormat: Text.PlainText
    }

