    readonly property int barBottom: barTop + barHeight
    readonly property int shadowPad: 22
    readonly property var batteryInfo: {
        const match = /^(\d+) %/.exec(telemetry.battery || "");
        return match ? {level: Number(match[1]), charging: (telemetry.battery || "").indexOf("en charge") >= 0} : {level: -1, charging: false};
    }
    readonly property string focusedApp: {
        const found = (telemetry.dock || []).find(d => d.focused);
        return found ? found.name : "Bureau";
    }

