    function symbol(name, tint, back) {
        const body = (symbols[name] || "").split("TINT").join(tint).split("BACK").join(back || "#000000");
        return "data:image/svg+xml;utf8," + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="' + tint + '" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">' + body + '</svg>');
    }

    component SoftShadow: Item {
        id: softShadow
        property real radius: 16
        property real strength: 1
        Repeater {
            model: [0.16, 0.1, 0.06, 0.034, 0.016]
            Rectangle {
                required property real modelData
                required property int index
                x: -(index + 1) * 3
                y: -(index + 1) * 3 + 5
                width: softShadow.width + (index + 1) * 6
                height: softShadow.height + (index + 1) * 6
                radius: softShadow.radius + (index + 1) * 3
                color: "transparent"
                border.width: 3
                border.color: Qt.rgba(root.tShadow.r, root.tShadow.g, root.tShadow.b, modelData * softShadow.strength * root.shadowStrength)
            }
        }
    }

    component GlassRim: Shape {
        id: rim
        property real radius: 16
        ShapePath {
            strokeWidth: -1
            strokeColor: "transparent"
            fillRule: ShapePath.OddEvenFill
            fillGradient: LinearGradient {
                x1: 0; y1: 0; x2: 0; y2: rim.height
                GradientStop { position: 0; color: root.tRimTop }
                GradientStop { position: 0.28; color: root.tRimMid }
                GradientStop { position: 0.72; color: root.tRimMid }
                GradientStop { position: 1; color: root.tRimBottom }
            }
            PathRectangle { x: 0; y: 0; width: rim.width; height: rim.height; radius: rim.radius }
            PathRectangle { x: 1; y: 1; width: rim.width - 2; height: rim.height - 2; radius: Math.max(0, rim.radius - 1) }
        }
    }

    component Material: Rectangle {
        id: material
        property bool menu: false
        radius: 16
        border.width: 1
        border.color: root.tEdge
        gradient: Gradient {
            GradientStop { position: 0; color: material.menu ? root.tMenuTop : root.tGlassTop }
            GradientStop { position: 1; color: material.menu ? root.tMenuBottom : root.tGlassBottom }
        }
        GlassRim {
            x: 1
            y: 1
            width: material.width - 2
            height: material.height - 2
            radius: Math.max(0, material.radius - 1)
        }
    }

    component MacPanel: PanelWindow {
        id: macPanel
        property string name
        readonly property bool shown: root.openPanel === name
        property real reveal: shown ? 1 : 0
        property Component body
        property alias sheet: sheet
        property real sheetWidth: 300
        property real sheetHeight: 300
        property real sheetRadius: 24
        property bool sheetMenu: false
        property real sheetX: root.shadowPad
        property real sheetY: root.shadowPad
        readonly property Item content: bodyLoader.item
        visible: reveal > 0.01
        color: "transparent"
        exclusionMode: ExclusionMode.Ignore
        margins.top: Math.max(0, root.barBottom + 6 - root.shadowPad)
        implicitWidth: sheetWidth + 2 * root.shadowPad
        implicitHeight: sheetHeight + 2 * root.shadowPad
        WlrLayershell.namespace: root.namespace + "-panel"
        WlrLayershell.layer: WlrLayer.Overlay
        WlrLayershell.keyboardFocus: WlrKeyboardFocus.None
        mask: Region { item: sheet }
        BackgroundEffect.blurRegion: Region { item: sheet; radius: macPanel.sheetRadius }
        Behavior on reveal { NumberAnimation { duration: 170; easing.type: Easing.OutCubic } }

        Item {
            id: frame
            x: macPanel.sheetX
            y: macPanel.sheetY
            width: macPanel.sheetWidth
            height: macPanel.sheetHeight
            opacity: macPanel.reveal
            scale: 0.96 + 0.04 * macPanel.reveal
            transformOrigin: Item.Top

            SoftShadow {
                anchors.fill: parent
                radius: macPanel.sheetRadius
            }

            Material {
                id: sheet
                anchors.fill: parent
                radius: macPanel.sheetRadius
                menu: macPanel.sheetMenu

                Loader {
                    id: bodyLoader
                    anchors.fill: parent
