    component MacSlider: Item {
        id: macSlider
        property real value: 0
        property string glyph
        property bool available: true
        property bool interactive: true
        property real dragging: -1
        readonly property real shown: Math.max(0, Math.min(100, dragging >= 0 ? dragging : value))
        signal moved(real value)
        height: 26
        opacity: available ? 1 : 0.45
        Rectangle {
            id: macTrack
            anchors.fill: parent
            radius: height / 2
            color: root.tTrack
            border.width: 1
            border.color: root.dark ? "#0fffffff" : "#0d000000"
            Rectangle {
                width: macTrack.height + (macTrack.width - macTrack.height) * macSlider.shown / 100
                height: parent.height
                radius: height / 2
                color: root.tFill
                Behavior on width {
                    enabled: macSlider.dragging < 0
                    NumberAnimation { duration: 140; easing.type: Easing.OutCubic }
                }
                Rectangle {
                    anchors.right: parent.right
                    width: parent.height
                    height: parent.height
                    radius: height / 2
                    color: "#ffffff"
                    border.width: 1
                    border.color: root.dark ? "#40000000" : "#24000000"
                }
            }
            Symbol {
                name: macSlider.glyph
                x: 7
                anchors.verticalCenter: parent.verticalCenter
                tint: "#76767c"
                width: 13
                height: 13
            }
        }
        MouseArea {
            anchors.fill: parent
            enabled: macSlider.available && macSlider.interactive
            function level(x) { return Math.round(Math.max(0, Math.min(1, (x - 13) / Math.max(1, width - 26))) * 100); }
            onPressed: mouse => macSlider.dragging = level(mouse.x)
            onPositionChanged: mouse => { if (pressed) macSlider.dragging = level(mouse.x); }
            onReleased: mouse => {
                macSlider.moved(level(mouse.x));
                macSlider.dragging = -1;
            }
        }
    }

    component MenuItem: Rectangle {
        id: menuItem
