            opacity: menuItem.available ? 1 : 0.4
        }
        MacLabel {
            anchors.verticalCenter: parent.verticalCenter
            x: menuItem.glyph !== "" ? 31 : 11
            width: parent.width - x - 11 - (menuHint.visible ? menuHint.implicitWidth + 8 : 0)
            elide: Text.ElideRight
