    component BatteryIcon: Item {
        id: batteryIcon
        property int level: -1
        property bool charging: false
        property color tint: root.tText
        width: 25
        height: 12
        Rectangle {
            width: 22
            height: 12
            radius: 3.5
            color: "transparent"
            border.width: 1
            border.color: Qt.rgba(batteryIcon.tint.r, batteryIcon.tint.g, batteryIcon.tint.b, 0.45)
            Rectangle {
                x: 2
                y: 2
                height: parent.height - 4
                width: Math.max(1.5, (parent.width - 4) * Math.max(0, batteryIcon.level) / 100)
                radius: 1.8
                color: batteryIcon.charging ? root.tGreen : batteryIcon.level >= 0 && batteryIcon.level <= 20 ? root.tRed : batteryIcon.tint
            }
        }
        Rectangle {
            x: 23
            y: 4
            width: 1.6
            height: 4
            radius: 0.8
            color: Qt.rgba(batteryIcon.tint.r, batteryIcon.tint.g, batteryIcon.tint.b, 0.45)
        }
    }

    Variants {
        model: root.selectedScreens

        Scope {
            id: display
            required property var modelData
            readonly property bool compact: modelData.width < 1100

            PanelWindow {
                id: desktop
                screen: display.modelData
                anchors { top: true; bottom: true; left: true; right: true }
                color: root.solid
                focusable: false
                exclusionMode: ExclusionMode.Ignore
                WlrLayershell.namespace: root.namespace + "-desktop"
                WlrLayershell.layer: WlrLayer.Background
                WlrLayershell.keyboardFocus: WlrKeyboardFocus.OnDemand

                property int front: 0
                property int menuX: 0
                property int menuY: 0
                property string wantedUrl: ""
                property string stagedToken: ""
                readonly property string chosenUrl: root.telemetry.wallpaper && root.telemetry.wallpaper !== root.wallpaperFailed ? root.telemetry.wallpaper : root.telemetry.fond

                function present(url, token) {
                    wantedUrl = url;
                    stagedToken = token;
                    const back = front === 0 ? layerB : layerA;
                    if (!url) {
                        front = -1;
                        layerA.source = "";
                        layerB.source = "";
                        return;
                    }
                    if ((front === 0 ? layerA : layerB).source.toString() === url && token === "")
                        return;
                    back.source = "";
                    back.source = url;
                }

                function settled(layer, other, index) {
                    if (layer.source.toString() !== wantedUrl || wantedUrl === "")
                        return;
                    if (layer.status === Image.Ready) {
                        front = index;
                        other.source = "";
                        if (stagedToken !== "") {
                            root.send({action: "commit", token: stagedToken});
                            stagedToken = "";
                        }
                    } else if (layer.status === Image.Error) {
                        layer.source = "";
                        if (stagedToken !== "") {
                            root.send({action: "discard", token: stagedToken});
                            stagedToken = "";
                            present(chosenUrl, "");
                        } else if (wantedUrl === root.telemetry.wallpaper) {
                            root.wallpaperFailed = wantedUrl;
                        } else {
                            front = -1;
                        }
                    }
                }

                onChosenUrlChanged: if (stagedToken === "") present(chosenUrl, "")
                Component.onCompleted: present(chosenUrl, "")

                Connections {
                    target: root
                    function onTelemetryChanged() {
                        const staged = root.telemetry.staged;
                        if (staged && staged.token && staged.token !== desktop.stagedToken)
                            desktop.present(staged.url, staged.token);
                        else if (desktop.stagedToken !== "" && !(staged && staged.token === desktop.stagedToken)) {
                            desktop.stagedToken = "";
                            desktop.present(desktop.chosenUrl, "");
                        }
                    }
                }

                Image {
                    id: layerA
                    anchors.fill: parent
                    visible: desktop.front === 0 && status === Image.Ready
                    fillMode: Image.PreserveAspectCrop
                    sourceSize.width: desktop.width
                    sourceSize.height: desktop.height
                    asynchronous: true
                    cache: false
                    smooth: true
                    onStatusChanged: desktop.settled(layerA, layerB, 0)
                }

                Image {
                    id: layerB
                    anchors.fill: parent
                    visible: desktop.front === 1 && status === Image.Ready
                    fillMode: Image.PreserveAspectCrop
                    sourceSize.width: desktop.width
                    sourceSize.height: desktop.height
                    asynchronous: true
                    cache: false
                    smooth: true
                    onStatusChanged: desktop.settled(layerB, layerA, 1)
                }

                MouseArea {
                    anchors.fill: parent
                    acceptedButtons: Qt.RightButton
                    onPressed: mouse => {
                        chooser.visible = false;
                        desktopMenu.visible = false;
                        desktop.menuX = Math.min(mouse.x, desktop.width - 1);
                        desktop.menuY = Math.min(mouse.y, desktop.height - 1);
                        desktopMenu.visible = true;
                    }
                }

                Item {
                    id: widgetLayer
                    anchors.fill: parent
                    onWidthChanged: root.widgetArea = width
                    anchors.topMargin: root.topOffset + 48
                    anchors.bottomMargin: 110

                    Repeater {
                        model: root.widgetList

                        Item {
                            id: holder
                            required property var modelData
                            required property int index
                            readonly property string kind: modelData.kind
                            readonly property string size: modelData.size || "small"
                            readonly property string style: root.widgetType(kind).styles.indexOf(modelData.style) >= 0 ? modelData.style : root.widgetType(kind).styles[0]
                            readonly property bool darkTheme: modelData.theme !== "light"
                            readonly property var settings: modelData.settings || ({})
                            readonly property var dims: root.widgetDims(kind, size)
                            readonly property bool usable: !root.editWidgets
                            readonly property real sx: widgetLayer.x + x
                            readonly property real sy: widgetLayer.y + y
                            x: Math.min(Math.max(0, modelData.x), Math.max(0, widgetLayer.width - width))
                            y: Math.min(Math.max(0, modelData.y), Math.max(0, widgetLayer.height - height))
                            width: dims[0]
                            height: dims[1]
                            z: dragArea.drag.active ? 10 : 0
                            scale: root.editWidgets ? 0.97 : 1
                            Behavior on scale { NumberAnimation { duration: 200; easing.type: Easing.OutCubic } }

                            Loader {
                                id: card
                                anchors.fill: parent
                                sourceComponent: ({weather: weatherCard, calendar: calendarCard, clock: clockCard, player: playerCard,
                                                   activity: activityCard, batteries: batteriesCard, timer: timerCard, notes: notesCard,
                                                   reminders: remindersCard, image: imageCard})[holder.kind] || null
                            }

                            Component {
                                id: weatherCard
                                Mac.WeatherWidget {
                                    style: holder.style; size: holder.size; fam: root.fontFamily; editing: root.editWidgets
                                    glassReady: root.glassOk; shaderUrl: root.glassShader; wallUrl: desktop.chosenUrl
                                    screenX: holder.sx; screenY: holder.sy; screenW: desktop.width; screenH: desktop.height; darkGlass: holder.darkTheme
                                    onGlassFailed: root.glassOk = false
                                    readonly property var wx: root.telemetry.weather || ({})
                                    city: wx.city || "—"; located: !!wx.located; hasData: !!wx.ready
                                    temp: wx.temp || 0; hi: wx.hi || 0; lo: wx.lo || 0; cond: wx.cond || (wx.error ? "Météo indisponible" : "Chargement…")
                                    kind: wx.kind || "cloud"; isDay: wx.day !== false; hourly: wx.hourly || []; daily: wx.daily || []
                                }
                            }
                            Component {
                                id: calendarCard
                                Mac.CalendarWidget {
                                    style: holder.style; size: holder.size; fam: root.fontFamily; editing: root.editWidgets; weekStart: 1
                                    mode: holder.darkTheme ? "dark" : "light"
                                    glassReady: root.glassOk; shaderUrl: root.glassShader; wallUrl: desktop.chosenUrl
                                    screenX: holder.sx; screenY: holder.sy; screenW: desktop.width; screenH: desktop.height; darkGlass: holder.darkTheme
                                    onGlassFailed: root.glassOk = false
                                }
                            }
                            Component {
                                id: clockCard
                                Mac.ClockWidget {
                                    style: holder.style; size: holder.size; fam: root.fontFamily; editing: root.editWidgets; secondsMode: "tick"
                                    cityCode: root.telemetry.clockCity || "PAR"
                                    glassReady: root.glassOk; shaderUrl: root.glassShader; wallUrl: desktop.chosenUrl
                                    screenX: holder.sx; screenY: holder.sy; screenW: desktop.width; screenH: desktop.height; darkGlass: holder.darkTheme
                                    onGlassFailed: root.glassOk = false
                                }
                            }
                            Component {
                                id: playerCard
                                Mac.PlayerWidget {
                                    style: holder.style; size: holder.size; fam: root.fontFamily; editing: root.editWidgets; animationsEnabled: false
                                    glassReady: root.glassOk; shaderUrl: root.glassShader; wallUrl: desktop.chosenUrl
                                    screenX: holder.sx; screenY: holder.sy; screenW: desktop.width; screenH: desktop.height; darkGlass: holder.darkTheme
                                    onGlassFailed: root.glassOk = false
                                    readonly property var media: root.telemetry.media || ({})
                                    hasPlayer: !!media.status; title: media.title || ""; artist: media.artist || ""; album: media.album || ""
                                    artUrl: media.art || ""; playing: media.status === "Playing"
                                    canShuffle: false; canLoop: false; canSeek: false
                                    onTogglePlaying: if (holder.usable) root.send({action: "media", value: "play-pause"})
                                    onNextTrack: if (holder.usable) root.send({action: "media", value: "next"})
                                    onPreviousTrack: if (holder.usable) root.send({action: "media", value: "previous"})
                                }
                            }
                            Component {
                                id: activityCard
                                Mac.ActivityWidget {
                                    style: holder.style; size: holder.size; fam: root.fontFamily; editing: root.editWidgets
                                    glassReady: root.glassOk; shaderUrl: root.glassShader; wallUrl: desktop.chosenUrl
                                    screenX: holder.sx; screenY: holder.sy; screenW: desktop.width; screenH: desktop.height; darkGlass: holder.darkTheme
                                    onGlassFailed: root.glassOk = false
                                    settings: ({view: holder.settings.view === "graphs" ? "graphs" : "rings"})
                                    readonly property var stats: root.telemetry.activity || ({})
                                    sample: stats.sample || ({}); history: stats.history || []; stale: !stats.sample
                                }
                            }
                            Component {
                                id: batteriesCard
                                Mac.BatteriesWidget {
                                    style: holder.style; size: holder.size; fam: root.fontFamily; editing: root.editWidgets
                                    glassReady: root.glassOk; shaderUrl: root.glassShader; wallUrl: desktop.chosenUrl
                                    screenX: holder.sx; screenY: holder.sy; screenW: desktop.width; screenH: desktop.height; darkGlass: holder.darkTheme
                                    onGlassFailed: root.glassOk = false
                                    settings: ({mode: "auto"}); entries: root.telemetry.batteries || []
                                }
                            }
                            Component {
                                id: timerCard
                                Mac.TimerWidget {
                                    style: holder.style; size: holder.size; fam: root.fontFamily; editing: root.editWidgets
                                    glassReady: root.glassOk; shaderUrl: root.glassShader; wallUrl: desktop.chosenUrl
                                    screenX: holder.sx; screenY: holder.sy; screenW: desktop.width; screenH: desktop.height; darkGlass: holder.darkTheme
                                    onGlassFailed: root.glassOk = false
                                    backend: root.timerBackend; interactive: holder.usable
                                    onOpenClock: root.timerBackend.startTimer(presets[0] * 60000)
                                }
                            }
                            Component {
                                id: notesCard
                                Mac.NotesWidget {
                                    style: holder.style; size: holder.size; fam: root.fontFamily; editing: root.editWidgets
                                    glassReady: root.glassOk; shaderUrl: root.glassShader; wallUrl: desktop.chosenUrl
                                    screenX: holder.sx; screenY: holder.sy; screenW: desktop.width; screenH: desktop.height; darkGlass: holder.darkTheme
                                    onGlassFailed: root.glassOk = false
                                    ready: true; interactive: holder.usable
                                    notes: root.telemetry.notes ? [{body: root.telemetry.notes}] : []
                                    body: root.telemetry.notes || ""
                                    onOpenRequested: notesEditor.open()
                                }
                            }
                            Component {
                                id: remindersCard
                                Mac.RemindersWidget {
                                    style: holder.style; size: holder.size; fam: root.fontFamily; editing: root.editWidgets
                                    glassReady: root.glassOk; shaderUrl: root.glassShader; wallUrl: desktop.chosenUrl
                                    screenX: holder.sx; screenY: holder.sy; screenW: desktop.width; screenH: desktop.height; darkGlass: holder.darkTheme
                                    onGlassFailed: root.glassOk = false
                                    ready: true; interactive: holder.usable
                                    tasks: (root.telemetry.todo || []).map((t, i) => ({id: String(i), title: t.text, done: t.done}))
                                    onToggleRequested: task => {
                                        const list = (root.telemetry.todo || []).slice();
                                        const i = Number(task.id);
                                        if (list[i])
                                            list[i] = {text: list[i].text, done: !list[i].done};
                                        root.saveTodo(list);
                                    }
                                    onAddRequested: title => root.saveTodo((root.telemetry.todo || []).concat([{text: title, done: false}]))
                                    onDeleteRequested: task => root.saveTodo((root.telemetry.todo || []).filter((t, i) => String(i) !== task.id))
                                    onOpenRequested: adding = true
                                }
                            }
                            Component {
                                id: imageCard
                                Mac.ImageWidget {
                                    style: holder.style; size: holder.size; fam: root.fontFamily; editing: root.editWidgets
                                    glassReady: root.glassOk; shaderUrl: root.glassShader; wallUrl: desktop.chosenUrl
                                    screenX: holder.sx; screenY: holder.sy; screenW: desktop.width; screenH: desktop.height; darkGlass: holder.darkTheme
                                    onGlassFailed: root.glassOk = false
                                    settings: ({path: typeof holder.settings.path === "string" ? holder.settings.path : ""})
                                }
                            }

                            MouseArea {
                                id: dragArea
                                anchors.fill: parent
                                visible: root.editWidgets
                                cursorShape: Qt.SizeAllCursor
                                drag.target: holder
                                drag.threshold: 2
                                onReleased: root.moveWidget(holder.index, Math.round(holder.x / 8) * 8, Math.round(holder.y / 8) * 8)
                            }

                            Rectangle {
                                visible: root.editWidgets
                                x: -8
                                y: -8
                                width: 26
                                height: 26
