                                                if (key === "size") {
                                                    const next = root.cycle(["small", "medium", "large"], holder.size);
                                                    const d = root.widgetDims(holder.kind, next);
                                                    const fits = holder.modelData.x + d[0] <= widgetLayer.width && holder.modelData.y + d[1] <= widgetLayer.height;
                                                    root.updateWidget(holder.modelData.id, fits ? {size: next} : Object.assign({size: next}, root.freeSpot(holder.kind, next, holder.modelData.id)));
                                                } else if (key === "style") {
                                                    root.updateWidget(holder.modelData.id, {style: root.cycle(root.widgetType(holder.kind).styles, holder.style)});
                                                } else if (key === "theme") {
                                                    root.updateWidget(holder.modelData.id, {theme: holder.darkTheme ? "light" : "dark"});
                                                } else if (key === "view") {
                                                    root.updateWidget(holder.modelData.id, {settings: Object.assign({}, holder.settings, {view: holder.settings.view === "graphs" ? "rings" : "graphs"})});
