                                    daily: wx.ready ? wx.daily : [{d: "Aujourd’hui", lo: 13, hi: 21, k: "sun"}, {d: "Sam", lo: 12, hi: 20, k: "partly"}, {d: "Dim", lo: 11, hi: 17, k: "rain"}, {d: "Lun", lo: 10, hi: 16, k: "cloud"}, {d: "Mar", lo: 12, hi: 19, k: "sun"}]
                                }
