                PopupWindow {
                    id: chooser
                    anchor.window: desktop
                    anchor.rect.x: Math.max(0, (desktop.width - implicitWidth) / 2)
                    anchor.rect.y: Math.max(0, (desktop.height - implicitHeight) / 2)
                    anchor.rect.width: 1
                    anchor.rect.height: 1
                    anchor.adjustment: PopupAdjustment.All
                    implicitWidth: Math.min(840, desktop.width - 24) + 2 * root.shadowPad
                    implicitHeight: Math.max(320, Math.min(520, desktop.height - 2 * (root.bottomOffset + 96))) + 2 * root.shadowPad
                    color: "transparent"
                    grabFocus: true
                    visible: false
                    mask: Region { item: chooser.body ? chooser.body.sheet : null }

                    property string selectedPath: ""
                    property url selectedUrl: ""
                    property url lastGood: ""
                    property string note: ""
                    property string target: ""
                    property url place: ""
                    readonly property Item body: chooserBody.item

                    function openFor(id) {
                        target = id;
                        show();
                    }

                    function open() {
                        target = "";
                        show();
                    }

                    function show() {
                        const places = root.telemetry.places;
                        if (places.length === 0)
                            return;
                        goTo(places[0].url);
                        visible = true;
                        body.fileList.forceActiveFocus();
                    }

                    function goTo(url) {
                        note = "";
                        selectedPath = "";
                        selectedUrl = "";
                        place = url;
                        if (!body)
                            return;
                        body.folders.folder = url;
                        body.fileList.currentIndex = -1;
                    }

                    function activate(index) {
                        const folders = body.folders;
                        if (index < 0 || index >= folders.count)
                            return;
                        if (folders.get(index, "fileIsDir")) {
                            note = "";
                            selectedPath = "";
                            selectedUrl = "";
                            folders.folder = folders.get(index, "fileUrl");
                            body.fileList.currentIndex = -1;
                        } else {
                            selectedPath = folders.get(index, "filePath");
                            selectedUrl = folders.get(index, "fileUrl");
                        }
                    }

                    function up() {
                        const folders = body.folders;
                        if (folders.parentFolder.toString() === "")
                            return;
                        selectedPath = "";
                        selectedUrl = "";
                        note = "";
                        folders.folder = folders.parentFolder;
                        body.fileList.currentIndex = -1;
                    }

                    function apply() {
                        if (selectedPath === "" || !body || body.preview.status !== Image.Ready)
                            return;
                        if (target !== "") {
                            const item = root.widgetList.find(o => o.id === target);
                            if (item)
                                root.updateWidget(target, {settings: Object.assign({}, item.settings || {}, {path: selectedPath})});
                            visible = false;
                            return;
                        }
                        root.wallpaperFailed = "";
                        root.send({action: "stage", path: selectedPath});
                        visible = false;
                    }

                    Loader {
                        id: chooserBody
                        anchors.fill: parent
                        active: chooser.visible
                        sourceComponent: Item {
                            property alias folders: folders
                            property alias fileList: fileList
                            property alias preview: previewImage
                            property alias sheet: chooserSheet

                            FolderListModel {
                                id: folders
                                folder: chooser.place
                                showDirs: true
                                showDirsFirst: true
                                showDotAndDotDot: false
                                showHidden: false
                                caseSensitive: false
                                sortCaseSensitive: false
                                nameFilters: ["*.jpg", "*.jpeg", "*.png", "*.webp", "*.gif", "*.bmp"]
                                onStatusChanged: {
                                    if (status === FolderListModel.Ready)
                                        chooser.lastGood = folder;
                                    else if (status === FolderListModel.Null && chooser.visible && chooser.lastGood.toString() !== "" && folder.toString() !== chooser.lastGood.toString()) {
                                        chooser.note = "Dossier impossible à ouvrir ici (nom avec # ?). Déplacer l’image ailleurs.";
                                        folder = chooser.lastGood;
                                    }
                                }
                            }

                            SoftShadow {
                                x: root.shadowPad
                                y: root.shadowPad
                                width: chooserSheet.width
                                height: chooserSheet.height
                                radius: chooserSheet.radius
                            }

                            Material {
                                id: chooserSheet
                                x: root.shadowPad
                                y: root.shadowPad
                                width: chooser.implicitWidth - 2 * root.shadowPad
                                height: chooser.implicitHeight - 2 * root.shadowPad
                                radius: 18

                                Rectangle {
                                    id: sidebar
                                    x: 8
                                    y: 8
                                    width: 196
                                    height: parent.height - 16
                                    radius: 12
                                    color: root.dark ? "#14ffffff" : "#66ffffff"
                                    border.width: 1
                                    border.color: root.tModuleEdge

                                    Row {
                                        x: 14
                                        y: 16
                                        spacing: 8
                                        Repeater {
                                            model: ["#ff5f57", "#febc2e", "#28c840"]
                                            Rectangle {
                                                id: light
                                                required property string modelData
                                                required property int index
                                                width: 12
                                                height: 12
                                                radius: 6
                                                color: modelData
                                                border.width: 1
                                                border.color: "#26000000"
                                                MouseArea {
                                                    anchors.fill: parent
                                                    enabled: light.index === 0
                                                    onClicked: chooser.visible = false
                                                }
                                            }
                                        }
                                    }

                                    MacLabel {
                                        x: 14
                                        y: 48
                                        text: "Favoris"
                                        font.pixelSize: 11
                                        font.weight: Font.DemiBold
                                        color: root.tTertiary
                                    }

                                    Column {
                                        x: 6
                                        y: 68
                                        width: parent.width - 12
                                        spacing: 2
                                        Repeater {
                                            model: root.telemetry.places
                                            Rectangle {
                                                id: placeRow
                                                required property var modelData
                                                required property int index
                                                readonly property bool current: chooser.place.toString() === modelData.url
                                                width: parent.width
                                                height: 28
                                                radius: 7
                                                color: current ? root.tPressed : placeMouse.containsMouse ? root.tHover : "transparent"
                                                Symbol {
                                                    x: 9
                                                    anchors.verticalCenter: parent.verticalCenter
                                                    name: ({"Images": "photo", "Téléchargements": "download", "Dossier personnel": "house"})[placeRow.modelData.label] || "folder"
                                                    tint: root.tAccent
                                                    width: 15
                                                    height: 15
                                                }
                                                MacLabel {
                                                    x: 32
                                                    width: parent.width - 40
                                                    anchors.verticalCenter: parent.verticalCenter
                                                    elide: Text.ElideRight
                                                    text: placeRow.modelData.label
                                                    font.weight: placeRow.current ? Font.DemiBold : Font.Normal
                                                }
                                                MouseArea {
                                                    id: placeMouse
                                                    anchors.fill: parent
                                                    hoverEnabled: true
                                                    onClicked: chooser.goTo(placeRow.modelData.url)
                                                }
                                            }
                                        }
                                    }
                                }

                                Item {
                                    id: chooserMain
                                    anchors.left: sidebar.right
                                    anchors.leftMargin: 14
                                    anchors.right: parent.right
                                    anchors.rightMargin: 16
                                    anchors.top: parent.top
                                    anchors.bottom: parent.bottom
                                    focus: true
                                    Keys.onEscapePressed: chooser.visible = false

                                    Row {
                                        id: header
                                        y: 12
                                        height: 28
                                        spacing: 10
                                        BarItem {
                                            width: 28
                                            height: 28
                                            anchors.verticalCenter: parent.verticalCenter
                                            opacity: folders.parentFolder.toString() !== "" ? 1 : 0.35
                                            onActivated: chooser.up()
                                            Symbol { name: "left"; anchors.centerIn: parent; width: 15; height: 15 }
                                        }
                                        Column {
                                            anchors.verticalCenter: parent.verticalCenter
                                            MacLabel {
                                                text: chooser.target !== "" ? "Image du widget" : "Fond d’écran"
                                                font.pixelSize: 15
                                                font.weight: Font.Bold
                                            }
                                            MacLabel {
                                                width: chooserMain.width - 60
                                                elide: Text.ElideMiddle
                                                color: root.tSecondary
                                                font.pixelSize: 11
                                                text: {
                                                    try {
                                                        return decodeURIComponent(folders.folder.toString().replace(/^file:\/\//, ""));
                                                    } catch (error) {
                                                        return folders.folder.toString();
                                                    }
                                                }
                                            }
                                        }
                                    }

                                    Rectangle {
                                        id: listPane
                                        anchors.top: parent.top
                                        anchors.topMargin: 56
                                        anchors.bottom: footer.top
                                        anchors.bottomMargin: 12
                                        width: Math.round(parent.width * 0.44)
                                        radius: 12
                                        color: root.dark ? "#1f000000" : "#8cffffff"
                                        border.width: 1
                                        border.color: root.tModuleEdge

                                        ListView {
                                            id: fileList
                                            anchors.fill: parent
                                            anchors.margins: 6
                                            clip: true
                                            model: chooser.visible ? folders : null
                                            currentIndex: -1
                                            boundsBehavior: Flickable.StopAtBounds
                                            keyNavigationEnabled: true
                                            focus: true
                                            Keys.onReturnPressed: {
                                                if (currentIndex >= 0 && folders.get(currentIndex, "fileIsDir"))
                                                    chooser.activate(currentIndex);
                                                else
                                                    chooser.apply();
                                            }
                                            Keys.onEscapePressed: chooser.visible = false
                                            Keys.onPressed: event => {
                                                if (event.key === Qt.Key_Backspace && folders.parentFolder.toString() !== "") {
                                                    chooser.up();
                                                    event.accepted = true;
                                                }
                                            }
                                            onCurrentIndexChanged: {
                                                if (currentIndex >= 0 && !folders.get(currentIndex, "fileIsDir"))
                                                    chooser.activate(currentIndex);
                                            }

                                            delegate: Rectangle {
                                                id: fileRow
                                                required property int index
                                                required property string fileName
                                                required property bool fileIsDir
                                                width: ListView.view.width
                                                height: 28
                                                radius: 7
                                                color: ListView.isCurrentItem ? root.tAccent : rowMouse.containsMouse ? root.tHover : "transparent"
                                                Symbol {
                                                    x: 8
                                                    anchors.verticalCenter: parent.verticalCenter
                                                    name: fileRow.fileIsDir ? "folder" : "photo"
                                                    tint: fileRow.ListView.isCurrentItem ? "#ffffff" : fileRow.fileIsDir ? root.tAccent : root.dimHex
                                                    width: 15
                                                    height: 15
                                                }
                                                MacLabel {
                                                    anchors.verticalCenter: parent.verticalCenter
                                                    x: 30
                                                    width: parent.width - 52
                                                    elide: Text.ElideMiddle
                                                    text: fileRow.fileName
                                                    color: fileRow.ListView.isCurrentItem ? "#ffffff" : root.tText
                                                }
                                                Symbol {
                                                    visible: fileRow.fileIsDir
                                                    anchors.right: parent.right
                                                    anchors.rightMargin: 8
                                                    anchors.verticalCenter: parent.verticalCenter
                                                    name: "chevron"
                                                    tint: fileRow.ListView.isCurrentItem ? "#ffffff" : root.dimHex
                                                    width: 10
                                                    height: 10
                                                }
                                                MouseArea {
                                                    id: rowMouse
                                                    anchors.fill: parent
                                                    hoverEnabled: true
                                                    acceptedButtons: Qt.LeftButton
                                                    onClicked: {
                                                        fileList.currentIndex = fileRow.index;
                                                        chooser.activate(fileRow.index);
                                                    }
                                                    onDoubleClicked: {
                                                        if (!fileRow.fileIsDir)
                                                            chooser.apply();
                                                    }
                                                }
                                            }

                                            MacLabel {
                                                anchors.centerIn: parent
                                                visible: folders.status === FolderListModel.Ready && folders.count === 0
                                                width: parent.width - 32
                                                horizontalAlignment: Text.AlignHCenter
                                                wrapMode: Text.WordWrap
                                                color: root.tSecondary
                                                text: "Aucune image ici.\nJPEG, PNG, WebP, GIF ou BMP."
                                            }
                                        }
                                    }

                                    Rectangle {
                                        anchors.top: listPane.top
                                        anchors.bottom: listPane.bottom
                                        anchors.left: listPane.right
                                        anchors.leftMargin: 14
                                        anchors.right: parent.right
                                        radius: 12
                                        color: root.solid
                                        clip: true
                                        Image {
                                            id: previewImage
                                            anchors.fill: parent
                                            source: chooser.selectedUrl
                                            fillMode: Image.PreserveAspectCrop
                                            sourceSize.width: 640
                                            sourceSize.height: 400
                                            asynchronous: true
                                            cache: false
                                            visible: status === Image.Ready
                                        }
                                        Rectangle {
                                            anchors.fill: parent
                                            radius: 12
                                            color: "transparent"
                                            border.width: 1
                                            border.color: "#33ffffff"
                                        }
                                        MacLabel {
                                            anchors.centerIn: parent
                                            width: parent.width - 32
                                            horizontalAlignment: Text.AlignHCenter
                                            wrapMode: Text.WordWrap
                                            visible: previewImage.status !== Image.Ready
                                            color: "#d9ffffff"
                                            text: chooser.selectedPath === "" ? "Choisir une image à gauche"
                                                : previewImage.status === Image.Loading ? "Lecture de l’image…"
                                                : "Image illisible : choisir un autre fichier"
                                        }
                                    }

                                    Row {
                                        id: footer
                                        anchors.bottom: parent.bottom
                                        anchors.bottomMargin: 14
                                        anchors.right: parent.right
                                        spacing: 8
                                        MacLabel {
                                            anchors.verticalCenter: parent.verticalCenter
                                            width: Math.max(0, chooserMain.width - 88 * 2 - 16 - 8)
                                            elide: Text.ElideMiddle
                                            color: root.tSecondary
                                            font.pixelSize: 11
                                            text: chooser.note !== "" ? chooser.note : chooser.selectedPath === "" ? (chooser.target !== "" ? "Choisir une image locale pour le widget." : "Le fond actuel reste en place tant que rien n’est appliqué.") : chooser.selectedPath
                                        }
                                        MacButton { text: "Annuler"; onActivated: chooser.visible = false }
                                        MacButton {
                                            text: "Appliquer"
                                            primary: true
                                            available: chooser.selectedPath !== "" && previewImage.status === Image.Ready
                                            onActivated: chooser.apply()
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }

            PanelWindow {
                id: topBar
                screen: display.modelData
                anchors { top: true; left: true; right: true }
                margins.top: root.barTop
                implicitHeight: root.barHeight
                color: "transparent"
                focusable: false
                exclusionMode: root.reserve ? ExclusionMode.Auto : ExclusionMode.Ignore
                WlrLayershell.namespace: root.namespace
                WlrLayershell.layer: WlrLayer.Top
                WlrLayershell.keyboardFocus: WlrKeyboardFocus.None
                BackgroundEffect.blurRegion: Region { item: menuBar }

                Rectangle {
                    id: menuBar
                    anchors.fill: parent
                    color: root.tBar
                    Rectangle {
                        anchors.bottom: parent.bottom
                        width: parent.width
                        height: 1
                        color: root.tBarEdge
                    }

                    Row {
                        id: leftRow
                        x: 8
                        height: parent.height
                        spacing: 2

                        BarItem {
                            anchors.verticalCenter: parent.verticalCenter
                            width: 36
                            active: root.openPanel === "power"
                            onActivated: root.toggle("power")
                            Symbol { name: "logo"; anchors.centerIn: parent; width: 16; height: 16; back: root.dark ? "#3a3a40" : "#dcdce2" }
                        }

                        BarItem {
                            anchors.verticalCenter: parent.verticalCenter
                            width: appName.implicitWidth + 22
                            active: root.telemetry.overview
                            onActivated: root.send({action: "overview"})
                            MacLabel {
                                id: appName
                                anchors.centerIn: parent
                                text: root.focusedApp
                                width: Math.min(implicitWidth, 180)
                                elide: Text.ElideRight
                                font.weight: Font.Bold
                            }
                        }

                        Repeater {
                            model: workspaceItems
                            BarItem {
                                id: spaceItem
                                required property var model
                                anchors.verticalCenter: parent.verticalCenter
                                width: Math.max(30, spaceLabel.implicitWidth + 20)
                                active: model.active
                                color: model.active ? root.tPressed : model.urgent ? (root.dark ? "#55ff453a" : "#40ff3b30") : spaceMouse.containsMouse ? root.tHover : "transparent"
                                onActivated: root.send({action: "workspace", id: spaceItem.model.workspaceId})
                                MacLabel {
                                    id: spaceLabel
                                    anchors.centerIn: parent
                                    text: spaceItem.model.label + (spaceItem.model.urgent ? "!" : "")
                                    font.weight: spaceItem.model.active ? Font.DemiBold : Font.Medium
                                    color: spaceItem.model.active ? root.tText : root.tSecondary
                                }
                                HoverHandler { id: spaceMouse }
                            }
                        }
                    }

                    Row {
                        id: rightRow
                        anchors.right: parent.right
                        anchors.rightMargin: 8
                        height: parent.height
                        spacing: 2

                        BarItem {
                            anchors.verticalCenter: parent.verticalCenter
                            visible: !display.compact && !!(root.telemetry.media && root.telemetry.media.title)
                            width: visible ? barMedia.implicitWidth + 20 : 0
                            onActivated: root.send({action: "media", value: "play-pause"})
                            Row {
                                id: barMedia
                                anchors.centerIn: parent
                                spacing: 6
                                Symbol { name: root.telemetry.media && root.telemetry.media.status === "Playing" ? "pause" : "play"; width: 11; height: 11; anchors.verticalCenter: parent.verticalCenter }
                                MacLabel {
                                    text: root.telemetry.media && root.telemetry.media.title ? root.telemetry.media.title : ""
                                    width: Math.min(implicitWidth, 160)
                                    elide: Text.ElideRight
                                }
                            }
                        }

                        BarItem {
                            anchors.verticalCenter: parent.verticalCenter
                            visible: root.telemetry.layout !== ""
                            width: visible ? layoutLabel.implicitWidth + 20 : 0
                            onActivated: root.send({action: "layout"})
                            MacLabel { id: layoutLabel; anchors.centerIn: parent; text: root.telemetry.layout; font.weight: Font.DemiBold; font.pixelSize: 12 }
                        }

                        BarItem {
                            anchors.verticalCenter: parent.verticalCenter
                            visible: root.batteryInfo.level >= 0
                            width: visible ? barBattery.implicitWidth + 20 : 0
                            active: root.openPanel === "control"
                            onActivated: root.toggle("control")
                            Row {
                                id: barBattery
                                anchors.centerIn: parent
                                spacing: 6
                                MacLabel { text: root.batteryInfo.level + " %"; font.pixelSize: 12; anchors.verticalCenter: parent.verticalCenter }
                                BatteryIcon { level: root.batteryInfo.level; charging: root.batteryInfo.charging; anchors.verticalCenter: parent.verticalCenter }
                            }
                        }

                        BarItem {
                            anchors.verticalCenter: parent.verticalCenter
                            visible: root.telemetry.radios.wifi !== "absent"
                            width: visible ? 32 : 0
                            active: root.openPanel === "control"
                            onActivated: root.toggle("control")
                            Symbol { name: "wifi"; anchors.centerIn: parent; opacity: root.telemetry.radios.wifi === "connecté" ? 1 : 0.4 }
                        }

                        BarItem {
                            anchors.verticalCenter: parent.verticalCenter
                            width: 32
                            active: root.openPanel === "launcher"
                            onActivated: root.toggle("launcher")
                            Symbol { name: "search"; anchors.centerIn: parent; width: 15; height: 15 }
                        }

                        BarItem {
                            anchors.verticalCenter: parent.verticalCenter
                            width: 32
                            active: root.openPanel === "control"
                            onActivated: root.toggle("control")
                            Symbol { name: "control"; anchors.centerIn: parent }
                        }

                        BarItem {
                            anchors.verticalCenter: parent.verticalCenter
                            width: barClock.implicitWidth + 22
                            active: root.openPanel === "calendar"
                            onActivated: root.toggle("calendar")
                            MacLabel {
                                id: barClock
                                anchors.centerIn: parent
                                text: Qt.locale("fr_FR").toString(clock.date, display.compact ? "ddd d" : "ddd d MMM") + "  " + Qt.formatDateTime(clock.date, "HH:mm")
                                font.weight: Font.Medium
                            }
                        }

                        BarItem {
                            anchors.verticalCenter: parent.verticalCenter
                            visible: root.preview
                            width: visible ? closeLabel.implicitWidth + 20 : 0
                            onActivated: Qt.quit()
                            MacLabel { id: closeLabel; anchors.centerIn: parent; text: "Fermer l’aperçu"; font.pixelSize: 12; color: root.tSecondary }
                        }
                    }
                }
            }

            PanelWindow {
                id: catcher
                screen: display.modelData
                visible: root.openPanel !== ""
                anchors { top: true; bottom: true; left: true; right: true }
                color: "transparent"
                focusable: false
                exclusionMode: ExclusionMode.Ignore
                margins.top: root.barBottom
                WlrLayershell.namespace: root.namespace + "-catcher"
                WlrLayershell.layer: WlrLayer.Top
                WlrLayershell.keyboardFocus: WlrKeyboardFocus.None
                MouseArea {
                    anchors.fill: parent
                    acceptedButtons: Qt.AllButtons
                    onPressed: root.openPanel = ""
                }
            }

            MacPanel {
                screen: display.modelData
                id: calendarPanel
                name: "calendar"
                anchors.top: true
                anchors.right: true
                margins.right: 0
                sheetWidth: 300
                sheetHeight: 330
                sheetX: root.shadowPad
                sheetY: root.barBottom + 6 - margins.top
                implicitWidth: sheetWidth + root.shadowPad + 8
                property date month: new Date(clock.date.getFullYear(), clock.date.getMonth(), 1)
                readonly property bool current: month.getFullYear() === clock.date.getFullYear() && month.getMonth() === clock.date.getMonth()
                onShownChanged: month = new Date(clock.date.getFullYear(), clock.date.getMonth(), 1)

                body: Component {
                    Item {
                        Item {
                            anchors.fill: parent
                            anchors.margins: 16
                            Column {
                                spacing: 1
                                MacLabel {
                                    text: Qt.locale("fr_FR").toString(clock.date, "dddd d MMMM")
                                    font.pixelSize: 12
                                    font.weight: Font.DemiBold
                                    color: root.tSecondary
                                }
                                Row {
                                    spacing: 6
                                    MacLabel {
                                        text: Qt.locale("fr_FR").toString(calendarPanel.month, "MMMM")
                                        font.pixelSize: 21
                                        font.weight: Font.Bold
                                        font.capitalization: Font.Capitalize
                                    }
                                    MacLabel {
                                        text: Qt.formatDate(calendarPanel.month, "yyyy")
                                        font.pixelSize: 21
                                        color: root.tRed
                                    }
                                }
                            }
                            Row {
                                anchors.right: parent.right
                                y: 14
                                spacing: 2
                                BarItem {
                                    width: 26
                                    onActivated: calendarPanel.month = new Date(calendarPanel.month.getFullYear(), calendarPanel.month.getMonth() - 1, 1)
                                    Symbol { name: "left"; anchors.centerIn: parent; width: 14; height: 14 }
                                }
                                BarItem {
                                    width: 26
                                    onActivated: calendarPanel.month = new Date(clock.date.getFullYear(), clock.date.getMonth(), 1)
                                    Symbol { name: "dot"; anchors.centerIn: parent; width: 14; height: 14; opacity: calendarPanel.current ? 0.35 : 1 }
                                }
                                BarItem {
                                    width: 26
                                    onActivated: calendarPanel.month = new Date(calendarPanel.month.getFullYear(), calendarPanel.month.getMonth() + 1, 1)
                                    Symbol { name: "right"; anchors.centerIn: parent; width: 14; height: 14 }
                                }
                            }
                            Rectangle {
                                y: 60
                                width: parent.width
                                height: parent.height - 60
                                radius: 16
                                color: root.tModule
                                border.width: 1
                                border.color: root.tModuleEdge
                            }
                            Grid {
                                y: 64
                                x: 2
                                columns: 7
                                columnSpacing: 2
                                rowSpacing: 0
                                Repeater {
                                    model: ["lun", "mar", "mer", "jeu", "ven", "sam", "dim"]
                                    MacLabel {
                                        required property string modelData
                                        width: 36
                                        height: 24
                                        horizontalAlignment: Text.AlignHCenter
                                        verticalAlignment: Text.AlignVCenter
                                        text: modelData
                                        color: root.tSecondary
                                        font.pixelSize: 10
                                        font.weight: Font.DemiBold
                                        font.capitalization: Font.AllUppercase
                                    }
                                }
                                Repeater {
                                    model: 42
                                    Item {
                                        required property int index
                                        readonly property int offset: (calendarPanel.month.getDay() + 6) % 7
                                        readonly property date day: new Date(calendarPanel.month.getFullYear(), calendarPanel.month.getMonth(), index - offset + 1)
                                        readonly property bool inMonth: day.getMonth() === calendarPanel.month.getMonth()
                                        readonly property bool today: day.toDateString() === clock.date.toDateString()
                                        readonly property bool weekend: day.getDay() === 0 || day.getDay() === 6
                                        width: 36
                                        height: 33
                                        Rectangle {
                                            anchors.centerIn: parent
                                            width: 28
                                            height: 28
                                            radius: 14
                                            color: root.tRed
                                            visible: parent.today
                                        }
                                        MacLabel {
                                            anchors.centerIn: parent
                                            text: parent.day.getDate()
                                            font.pixelSize: 13
                                            color: parent.today ? "#ffffff" : !parent.inMonth ? root.tTertiary : parent.weekend ? root.tSecondary : root.tText
                                            font.weight: parent.today ? Font.Bold : Font.Medium
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }

            MacPanel {
                screen: display.modelData
                id: controlPanel
                name: "control"
                anchors.top: true
                anchors.right: true
                margins.right: 0
                sheetWidth: 340
                sheetHeight: content ? content.implicitHeight + 28 : 480
                sheetX: root.shadowPad
                sheetY: root.barBottom + 6 - margins.top
                implicitWidth: sheetWidth + root.shadowPad + 8
                sheetRadius: 26
                property string page: ""
                property bool typing: false
                WlrLayershell.keyboardFocus: shown && page === "wifi" && typing ? WlrKeyboardFocus.Exclusive : WlrKeyboardFocus.None
                onShownChanged: {
                    if (!shown)
                        page = "";
                    root.send({action: "watch", value: shown});
                }
                onPageChanged: root.send({action: "page", value: page})
                readonly property var wifi: root.telemetry.wifiPanel || ({available: false, networks: [], message: "", busy: false, ask: "", backend: ""})
                readonly property var bt: root.telemetry.bt || ({available: false, powered: false, devices: [], message: "", busy: false})
                readonly property var btConnected: (bt.devices || []).filter(d => d.connected)
                readonly property var media: root.telemetry.media || ({})
                readonly property bool playing: !!media.title
                readonly property var dnd: root.telemetry.dnd || ({available: false, on: false})

                property Component wifiPage: Component {
                    Item {
                        id: wifiView
                        property string chosen: ""
                        property bool hiddenForm: false
                        readonly property bool typing: (chosen !== "" && !networks.some(n => n.ssid === chosen && (n.active || (n.known && !controlPanel.wifi.ask)))) || hiddenForm
                        onTypingChanged: controlPanel.typing = typing
                        Component.onDestruction: controlPanel.typing = false
                        readonly property var networks: controlPanel.wifi.networks || []
                        readonly property bool on: root.telemetry.radios.wifi !== "bloqué"
                        function join(network, password) {
                            root.send({action: "wifi", value: {op: "connect", ssid: network, password: password || ""}});
                        }
                        Connections {
                            target: controlPanel
                            function onWifiChanged() {
                                if (controlPanel.wifi.ask && controlPanel.wifi.ask !== "")
                                    wifiView.chosen = controlPanel.wifi.ask;
                                else if (wifiView.networks.some(n => n.active && n.ssid === wifiView.chosen))
                                    wifiView.chosen = "";
                            }
                        }
                        PageHeader {
                            id: wifiHeader
                            title: "Wi-Fi"
                            detail: controlPanel.wifi.busy ? (controlPanel.wifi.message || "Recherche…") : (controlPanel.wifi.message || controlPanel.wifi.backend || "")
                            onBack: controlPanel.page = ""
                            BarItem {
                                width: 28
                                height: 28
                                onActivated: root.send({action: "wifi", value: {op: "scan"}})
                                Symbol { name: "refresh"; anchors.centerIn: parent; width: 14; height: 14; opacity: controlPanel.wifi.busy ? 0.4 : 1 }
                            }
                            MacSwitch {
                                anchors.verticalCenter: parent.verticalCenter
                                checked: wifiView.on
                                usable: root.telemetry.radios.wifi !== "absent"
                                onToggled: root.send({action: "wifi", value: {op: "power", on: !wifiView.on}})
                            }
                        }
                        Rectangle {
                            y: wifiHeader.height + 4
                            width: parent.width
                            height: parent.height - y - 40
                            radius: 16
                            color: root.tModule
                            border.width: 1
                            border.color: root.tModuleEdge
                            ListView {
                                id: networkList
                                anchors.fill: parent
                                anchors.margins: 6
                                clip: true
                                spacing: 2
                                boundsBehavior: Flickable.StopAtBounds
                                model: wifiView.networks
                                delegate: Rectangle {
                                    id: networkRow
                                    required property var modelData
                                    readonly property bool open: wifiView.chosen === modelData.ssid
                                    onOpenChanged: if (open && !modelData.active) Qt.callLater(() => passwordField.input.forceActiveFocus())
                                    width: ListView.view.width
                                    height: open ? (modelData.active ? 72 : modelData.secure && !modelData.known ? 78 : 72) : 36
                                    radius: 10
                                    color: open ? root.tHover : networkMouse.containsMouse ? root.tHover : "transparent"
                                    MouseArea {
                                        id: networkMouse
                                        width: parent.width
                                        height: 36
                                        hoverEnabled: true
                                        onClicked: {
                                            const n = networkRow.modelData;
                                            if (!n.active && (n.known || !n.secure))
                                                wifiView.join(n.ssid, "");
                                            else
                                                wifiView.chosen = networkRow.open ? "" : n.ssid;
                                        }
                                    }
                                    Rectangle {
                                        x: 8
                                        y: 6
                                        width: 24
                                        height: 24
                                        radius: 12
                                        color: networkRow.modelData.active ? root.tAccent : root.tCircle
                                        Symbol {
                                            anchors.centerIn: parent
                                            name: "wifi"
                                            width: 13
                                            height: 13
                                            tint: networkRow.modelData.active ? "#ffffff" : root.inkHex
                                            opacity: networkRow.modelData.signal >= 55 ? 1 : networkRow.modelData.signal >= 30 ? 0.7 : 0.45
                                        }
                                    }
                                    MacLabel {
                                        x: 40
                                        y: 9
                                        width: parent.width - 90
                                        elide: Text.ElideRight
                                        text: networkRow.modelData.ssid
                                        font.weight: networkRow.modelData.active ? Font.DemiBold : Font.Normal
                                    }
                                    Row {
                                        anchors.right: parent.right
                                        anchors.rightMargin: 10
                                        y: 10
                                        spacing: 6
                                        Symbol { visible: networkRow.modelData.secure; name: "lockSmall"; width: 13; height: 13; tint: root.dimHex }
                                        Symbol { visible: networkRow.modelData.active; name: "check"; width: 13; height: 13; tint: root.tAccent }
                                    }
                                    Row {
                                        visible: networkRow.open
                                        x: 40
                                        y: 38
                                        spacing: 6
                                        PlainField {
                                            id: passwordField
                                            visible: !networkRow.modelData.active
                                            width: networkRow.width - 40 - 10 - joinButton.width - 6
                                            secret: true
                                            placeholder: networkRow.modelData.known ? "Nouveau mot de passe" : "Mot de passe"
                                            onAccepted: wifiView.join(networkRow.modelData.ssid, text)
                                        }
                                        MacButton {
                                            id: joinButton
                                            visible: !networkRow.modelData.active
                                            primary: true
                                            text: "Rejoindre"
                                            width: 84
                                            onActivated: wifiView.join(networkRow.modelData.ssid, passwordField.text)
                                        }
                                        MacButton {
                                            visible: networkRow.modelData.active
                                            text: "Déconnecter"
                                            onActivated: { root.send({action: "wifi", value: {op: "disconnect"}}); wifiView.chosen = ""; }
                                        }
                                        MacButton {
                                            visible: networkRow.modelData.known
                                            text: "Oublier"
                                            onActivated: { root.send({action: "wifi", value: {op: "forget", ssid: networkRow.modelData.ssid}}); wifiView.chosen = ""; }
                                        }
                                    }
                                }
                                MacLabel {
                                    anchors.centerIn: parent
                                    width: parent.width - 32
                                    visible: networkList.count === 0
                                    horizontalAlignment: Text.AlignHCenter
                                    wrapMode: Text.WordWrap
                                    color: root.tSecondary
                                    text: !wifiView.on ? "Wi-Fi désactivé" : controlPanel.wifi.busy ? "Recherche des réseaux…"
                                        : controlPanel.wifi.available === false && controlPanel.wifi.message ? controlPanel.wifi.message : "Aucun réseau trouvé"
                                }
                            }
                        }
                        Item {
                            anchors.bottom: parent.bottom
                            width: parent.width
                            height: 32
                            BarItem {
                                visible: !wifiView.hiddenForm
                                height: 28
                                width: otherLabel.implicitWidth + 24
                                anchors.verticalCenter: parent.verticalCenter
                                onActivated: { wifiView.hiddenForm = true; Qt.callLater(() => hiddenName.input.forceActiveFocus()); }
                                MacLabel { id: otherLabel; anchors.centerIn: parent; text: "Autre réseau…"; color: root.tAccent }
                            }
                            Row {
                                visible: wifiView.hiddenForm
                                spacing: 6
                                anchors.verticalCenter: parent.verticalCenter
                                PlainField { id: hiddenName; width: 104; placeholder: "Nom" }
                                PlainField { id: hiddenPass; width: 104; secret: true; placeholder: "Mot de passe"; onAccepted: hiddenJoin.activated() }
                                MacButton {
                                    id: hiddenJoin
                                    primary: true
                                    text: "OK"
                                    width: 60
                                    onActivated: {
                                        root.send({action: "wifi", value: {op: "connect", ssid: hiddenName.text, password: hiddenPass.text, hidden: true}});
                                        wifiView.hiddenForm = false;
                                    }
                                }
                            }
                        }
                    }
                }

                property Component btPage: Component {
                    Item {
                        id: btView
                        readonly property var devices: controlPanel.bt.devices || []
                        PageHeader {
                            id: btHeader
                            title: "Bluetooth"
                            detail: controlPanel.bt.busy ? (controlPanel.bt.message || "…") : (controlPanel.bt.message || (controlPanel.bt.powered ? "Activé" : controlPanel.bt.available ? "Éteint" : ""))
                            onBack: controlPanel.page = ""
                            BarItem {
                                width: 28
                                height: 28
                                visible: controlPanel.bt.powered
                                onActivated: root.send({action: "bt", value: {op: "scan"}})
                                Symbol { name: "refresh"; anchors.centerIn: parent; width: 14; height: 14; opacity: controlPanel.bt.busy ? 0.4 : 1 }
                            }
                            MacSwitch {
                                anchors.verticalCenter: parent.verticalCenter
                                checked: !!controlPanel.bt.powered
                                usable: !!controlPanel.bt.available || root.telemetry.radios.bluetooth !== "absent"
                                onToggled: root.send({action: "bt", value: {op: "power"}})
                            }
                        }
                        Rectangle {
                            y: btHeader.height + 4
                            width: parent.width
                            height: parent.height - y
                            radius: 16
                            color: root.tModule
                            border.width: 1
                            border.color: root.tModuleEdge
                            ListView {
                                id: deviceList
                                anchors.fill: parent
                                anchors.margins: 6
                                clip: true
                                spacing: 2
                                boundsBehavior: Flickable.StopAtBounds
                                model: btView.devices
                                section.property: "paired"
                                delegate: Rectangle {
                                    id: deviceRow
                                    required property var modelData
                                    width: ListView.view.width
                                    height: 42
                                    radius: 10
                                    color: deviceMouse.containsMouse ? root.tHover : "transparent"
                                    MouseArea {
                                        id: deviceMouse
                                        anchors.fill: parent
                                        hoverEnabled: true
                                        onClicked: {
                                            const d = deviceRow.modelData;
                                            root.send({action: "bt", value: {op: d.connected ? "disconnect" : d.paired ? "connect" : "pair", mac: d.mac}});
                                        }
                                    }
                                    Rectangle {
                                        x: 8
                                        anchors.verticalCenter: parent.verticalCenter
                                        width: 26
                                        height: 26
                                        radius: 13
                                        color: deviceRow.modelData.connected ? root.tAccent : root.tCircle
                                        Symbol {
                                            anchors.centerIn: parent
                                            name: deviceRow.modelData.icon.indexOf("audio") >= 0 ? "headphones" : deviceRow.modelData.icon.indexOf("phone") >= 0 ? "device" : "bluetooth"
                                            width: 14
                                            height: 14
                                            tint: deviceRow.modelData.connected ? "#ffffff" : root.inkHex
                                        }
                                    }
                                    Column {
                                        x: 42
                                        width: parent.width - 42 - 40
                                        anchors.verticalCenter: parent.verticalCenter
                                        MacLabel { width: parent.width; elide: Text.ElideRight; text: deviceRow.modelData.name; font.weight: deviceRow.modelData.connected ? Font.DemiBold : Font.Normal }
                                        MacLabel {
                                            width: parent.width
                                            elide: Text.ElideRight
                                            font.pixelSize: 11
                                            color: root.tSecondary
                                            text: (deviceRow.modelData.connected ? "Connecté" : deviceRow.modelData.paired ? "Jumelé" : "Cliquer pour jumeler")
                                                + (deviceRow.modelData.battery >= 0 ? " · " + deviceRow.modelData.battery + " %" : "")
                                        }
                                    }
                                    BarItem {
                                        visible: deviceRow.modelData.paired
                                        anchors.right: parent.right
                                        anchors.rightMargin: 6
                                        anchors.verticalCenter: parent.verticalCenter
                                        width: 26
                                        height: 26
                                        onActivated: root.send({action: "bt", value: {op: "remove", mac: deviceRow.modelData.mac}})
                                        Symbol { name: "close"; anchors.centerIn: parent; width: 12; height: 12; tint: root.dimHex }
                                    }
                                }
                                MacLabel {
                                    anchors.centerIn: parent
                                    width: parent.width - 32
                                    visible: deviceList.count === 0
                                    horizontalAlignment: Text.AlignHCenter
                                    wrapMode: Text.WordWrap
                                    color: root.tSecondary
                                    text: !controlPanel.bt.available ? (controlPanel.bt.message || "Bluetooth indisponible")
                                        : !controlPanel.bt.powered ? "Bluetooth éteint" : controlPanel.bt.busy ? "Recherche des appareils…" : "Aucun appareil"
                                }
                            }
                        }
                    }
                }

                property Component soundPage: Component {
                    Item {
                        PageHeader {
                            id: soundHeader
                            title: "Sortie son"
                            detail: root.telemetry.muted ? "Coupé" : root.telemetry.volume >= 0 ? root.telemetry.volume + " %" : ""
                            onBack: controlPanel.page = ""
                        }
                        MacSlider {
                            y: soundHeader.height + 4
                            width: parent.width
                            glyph: root.telemetry.muted ? "speakerOff" : "speaker"
                            value: root.telemetry.muted ? 0 : root.telemetry.volume
                            available: root.telemetry.volume >= 0
                            onMoved: v => root.send({action: "volume", value: v})
                        }
                        Rectangle {
                            y: soundHeader.height + 42
                            width: parent.width
                            height: parent.height - y
                            radius: 16
                            color: root.tModule
                            border.width: 1
                            border.color: root.tModuleEdge
                            ListView {
                                id: sinkList
                                anchors.fill: parent
                                anchors.margins: 6
                                clip: true
                                spacing: 2
                                model: root.telemetry.sinks || []
                                delegate: Rectangle {
                                    id: sinkRow
                                    required property var modelData
                                    width: ListView.view.width
                                    height: 38
                                    radius: 10
                                    color: sinkMouse.containsMouse ? root.tHover : "transparent"
                                    MouseArea {
                                        id: sinkMouse
                                        anchors.fill: parent
                                        hoverEnabled: true
                                        onClicked: root.send({action: "sink", value: sinkRow.modelData.id})
                                    }
                                    Symbol { x: 10; anchors.verticalCenter: parent.verticalCenter; name: "speaker"; width: 15; height: 15; tint: sinkRow.modelData.default ? root.tAccent : root.inkHex }
                                    MacLabel {
                                        x: 34
                                        width: parent.width - 64
                                        anchors.verticalCenter: parent.verticalCenter
                                        elide: Text.ElideRight
                                        text: sinkRow.modelData.name
                                        font.weight: sinkRow.modelData.default ? Font.DemiBold : Font.Normal
                                    }
                                    Symbol { visible: sinkRow.modelData.default; anchors.right: parent.right; anchors.rightMargin: 10; anchors.verticalCenter: parent.verticalCenter; name: "check"; width: 13; height: 13; tint: root.tAccent }
                                }
                                MacLabel {
                                    anchors.centerIn: parent
                                    visible: sinkList.count === 0
                                    color: root.tSecondary
                                    text: "Aucune sortie trouvée (wpctl)"
                                }
                            }
                        }
                    }
                }

                body: Component {
                    Item {
                        implicitHeight: controlPanel.page === "" ? controlColumn.implicitHeight : 470
                        Column {
                            id: controlColumn
                            visible: controlPanel.page === ""
                            readonly property real half: (width - 10) / 2
                            x: 14
                            y: 14
                            width: controlPanel.sheetWidth - 28
                            spacing: 10

                            Row {
                                width: parent.width
                                spacing: 10
                                Module {
                                    width: controlColumn.half
                                    height: 146
                                    Column {
                                        x: 10
                                        y: 8
                                        width: parent.width - 20
                                        spacing: 2
                                        ToggleRow {
                                            width: parent.width
                                            title: "Wi-Fi"
                                            glyph: "wifi"
                                            checked: root.telemetry.radios.wifi === "connecté" || root.telemetry.radios.wifi === "déconnecté" || (root.telemetry.radios.wifi === "absent" && !!controlPanel.wifi.available)
                                            usable: (root.telemetry.radios.wifi !== "absent" && !!root.telemetry.tools.radio) || !!controlPanel.wifi.available
                                            detail: root.telemetry.wifiName ? root.telemetry.wifiName : root.telemetry.radios.wifi === "absent" && controlPanel.wifi.available ? "Non connecté"
                                                : ({"connecté": "Connecté", "déconnecté": "Non connecté", "bloqué": "Désactivé", "absent": "Absent"})[root.telemetry.radios.wifi] || ""
                                            expandable: true
                                            onOpened: controlPanel.page = "wifi"
                                            onActivated: {
                                                if (controlPanel.wifi.available)
                                                    root.send({action: "wifi", value: {op: "power", on: root.telemetry.radios.wifi === "bloqué"}});
                                                else
                                                    root.send({action: "radio", key: "wifi", value: root.telemetry.radios.wifi === "bloqué"});
                                            }
                                        }
                                        ToggleRow {
                                            width: parent.width
                                            title: "Bluetooth"
                                            glyph: "bluetooth"
                                            checked: root.telemetry.radios.bluetooth === "actif"
                                            usable: root.telemetry.radios.bluetooth !== "absent" && !!root.telemetry.tools.radio
                                            detail: controlPanel.btConnected.length > 0 ? controlPanel.btConnected.map(d => d.name).join(", ")
                                                : root.telemetry.radios.bluetooth === "actif" ? (controlPanel.bt.available && !controlPanel.bt.powered ? "Éteint" : "Activé")
                                                : root.telemetry.radios.bluetooth === "absent" ? "Absent" : "Désactivé"
                                            expandable: root.telemetry.radios.bluetooth !== "absent" || controlPanel.bt.available
                                            onOpened: controlPanel.page = "bluetooth"
                                            onActivated: {
                                                if (controlPanel.bt.available)
                                                    root.send({action: "bt", value: {op: "power"}});
                                                else
                                                    root.send({action: "radio", key: "bluetooth", value: root.telemetry.radios.bluetooth !== "actif"});
                                            }
                                        }
                                        ToggleRow {
                                            width: parent.width
                                            title: "Clavier"
                                            glyph: "keyboard"
                                            checked: false
                                            usable: root.telemetry.layouts > 1
                                            detail: root.telemetry.layoutName !== "" ? root.telemetry.layoutName : "—"
                                            onActivated: root.send({action: "layout"})
                                        }
                                    }
                                }
                                Column {
                                    width: controlColumn.half
                                    spacing: 10
                                    Module {
                                        width: parent.width
                                        height: 68
                                        ToggleRow {
                                            x: 10
                                            width: parent.width - 20
                                            anchors.verticalCenter: parent.verticalCenter
                                            title: "Concentration"
                                            glyph: "moon"
                                            checked: !!controlPanel.dnd.on
                                            usable: !!controlPanel.dnd.available
                                            detail: !controlPanel.dnd.available ? "Indisponible" : controlPanel.dnd.on ? "Ne pas déranger" : "Désactivée"
                                            onActivated: root.send({action: "dnd"})
                                        }
                                    }
                                    Row {
                                        spacing: 10
                                        Repeater {
                                            model: [
                                                {key: "appearance", glyph: "contrast", label: ({auto: "Auto", light: "Clair", dark: "Sombre"})[root.appearanceMode]},
                                                {key: "overview", glyph: "overview", label: "Bureaux"}
                                            ]
                                            Module {
                                                id: squareTile
                                                required property var modelData
                                                width: (controlColumn.half - 10) / 2
                                                height: 68
                                                Toggle {
                                                    anchors.horizontalCenter: parent.horizontalCenter
                                                    y: 8
                                                    glyph: squareTile.modelData.glyph
                                                    checked: squareTile.modelData.key === "appearance" ? root.dark : !!root.telemetry.overview
                                                    onActivated: {
                                                        if (squareTile.modelData.key === "appearance") {
                                                            root.send({action: "appearance", value: root.cycle(["auto", "light", "dark"], root.appearanceMode)});
                                                        } else {
                                                            root.openPanel = "";
                                                            root.send({action: "overview"});
                                                        }
                                                    }
                                                }
                                                MacLabel {
                                                    anchors.horizontalCenter: parent.horizontalCenter
                                                    y: 44
                                                    text: squareTile.modelData.label
                                                    font.pixelSize: 10
                                                    font.weight: Font.DemiBold
                                                }
                                            }
                                        }
                                    }
                                }
                            }

                            Module {
                                width: parent.width
                                height: screenError.visible ? 84 : 68
                                MacLabel { x: 14; y: 10; text: "Écran"; font.pixelSize: 12; font.weight: Font.DemiBold }
                                MacLabel {
                                    id: screenError
                                    x: 14
                                    y: 62
                                    width: parent.width - 28
                                    visible: text !== ""
                                    text: (root.telemetry.lightError || {}).screen || ""
                                    elide: Text.ElideRight
                                    font.pixelSize: 11
                                    color: root.tRed
                                }
                                MacLabel {
                                    anchors.right: parent.right
                                    anchors.rightMargin: 14
                                    y: 10
                                    visible: root.telemetry.brightness >= 0 && !!root.telemetry.tools.brightness
                                    text: root.telemetry.brightness + " %"
                                    font.pixelSize: 11
                                    color: root.tSecondary
                                }
                                MacSlider {
                                    x: 12
                                    y: 32
                                    width: parent.width - 24
                                    glyph: "sun"
                                    value: root.telemetry.brightness
                                    available: root.telemetry.brightness >= 0 && !!root.telemetry.tools.brightness
                                    onMoved: v => root.send({action: "brightness", value: v})
                                }
                            }

                            Module {
                                width: parent.width
                                height: kbdError.visible ? 84 : 68
                                visible: root.telemetry.kbd >= 0 && !!root.telemetry.tools.kbd
                                MacLabel { x: 14; y: 10; text: "Clavier rétroéclairé"; font.pixelSize: 12; font.weight: Font.DemiBold }
                                MacLabel {
                                    id: kbdError
                                    x: 14
                                    y: 62
                                    width: parent.width - 28
                                    visible: text !== ""
                                    text: (root.telemetry.lightError || {}).kbd || ""
                                    elide: Text.ElideRight
                                    font.pixelSize: 11
                                    color: root.tRed
                                }
                                MacLabel {
                                    anchors.right: parent.right
                                    anchors.rightMargin: 14
                                    y: 10
                                    text: root.telemetry.kbd + " %"
                                    font.pixelSize: 11
                                    color: root.tSecondary
                                }
                                MacSlider {
                                    x: 12
                                    y: 32
                                    width: parent.width - 24
                                    glyph: "keyboard"
                                    value: root.telemetry.kbd
                                    onMoved: v => root.send({action: "kbd", value: v})
                                }
                            }

                            Module {
                                width: parent.width
                                height: 68
                                MacLabel { x: 14; y: 10; text: "Son"; font.pixelSize: 12; font.weight: Font.DemiBold }
                                BarItem {
                                    id: outputButton
                                    anchors.right: parent.right
                                    anchors.rightMargin: 8
                                    y: 6
                                    height: 22
                                    width: 26
                                    visible: root.telemetry.volume >= 0
                                    onActivated: controlPanel.page = "sound"
                                    Symbol { name: "headphones"; anchors.centerIn: parent; width: 13; height: 13; tint: root.dimHex }
                                }
                                BarItem {
                                    anchors.right: outputButton.left
                                    anchors.rightMargin: 2
                                    y: 6
                                    height: 22
                                    width: soundState.implicitWidth + 30
                                    visible: root.telemetry.volume >= 0
                                    active: root.telemetry.muted
                                    onActivated: root.send({action: "mute"})
                                    Row {
                                        anchors.centerIn: parent
                                        spacing: 4
                                        Symbol { name: root.telemetry.muted ? "speakerOff" : "speaker"; width: 13; height: 13; anchors.verticalCenter: parent.verticalCenter; tint: root.dimHex }
                                        MacLabel { id: soundState; text: root.telemetry.muted ? "Coupé" : root.telemetry.volume + " %"; font.pixelSize: 11; color: root.tSecondary }
                                    }
                                }
                                MacSlider {
                                    x: 12
                                    y: 32
                                    width: parent.width - 24
                                    glyph: root.telemetry.muted ? "speakerOff" : "speaker"
                                    value: root.telemetry.muted ? 0 : root.telemetry.volume
                                    available: root.telemetry.volume >= 0
                                    onMoved: v => root.send({action: "volume", value: v})
                                }
                            }

                            Module {
                                width: parent.width
                                height: 66
                                Rectangle {
                                    id: artBox
                                    x: 11
                                    anchors.verticalCenter: parent.verticalCenter
                                    width: 44
                                    height: 44
                                    radius: 10
                                    color: root.dark ? "#2effffff" : "#14000000"
                                    clip: true
                                    Symbol { anchors.centerIn: parent; name: "note"; width: 20; height: 20; tint: root.dimHex; visible: artImage.status !== Image.Ready }
                                    Image {
                                        id: artImage
                                        anchors.fill: parent
                                        source: controlPanel.playing && controlPanel.media.art ? controlPanel.media.art : ""
                                        sourceSize.width: 88
                                        sourceSize.height: 88
                                        fillMode: Image.PreserveAspectCrop
                                        asynchronous: true
                                        visible: status === Image.Ready
                                    }
                                }
                                Column {
                                    anchors.left: artBox.right
                                    anchors.leftMargin: 10
                                    anchors.right: mediaButtons.left
                                    anchors.rightMargin: 6
                                    anchors.verticalCenter: parent.verticalCenter
                                    MacLabel { width: parent.width; elide: Text.ElideRight; text: controlPanel.playing ? controlPanel.media.title : "Aucune lecture"; font.pixelSize: 12; font.weight: Font.DemiBold; color: controlPanel.playing ? root.tText : root.tSecondary }
                                    MacLabel { width: parent.width; elide: Text.ElideRight; text: controlPanel.playing ? (controlPanel.media.artist || "") : "Lecteur"; font.pixelSize: 11; color: root.tSecondary }
                                }
                                Row {
                                    id: mediaButtons
                                    anchors.right: parent.right
                                    anchors.rightMargin: 8
                                    anchors.verticalCenter: parent.verticalCenter
                                    spacing: 0
                                    opacity: controlPanel.playing ? 1 : 0.4
                                    Repeater {
                                        model: ["backward", "playpause", "forward"]
                                        BarItem {
                                            id: mediaButton
                                            required property string modelData
                                            width: 30
                                            height: 30
                                            enabled: controlPanel.playing
                                            onActivated: root.send({action: "media", value: ({backward: "previous", playpause: "play-pause", forward: "next"})[mediaButton.modelData]})
                                            Symbol {
                                                anchors.centerIn: parent
                                                name: mediaButton.modelData === "playpause" ? (controlPanel.media.status === "Playing" ? "pause" : "play") : mediaButton.modelData
                                                width: mediaButton.modelData === "playpause" ? 17 : 15
                                                height: width
                                            }
                                        }
                                    }
                                }
                            }

                            Row {
                                width: parent.width
                                spacing: 10
                                Module {
                                    width: controlColumn.half
                                    height: 54
                                    Row {
                                        x: 13
                                        anchors.verticalCenter: parent.verticalCenter
                                        spacing: 9
                                        BatteryIcon {
                                            anchors.verticalCenter: parent.verticalCenter
                                            level: root.batteryInfo.level
                                            charging: root.batteryInfo.charging
                                        }
                                        Column {
                                            anchors.verticalCenter: parent.verticalCenter
                                            MacLabel { text: root.batteryInfo.level >= 0 ? root.batteryInfo.level + " %" : "Batterie"; font.pixelSize: 12; font.weight: Font.DemiBold }
                                            MacLabel {
                                                text: root.batteryInfo.level < 0 ? "Absente" : root.telemetry.batteryTime ? root.telemetry.batteryTime : root.batteryInfo.charging ? "En charge" : (root.telemetry.battery.split(" · ")[1] || "")
                                                font.pixelSize: 11
                                                color: root.tSecondary
                                                font.capitalization: Font.Capitalize
                                            }
                                        }
                                    }
                                }
                                Module {
                                    width: controlColumn.half
                                    height: 54
                                    Row {
                                        x: 13
                                        anchors.verticalCenter: parent.verticalCenter
                                        spacing: 9
                                        Symbol { name: "gauge"; width: 18; height: 18; anchors.verticalCenter: parent.verticalCenter }
                                        Column {
                                            anchors.verticalCenter: parent.verticalCenter
                                            MacLabel { text: "Processeur " + (root.telemetry.cpu >= 0 ? root.telemetry.cpu + " %" : "—"); font.pixelSize: 11; font.weight: Font.DemiBold }
                                            MacLabel {
                                                text: "Mémoire " + (root.telemetry.memory >= 0 ? root.telemetry.memory + " %" : "—") + (root.telemetry.temperature >= 0 ? " · " + root.telemetry.temperature + " °C" : "")
                                                font.pixelSize: 11
                                                color: root.telemetry.temperature > 80 ? root.tRed : root.tSecondary
                                            }
                                        }
                                    }
                                }
                            }
                        }
                        Loader {
                            x: 14
                            y: 12
                            width: controlPanel.sheetWidth - 28
                            height: 470 - 4
                            active: controlPanel.page !== ""
                            sourceComponent: controlPanel.page === "wifi" ? controlPanel.wifiPage : controlPanel.page === "bluetooth" ? controlPanel.btPage : controlPanel.soundPage
                        }
                    }
                }
            }

            MacPanel {
                screen: display.modelData
                id: powerPanel
                name: "power"
                anchors.top: true
                anchors.left: true
                margins.left: 0
                sheetWidth: 268
                sheetHeight: content ? content.implicitHeight + 12 : 220
                sheetX: 8
                implicitWidth: sheetWidth + 8 + root.shadowPad
                sheetMenu: true
                sheetRadius: 12
                property string armed: ""
                onShownChanged: armed = ""

                body: Component {
                    Item {
                        implicitHeight: powerColumn.implicitHeight
                        Column {
                            id: powerColumn
                            x: 6
                            y: 6
                            width: powerPanel.sheetWidth - 12
                            spacing: 0
                            MenuItem {
                                text: "Vue d’ensemble des bureaux"
                                glyph: "overview"
                                onActivated: {
                                    root.openPanel = "";
                                    root.send({action: "overview"});
                                }
                            }
                            MenuItem {
                                text: "Rechercher une app…"
                                glyph: "search"
                                onActivated: root.openPanel = "launcher"
                            }
                            MenuSeparator {}
                            Repeater {
                                model: [
                                    {key: "lock", label: "Verrouiller l’écran", glyph: "lock", ok: !!root.telemetry.tools.lock, confirm: false},
                                    {key: "sep", label: "", glyph: "", ok: !!root.telemetry.tools.lock || !!root.telemetry.tools.power, confirm: false},
                                    {key: "reboot", label: "Redémarrer…", glyph: "reboot", ok: !!root.telemetry.tools.power, confirm: true},
                                    {key: "poweroff", label: "Éteindre…", glyph: "power", ok: !!root.telemetry.tools.power, confirm: true},
                                    {key: "sep", label: "", glyph: "", ok: !!root.telemetry.tools.power, confirm: false},
                                    {key: "logout", label: "Fermer la session…", glyph: "logout", ok: true, confirm: true}
                                ]
                                Item {
                                    id: powerEntry
                                    required property var modelData
                                    width: parent.width
                                    visible: modelData.ok
                                    height: !visible ? 0 : modelData.key === "sep" ? 11 : 26
                                    MenuSeparator { visible: powerEntry.modelData.key === "sep"; width: parent.width }
                                    MenuItem {
                                        visible: powerEntry.modelData.key !== "sep"
                                        width: parent.width
                                        glyph: powerEntry.modelData.glyph
                                        danger: powerPanel.armed === powerEntry.modelData.key
                                        text: powerPanel.armed === powerEntry.modelData.key ? "Cliquer encore pour confirmer" : powerEntry.modelData.label
                                        onActivated: {
                                            if (powerEntry.modelData.confirm && powerPanel.armed !== powerEntry.modelData.key) {
                                                powerPanel.armed = powerEntry.modelData.key;
                                                return;
                                            }
                                            root.openPanel = "";
                                            root.send({action: "power", value: powerEntry.modelData.key});
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }

            PanelWindow {
                id: launcher
                screen: display.modelData
                readonly property bool shown: root.openPanel === "launcher"
                property real reveal: shown ? 1 : 0
                readonly property real fieldWidth: Math.min(680, display.modelData.width - 80)
                readonly property real cardHeight: Math.min(400, display.modelData.height - 360)
                visible: reveal > 0.01
                anchors.top: true
                margins.top: Math.max(root.barBottom + 20, Math.round(display.modelData.height * 0.17) - root.shadowPad)
                implicitWidth: fieldWidth + 2 * root.shadowPad
                implicitHeight: 56 + 12 + cardHeight + 2 * root.shadowPad
                color: "transparent"
                focusable: true
                exclusionMode: ExclusionMode.Ignore
                WlrLayershell.namespace: root.namespace + "-panel"
                WlrLayershell.layer: WlrLayer.Overlay
                WlrLayershell.keyboardFocus: shown ? WlrKeyboardFocus.Exclusive : WlrKeyboardFocus.None
                mask: Region {
                    Region { item: field }
                    Region { item: card }
                }
                BackgroundEffect.blurRegion: Region {
                    Region { item: field; radius: 28 }
                    Region { item: card; radius: 24 }
                }
                Behavior on reveal { NumberAnimation { duration: 170; easing.type: Easing.OutCubic } }
                property string query: ""
                readonly property bool searching: query.trim() !== ""
                readonly property var matches: {
                    if (!visible)
                        return [];
                    const q = query.trim().toLowerCase();
                    if (q === "")
                        return root.launcherApps;
                    const starts = root.launcherApps.filter(a => a.name.toLowerCase().startsWith(q));
                    const rest = root.launcherApps.filter(a => !a.name.toLowerCase().startsWith(q) && (a.name.toLowerCase().indexOf(q) >= 0 || a.id.toLowerCase().indexOf(q) >= 0));
                    return starts.concat(rest);
                }
                readonly property real listHeight: searching ? (matches.length > 0 ? Math.min(matches.length, 8) * 44 + 16 : 52) : cardHeight

                function open(index) {
                    if (index < 0 || index >= matches.length)
                        return;
                    root.send({action: "open", key: matches[index].id});
                    root.openPanel = "";
                }

                function iconSources(entry) {
                    const list = [];
                    const name = entry.icon || "";
                    if (name.startsWith("/"))
                        list.push("file://" + encodeURI(name));
                    else if (name !== "") {
                        const path = Quickshell.iconPath(name, true);
                        if (path !== "")
                            list.push(path);
                    }
                    list.push(root.glyphs.app);
                    return list;
                }

                onShownChanged: if (!shown) query = ""

                Item {
                    id: launcherFrame
                    anchors.fill: parent
                    opacity: launcher.reveal
                    scale: 0.97 + 0.03 * launcher.reveal
                    transformOrigin: Item.Top

                    SoftShadow {
                        x: field.x
                        y: field.y
                        width: field.width
                        height: field.height
                        radius: field.radius
                    }

                    Material {
                        id: field
                        x: root.shadowPad
                        y: root.shadowPad
                        width: launcher.fieldWidth
                        height: 56
                        radius: 28

                        Loader {
                            anchors.fill: parent
                            active: launcher.visible
                            sourceComponent: Item {
                                Symbol { name: "search"; x: 20; anchors.verticalCenter: parent.verticalCenter; width: 20; height: 20; tint: root.dimHex }
                                TextInput {
                                    id: search
                                    x: 52
                                    width: parent.width - 72
                                    anchors.verticalCenter: parent.verticalCenter
                                    color: root.tText
                                    selectionColor: root.tAccent
                                    font.pixelSize: 21
                                    font.family: root.fontFamily
                                    font.weight: Font.Normal
                                    clip: true
                                    focus: true
                                    Component.onCompleted: forceActiveFocus()
                                    onTextChanged: launcher.query = text
                                    Keys.onEscapePressed: root.openPanel = ""
                                    Keys.onReturnPressed: launcher.open(cardLoader.item ? cardLoader.item.view.currentIndex : -1)
                                    Keys.onEnterPressed: launcher.open(cardLoader.item ? cardLoader.item.view.currentIndex : -1)
                                    Keys.onDownPressed: if (cardLoader.item) cardLoader.item.down()
                                    Keys.onUpPressed: if (cardLoader.item) cardLoader.item.up()
                                    Keys.onLeftPressed: event => { if (launcher.searching || !cardLoader.item) event.accepted = false; else cardLoader.item.left(); }
                                    Keys.onRightPressed: event => { if (launcher.searching || !cardLoader.item) event.accepted = false; else cardLoader.item.right(); }
                                    MacLabel {
                                        visible: search.text === ""
                                        text: "Recherche Spotlight"
                                        color: root.tTertiary
                                        font.pixelSize: 21
                                    }
                                }
                            }
                        }
                    }

                    SoftShadow {
                        x: card.x
                        y: card.y
                        width: card.width
                        height: card.height
                        radius: card.radius
                        strength: 0.8
                    }

                    Material {
                        id: card
                        x: root.shadowPad
                        y: field.y + field.height + 12
                        width: launcher.fieldWidth
                        height: launcher.listHeight
                        radius: 24

                        Loader {
                            id: cardLoader
                            anchors.fill: parent
                            active: launcher.visible
                            sourceComponent: Item {
                                readonly property var view: launcher.searching ? results : grid
                                function down() { if (launcher.searching) results.incrementCurrentIndex(); else grid.moveCurrentIndexDown(); }
                                function up() { if (launcher.searching) results.decrementCurrentIndex(); else grid.moveCurrentIndexUp(); }
                                function left() { grid.moveCurrentIndexLeft(); }
                                function right() { grid.moveCurrentIndexRight(); }

                                Connections {
                                    target: launcher
                                    function onQueryChanged() {
                                        grid.currentIndex = 0;
                                        results.currentIndex = 0;
                                    }
                                }

                                ListView {
                                    id: results
                                    visible: launcher.searching
                                    x: 8
                                    y: 8
                                    width: parent.width - 16
                                    height: Math.min(count, 8) * 44
                                    clip: true
                                    model: launcher.searching ? launcher.matches : []
                                    boundsBehavior: Flickable.StopAtBounds
                                    highlightMoveDuration: 0
                                    highlight: Rectangle { radius: 12; color: root.tAccent }
                                    delegate: Item {
                                        id: resultRow
                                        required property var modelData
                                        required property int index
                                        readonly property bool current: ListView.isCurrentItem
                                        width: ListView.view.width
                                        height: 44
                                        property int attempt: 0
                                        readonly property var sources: launcher.iconSources(modelData)
                                        Image {
                                            x: 10
                                            anchors.verticalCenter: parent.verticalCenter
                                            width: 30
                                            height: 30
                                            sourceSize.width: 64
                                            sourceSize.height: 64
                                            source: resultRow.sources[Math.min(resultRow.attempt, resultRow.sources.length - 1)]
                                            asynchronous: true
                                            smooth: true
                                            mipmap: true
                                            fillMode: Image.PreserveAspectFit
                                            onStatusChanged: {
                                                if ((status === Image.Error || (status === Image.Ready && implicitWidth < 2)) && resultRow.attempt < resultRow.sources.length - 1)
                                                    resultRow.attempt += 1;
                                            }
                                        }
                                        MacLabel {
                                            x: 50
                                            width: parent.width - 150
                                            anchors.verticalCenter: parent.verticalCenter
                                            elide: Text.ElideRight
                                            text: resultRow.modelData.name
                                            font.pixelSize: 15
                                            color: resultRow.current ? "#ffffff" : root.tText
                                        }
                                        MacLabel {
                                            anchors.right: parent.right
                                            anchors.rightMargin: 14
                                            anchors.verticalCenter: parent.verticalCenter
                                            text: "Application"
                                            font.pixelSize: 12
                                            color: resultRow.current ? "#d9ffffff" : root.tTertiary
                                        }
                                        MouseArea {
                                            anchors.fill: parent
                                            hoverEnabled: true
                                            onEntered: results.currentIndex = resultRow.index
                                            onClicked: launcher.open(resultRow.index)
                                        }
                                    }
                                }

                                MacLabel {
                                    visible: launcher.searching && results.count === 0
                                    x: 22
                                    anchors.verticalCenter: parent.verticalCenter
                                    text: "Aucun résultat"
                                    color: root.tSecondary
                                    font.pixelSize: 14
                                }

                                MacLabel {
                                    visible: !launcher.searching
                                    x: 22
                                    y: 14
                                    text: "Applications"
                                    font.pixelSize: 12
                                    font.weight: Font.DemiBold
                                    color: root.tSecondary
                                }

                                GridView {
                                    id: grid
                                    visible: !launcher.searching
                                    x: 12
                                    y: 36
                                    width: parent.width - 24
                                    height: parent.height - 44
                                    clip: true
                                    cellWidth: Math.floor(width / Math.max(1, Math.floor(width / 104)))
                                    cellHeight: 96
                                    model: launcher.searching ? [] : launcher.matches
                                    boundsBehavior: Flickable.StopAtBounds
                                    highlightMoveDuration: 0
                                    highlight: Rectangle { radius: 16; color: root.tHover }
                                    cacheBuffer: 0

                                    delegate: Item {
                                        id: appCell
                                        required property var modelData
                                        required property int index
                                        width: grid.cellWidth
                                        height: grid.cellHeight
                                        property int attempt: 0
                                        readonly property var sources: launcher.iconSources(modelData)
                                        Image {
                                            anchors.horizontalCenter: parent.horizontalCenter
                                            y: 10
                                            width: 50
                                            height: 50
                                            scale: cellMouse.pressed ? 0.92 : 1
                                            sourceSize.width: 96
                                            sourceSize.height: 96
                                            source: appCell.sources[Math.min(appCell.attempt, appCell.sources.length - 1)]
                                            asynchronous: true
                                            smooth: true
                                            mipmap: true
                                            fillMode: Image.PreserveAspectFit
                                            onStatusChanged: {
                                                if ((status === Image.Error || (status === Image.Ready && implicitWidth < 2)) && appCell.attempt < appCell.sources.length - 1)
                                                    appCell.attempt += 1;
                                            }
                                        }
                                        MacLabel {
                                            y: 66
                                            width: parent.width - 8
                                            x: 4
                                            horizontalAlignment: Text.AlignHCenter
                                            elide: Text.ElideRight
                                            text: appCell.modelData.name
                                            font.pixelSize: 11
                                        }
                                        MouseArea {
                                            id: cellMouse
                                            anchors.fill: parent
                                            hoverEnabled: true
                                            onEntered: grid.currentIndex = appCell.index
                                            onClicked: launcher.open(appCell.index)
                                        }
                                    }

                                    MacLabel {
                                        anchors.centerIn: parent
                                        visible: grid.count === 0
                                        text: "Aucune application trouvée"
                                        color: root.tSecondary
                                    }
                                }
                            }
                        }
                    }
                }
            }

            PanelWindow {
                id: osd
                screen: display.modelData
                property real reveal: root.osdVisible ? 1 : 0
                Behavior on reveal { NumberAnimation { duration: 180; easing.type: Easing.OutCubic } }
                visible: reveal > 0.01
                anchors.top: true
                anchors.right: true
                margins.top: Math.max(0, root.barBottom + 6 - root.shadowPad)
                margins.right: 0
                implicitWidth: 300 + root.shadowPad + 8
                implicitHeight: 52 + 2 * root.shadowPad
                color: "transparent"
                focusable: false
                exclusionMode: ExclusionMode.Ignore
                WlrLayershell.namespace: root.namespace + "-panel"
                WlrLayershell.layer: WlrLayer.Overlay
                WlrLayershell.keyboardFocus: WlrKeyboardFocus.None
                mask: Region {}
                BackgroundEffect.blurRegion: Region { item: osdBody; radius: 26 }

                Item {
                    x: root.shadowPad
                    y: root.barBottom + 6 - osd.margins.top
                    width: 300
                    height: 52
                    opacity: osd.reveal
                    transform: Translate { x: (1 - osd.reveal) * 24 }

                    SoftShadow {
                        anchors.fill: parent
                        radius: 26
                        strength: 0.8
                    }

                    Material {
                        id: osdBody
                        anchors.fill: parent
                        radius: 26

                        Loader {
                            anchors.fill: parent
                            active: osd.visible
                            sourceComponent: Item {
                                Symbol {
                                    x: 18
                                    anchors.verticalCenter: parent.verticalCenter
                                    width: 18
                                    height: 18
                                    name: root.osdKind === "brightness" ? "sun" : root.osdKind === "mute" ? "speakerOff" : "speaker"
                                }
                                MacSlider {
                                    x: 48
                                    width: parent.width - 48 - 62
                                    anchors.verticalCenter: parent.verticalCenter
                                    height: 8
                                    interactive: false
                                    glyph: ""
                                    value: root.osdKind === "mute" ? 0 : root.osdValue
                                }
                                MacLabel {
                                    anchors.right: parent.right
                                    anchors.rightMargin: 18
                                    anchors.verticalCenter: parent.verticalCenter
                                    text: root.osdKind === "mute" ? "Coupé" : Math.round(root.osdValue) + " %"
                                    font.pixelSize: 12
                                    font.weight: Font.DemiBold
                                    color: root.tSecondary
                                }
                            }
                        }
                    }
                }
            }
            PanelWindow {
                id: dockWindow
                screen: display.modelData
                anchors.bottom: true
                margins.bottom: root.bottomOffset
                color: "transparent"
                focusable: false
                exclusionMode: ExclusionMode.Ignore
                Component.onCompleted: {
                    if (root.reserve)
                        exclusiveZone = Qt.binding(() => dock.slabHeight + 6);
                }
                WlrLayershell.namespace: root.namespace + "-dock"
                WlrLayershell.layer: WlrLayer.Top
                WlrLayershell.keyboardFocus: WlrKeyboardFocus.None
                implicitWidth: Math.min(display.modelData.width, dock.restWidth + 2 * dock.pad + dock.maxGrowth + 160)
                implicitHeight: dock.slabHeight + (dock.peak - dock.base) + dock.bounceHeight + 56
                mask: Region { item: hitZone }
                BackgroundEffect.blurRegion: Region { item: slab; radius: dock.radius }

                Item {
                    id: dock
                    anchors.fill: parent

                    readonly property int count: dockItems.count
                    readonly property real base: Math.max(36, Math.min(52, Math.floor((display.modelData.width - 220) / Math.max(1, count) - spacing)))
                    readonly property real peak: Math.round(base * 1.62)
                    readonly property real spacing: 10
                    readonly property real gapWidth: 22
                    readonly property real pad: 12
                    readonly property real slabHeight: base + 24
                    readonly property real radius: Math.round(slabHeight * 0.36)
                    readonly property real bounceHeight: Math.round(base * 0.5)
                    readonly property real sigma: (base + spacing) * 1.25
                    readonly property real maxGrowth: (peak - base) * 3.2
                    readonly property real restWidth: count > 0 ? count * (base + spacing) - spacing + root.dockGaps * gapWidth : 0
                    property real magnify: hover.hovered ? 1 : 0
                    property real focusX: 0
                    property bool glide: false
                    property var hovered: null
                    property string bubbleText: ""

                    Behavior on magnify {
                        NumberAnimation { duration: 210; easing.type: Easing.OutCubic }
                    }
                    Behavior on focusX {
                        enabled: dock.glide
                        SpringAnimation { spring: 5.5; damping: 0.42; epsilon: 0.1 }
                    }

                    function track(x) {
                        focusX = restWidth / 2 + (x - width / 2);
                    }

                    onHoveredChanged: if (hovered) bubbleText = hovered.name

                    Rectangle {
                        x: slab.x + 6
                        y: slab.y + 10
                        width: slab.width - 12
                        height: slab.height - 4
                        radius: dock.radius
                        color: "#1a000000"
                        visible: dock.count > 0
                    }

                    Rectangle {
                        id: slab
                        width: dock.count > 0 ? row.width + 2 * dock.pad : 0
                        height: dock.slabHeight
                        x: Math.round((dock.width - width) / 2)
                        y: dock.height - height
                        radius: dock.radius
                        visible: dock.count > 0
                        gradient: Gradient {
                            GradientStop { position: 0; color: "#4a2b3242" }
                            GradientStop { position: 0.5; color: "#38202634" }
                            GradientStop { position: 1; color: "#4c1a1f2b" }
                        }

                        Rectangle {
                            x: 1
                            y: 1
                            width: parent.width - 2
                            height: Math.round(parent.height * 0.52)
                            radius: dock.radius - 1
                            gradient: Gradient {
                                GradientStop { position: 0; color: "#30ffffff" }
                                GradientStop { position: 0.45; color: "#0cffffff" }
                                GradientStop { position: 1; color: "#00ffffff" }
                            }
                        }

                        Rectangle {
                            x: dock.radius * 0.8
                            y: 1
                            width: parent.width - dock.radius * 1.6
                            height: 1
                            gradient: Gradient {
                                orientation: Gradient.Horizontal
                                GradientStop { position: 0; color: "#00ffffff" }
                                GradientStop { position: 0.3; color: "#bfffffff" }
                                GradientStop { position: 0.7; color: "#bfffffff" }
                                GradientStop { position: 1; color: "#00ffffff" }
                            }
                        }

                        Shape {
                            anchors.fill: parent
                            ShapePath {
                                strokeWidth: -1
                                strokeColor: "transparent"
                                fillRule: ShapePath.OddEvenFill
                                fillGradient: LinearGradient {
                                    x1: 0; y1: 0; x2: 0; y2: slab.height
                                    GradientStop { position: 0; color: "#a6ffffff" }
                                    GradientStop { position: 0.3; color: "#33ffffff" }
                                    GradientStop { position: 0.7; color: "#14ffffff" }
                                    GradientStop { position: 1; color: "#52ffffff" }
                                }
                                PathRectangle { x: 0; y: 0; width: slab.width; height: slab.height; radius: dock.radius }
                                PathRectangle { x: 1; y: 1; width: slab.width - 2; height: slab.height - 2; radius: dock.radius - 1 }
                            }
                        }

                        Shape {
                            x: 2
                            y: 2
                            width: parent.width - 4
                            height: parent.height - 4
                            ShapePath {
                                strokeWidth: -1
                                strokeColor: "transparent"
                                fillRule: ShapePath.OddEvenFill
                                fillGradient: LinearGradient {
                                    x1: 0; y1: 0; x2: 0; y2: slab.height - 4
                                    GradientStop { position: 0; color: "#24000000" }
                                    GradientStop { position: 0.45; color: "#00ffffff" }
                                    GradientStop { position: 0.8; color: "#10ffffff" }
                                    GradientStop { position: 1; color: "#40ffffff" }
                                }
                                PathRectangle { x: 0; y: 0; width: slab.width - 4; height: slab.height - 4; radius: dock.radius - 2 }
                                PathRectangle { x: 1.5; y: 1.5; width: slab.width - 7; height: slab.height - 7; radius: dock.radius - 3.5 }
                            }
                        }
                    }

                    Item {
                        id: hitZone
                        x: slab.x
                        width: slab.width
                        y: slab.y - (dock.peak - dock.base) * dock.magnify
                        height: dock.height - y
                        visible: dock.count > 0
                    }

                    HoverHandler {
                        id: hover
                        onHoveredChanged: {
                            if (hovered) {
                                dock.glide = false;
                                dock.track(point.position.x);
                                dock.glide = true;
                            }
                        }
                        onPointChanged: if (hovered) dock.track(point.position.x)
                    }

                    Row {
                        id: row
                        x: slab.x + dock.pad
                        y: slab.y + 10
                        height: dock.base
                        spacing: dock.spacing

                        Repeater {
                            model: dockItems

                            Item {
                                id: tile
                                required property int index
                                required property string key
                                required property string name
                                required property string icons
                                required property string glyph
                                required property int running
                                required property bool focused
                                required property bool urgent
                                required property bool launchable
                                required property bool gap
                                required property int gaps
                                readonly property real rest: index * (dock.base + dock.spacing) + gaps * dock.gapWidth + dock.base / 2
                                readonly property real distance: rest - dock.focusX
                                readonly property real size: dock.base + (dock.peak - dock.base) * dock.magnify * Math.exp(-distance * distance / (2 * dock.sigma * dock.sigma))
                                readonly property var sources: {
                                    const list = [];
                                    for (const name of JSON.parse(icons)) {
                                        if (name.startsWith("/"))
                                            list.push("file://" + encodeURI(name));
                                        else {
                                            const path = Quickshell.iconPath(name, true);
                                            if (path !== "")
                                                list.push(path);
                                        }
                                    }
                                    list.push(root.glyphs[glyph] || root.glyphs.app);
                                    return list;
                                }
                                property int attempt: 0
                                property real lift: 0
                                property real appear: 1
                                property bool waiting: false
                                property int bounces: 0

                                width: (size + (gap ? dock.gapWidth : 0)) * appear
                                height: dock.base
                                opacity: appear

                                Component.onCompleted: {
                                    if (dock.ready) {
                                        appear = 0;
                                        appearAnimation.start();
                                    }
                                }
                                onRunningChanged: if (running > 0) waiting = false
                                onSourcesChanged: attempt = 0

                                function launch(fresh) {
                                    if (key === "builtin:apps" && root.telemetry.tools && root.telemetry.tools.apps) {
                                        root.toggle("launcher");
                                        return;
                                    }
                                    root.send({action: fresh ? "launch" : "activate", key: key});
                                    if (fresh || running === 0) {
                                        waiting = running === 0 && key !== "builtin:apps";
                                        bounces = 1;
                                        bounce.restart();
                                    }
                                }

                                NumberAnimation {
                                    id: appearAnimation
                                    target: tile
                                    property: "appear"
                                    from: 0
                                    to: 1
                                    duration: 280
                                    easing.type: Easing.OutBack
                                }

                                SequentialAnimation {
                                    id: bounce
                                    NumberAnimation { target: tile; property: "lift"; to: dock.bounceHeight; duration: 260; easing.type: Easing.OutQuad }
                                    NumberAnimation { target: tile; property: "lift"; to: 0; duration: 300; easing.type: Easing.OutBounce }
                                    onFinished: {
                                        if (tile.waiting && tile.bounces < 4) {
                                            tile.bounces += 1;
                                            bounce.restart();
                                        }
                                    }
                                }

                                Rectangle {
                                    visible: tile.gap
                                    x: dock.gapWidth / 2 - dock.spacing / 2
                                    y: 4
                                    width: 1
                                    height: dock.base - 8
                                    color: "#40ffffff"
                                }

                                Item {
                                    id: iconBox
                                    anchors.right: parent.right
                                    anchors.bottom: parent.bottom
                                    anchors.bottomMargin: tile.lift
                                    width: tile.size
                                    height: tile.size
                                    transformOrigin: Item.Bottom
                                    scale: tileMouse.pressed ? 0.88 : 1

                                    Behavior on scale {
                                        NumberAnimation { duration: 140; easing.type: Easing.OutCubic }
                                    }

                                    Image {
                                        id: iconImage
                                        anchors.fill: parent
                                        source: tile.sources[Math.min(tile.attempt, tile.sources.length - 1)]
                                        sourceSize.width: 128
                                        sourceSize.height: 128
                                        fillMode: Image.PreserveAspectFit
                                        smooth: true
                                        mipmap: true
                                        onStatusChanged: {
                                            if ((status === Image.Error || (status === Image.Ready && implicitWidth < 2)) && tile.attempt < tile.sources.length - 1)
                                                tile.attempt += 1;
                                        }
                                    }
                                }

                                Row {
                                    anchors.horizontalCenter: iconBox.horizontalCenter
                                    y: parent.height + 5
                                    spacing: 3
                                    Repeater {
                                        model: Math.min(tile.running, 3)
                                        Rectangle {
                                            required property int index
                                            width: tile.focused && index === 0 ? 12 : 5
                                            height: 5
                                            radius: 2.5
                                            color: tile.urgent ? "#ffb4a2" : tile.focused ? "#ffffff" : "#c8f0f2f7"
                                            Behavior on width {
                                                NumberAnimation { duration: 180; easing.type: Easing.OutCubic }
                                            }
                                        }
                                    }
                                }

                                MouseArea {
                                    id: tileMouse
                                    x: tile.gap ? dock.gapWidth : 0
                                    width: tile.size
                                    y: tile.height - tile.size - tile.lift
                                    height: tile.size + tile.lift + 14
                                    hoverEnabled: true
                                    acceptedButtons: Qt.LeftButton | Qt.MiddleButton
                                    cursorShape: Qt.PointingHandCursor
                                    onContainsMouseChanged: {
                                        if (containsMouse)
                                            dock.hovered = tile;
                                        else if (dock.hovered === tile)
                                            dock.hovered = null;
                                    }
                                    onClicked: mouse => {
                                        if (mouse.button === Qt.MiddleButton) {
                                            if (tile.launchable)
                                                tile.launch(true);
                                        } else {
                                            tile.launch(false);
                                        }
                                    }
                                }
                            }
                        }
                    }

                    property bool ready: false
                    Timer {
                        interval: 600
                        running: dock.count > 0 && !dock.ready
                        onTriggered: dock.ready = true
                    }

                    Rectangle {
                        id: bubble
                        readonly property var target: dock.hovered
                        readonly property string shown: root.notice !== "" ? root.notice : dock.bubbleText
                        readonly property bool active: root.notice !== "" || (target !== null && !tileMoving)
                        readonly property bool tileMoving: target !== null && target.lift > 0
                        property real anchorX: target ? row.x + target.x + (target.gap ? dock.gapWidth : 0) + target.size / 2 : dock.width / 2
                        property real anchorY: target ? row.y + row.height - target.size - target.lift : slab.y - (dock.peak - dock.base) * dock.magnify
                        width: bubbleLabel.implicitWidth + 24
                        height: 28
                        radius: 14
                        x: Math.max(4, Math.min(dock.width - width - 4, (root.notice !== "" ? dock.width / 2 : anchorX) - width / 2))
                        y: (root.notice !== "" ? slab.y - (dock.peak - dock.base) * dock.magnify : anchorY) - height - 10
                        opacity: active ? 1 : 0
                        scale: active ? 1 : 0.9
                        visible: opacity > 0.01
                        border.width: 1
                        border.color: "#40ffffff"
                        gradient: Gradient {
                            GradientStop { position: 0; color: "#f03a4254" }
                            GradientStop { position: 1; color: "#f2232937" }
                        }

                        Behavior on opacity {
                            NumberAnimation { duration: 150; easing.type: Easing.OutCubic }
                        }
                        Behavior on scale {
                            NumberAnimation { duration: 150; easing.type: Easing.OutCubic }
                        }
                        Behavior on x {
                            enabled: bubble.opacity > 0.5
                            SpringAnimation { spring: 6; damping: 0.5; epsilon: 0.25 }
                        }

                        Label {
                            id: bubbleLabel
                            anchors.centerIn: parent
                            text: bubble.shown
                            font.pixelSize: 12
                            font.weight: Font.DemiBold
                        }
                    }
                }
            }
        }
    }
}
