#!/usr/bin/env bash
set -euo pipefail
OUTPUT=@OUTPUT@
DEFAULT_MODE=@DEFAULT@
PINS_ROOT=@PINS@
DATA_DIR=@DATA@
FALLBACK_WAYBAR=@FALLBACK@
FONT=@FONT@
FONT_FALLBACK=@FONTB@
DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd -P)"
[[ "${1:---start}" == --start ]] || { echo "Usage: run [--start]" >&2; exit 1; }
[[ -n "${XDG_RUNTIME_DIR:-}" && -d "$XDG_RUNTIME_DIR" && -O "$XDG_RUNTIME_DIR" ]] || {
  echo "cm1406-vitrum-plus: a user XDG_RUNTIME_DIR is required." >&2
  exit 1
}
[[ -n "${NIRI_SOCKET:-}" && -n "${WAYLAND_DISPLAY:-}" ]] || {
  echo "cm1406-vitrum-plus: run inside niri (NIRI_SOCKET and WAYLAND_DISPLAY required)." >&2
  exit 1
}
case "$WAYLAND_DISPLAY" in
  /*) socket=$WAYLAND_DISPLAY ;;
  *) socket=$XDG_RUNTIME_DIR/$WAYLAND_DISPLAY ;;
esac
[[ -S "$socket" ]] || { echo "cm1406-vitrum-plus: Wayland socket unavailable." >&2; exit 1; }
RUNTIME="$XDG_RUNTIME_DIR/cm1406-vitrum-plus"
[[ ! -L "$RUNTIME" ]] || exit 1
umask 077
mkdir -p -- "$RUNTIME"
[[ -O "$RUNTIME" && ! -L "$RUNTIME" ]] || exit 1
exec 9>"$RUNTIME/lock"
flock -n 9 || { echo "cm1406-vitrum-plus: already running."; exit 0; }
runner=$(command -v qs || command -v quickshell || true)
fallback() {
  echo "cm1406-vitrum-plus: $1" >&2
  if [[ "$FALLBACK_WAYBAR" == 1 ]] && command -v waybar >/dev/null 2>&1; then
    config_home=${XDG_CONFIG_HOME:-$HOME/.config}
    if [[ -f "$config_home/fontconfig/conf.d/60-cm1406-open-runde.conf" ]]; then
      style=/etc/xdg/waybar/style.css
      [[ -f "$config_home/waybar/style.css" ]] && style=$config_home/waybar/style.css
      if [[ -f "$style" && "$style" =~ ^[A-Za-z0-9/._-]+$ ]]; then
        printf '@import url("file://%s");\n* { font-family: "Open Runde", sans-serif; }\n' "$style" > "$RUNTIME/waybar-font.css"
        exec waybar -s "$RUNTIME/waybar-font.css" 9>&-
      fi
    fi
    exec waybar 9>&-
  fi
  exit 1
}
[[ -n "$runner" ]] || fallback "Quickshell (qs) is missing; see the installer --rollback."
if command -v fc-list >/dev/null 2>&1 && ! fc-list -q "$FONT" 2>/dev/null; then
  FONT=$FONT_FALLBACK
fi
rm -rf -- "$RUNTIME/live"
mkdir -m 700 -- "$RUNTIME/live" "$RUNTIME/live/runtime" "$RUNTIME/live/cache"
cp -- "$DIR/shell.qml" "$DIR/helper.py" "$RUNTIME/live/"
cp -R -- "$DIR/macshell" "$RUNTIME/live/macshell"
child=""
cleanup() {
  trap - EXIT TERM INT HUP
  if [[ -n "$child" ]]; then
    kill -TERM "$child" 2>/dev/null || true
    wait "$child" 2>/dev/null || true
  fi
  rm -f -- "$RUNTIME/pid"
}
trap cleanup EXIT
trap 'exit 0' TERM INT HUP
started=$SECONDS
env \
  VP_HELPER="$RUNTIME/live/helper.py" \
  VP_OUTPUT="$OUTPUT" \
  VP_TOP=8 VP_BOTTOM=8 VP_RESERVE=1 VP_PREVIEW=0 \
  VP_FONT="$FONT" \
  VP_DEFAULT="$DEFAULT_MODE" VP_DATA="$DATA_DIR" VP_PINS_ROOT="$PINS_ROOT" \
  VP_APP_RUNTIME="$XDG_RUNTIME_DIR" \
  VP_APP_CACHE="${XDG_CACHE_HOME:-$HOME/.cache}" \
  VP_APP_WAYLAND="$WAYLAND_DISPLAY" \
  XDG_RUNTIME_DIR="$RUNTIME/live/runtime" \
  XDG_CACHE_HOME="$RUNTIME/live/cache" \
  WAYLAND_DISPLAY="$socket" \
  "$runner" --path "$RUNTIME/live/shell.qml" > "$RUNTIME/log" 2>&1 9>&- &
child=$!
printf '%s\n' "$child" > "$RUNTIME/pid"
status=0
wait "$child" || status=$?
child=""
rm -f -- "$RUNTIME/pid"
if (( status != 0 && status != 143 && SECONDS - started < 20 )); then
  fallback "Quickshell stopped at startup (status $status); log: $RUNTIME/log"
fi
exit 0
