wait "$child" || status=$?
child=""
rm -f -- "$RUNTIME/pid"
if (( status != 0 && status != 143 && SECONDS - started < 20 )); then
  fallback "Quickshell stopped at startup (status $status); log: $RUNTIME/log"
fi
exit 0
VITRUM_RUNV5_EOF
