class Refusal(Exception):
    pass


def fail(message):
    raise Refusal(message)


def sha(data):
    return hashlib.sha256(data).hexdigest()


def absolute(value, label):
    if not value or not os.path.isabs(value) or ".." in Path(value).parts:
        fail(f"{label} must be an absolute path without '..': {value!r}")
    if any(ord(c) < 32 for c in value):
        fail(f"{label} contains control characters.")
    return Path(os.path.normpath(value))


def no_symlinks(path):
    for part in (*reversed(path.parents), path):
        if part.is_symlink():
            fail(f"Symlinked path refused: {part}")


def owned_file(path):
    no_symlinks(path)
    info = path.lstat()
    if not stat.S_ISREG(info.st_mode) or info.st_uid != os.getuid() or info.st_nlink != 1:
        fail(f"Expected a single-link regular file owned by you: {path}")
    return info


def owned_dir(path):
    no_symlinks(path)
    info = path.lstat()
    if not stat.S_ISDIR(info.st_mode) or info.st_uid != os.getuid():
        fail(f"Expected a directory owned by you: {path}")
    return info


def running_targets():
    found = []
    for entry in Path("/proc").iterdir():
        if not entry.name.isdigit():
            continue
        try:
            if entry.stat().st_uid != os.getuid():
                continue
            args = [os.fsdecode(a) for a in (entry / "cmdline").read_bytes().split(b"\0") if a]
            if not args or Path(args[0]).name not in ("niri", ".niri-wrapped"):
                continue
            if any(a in ("msg", "validate", "completions", "panic", "--help", "--version") for a in args[1:]):
                continue
            environment = {}
            for item in (entry / "environ").read_bytes().split(b"\0"):
                key, sep, value = item.partition(b"=")
                if sep:
                    environment[os.fsdecode(key)] = os.fsdecode(value)
            chosen = None
            for index, arg in enumerate(args[1:], 1):
                if arg in ("-c", "--config"):
                    chosen = args[index + 1]
                    break
                if arg.startswith("--config="):
                    chosen = arg.split("=", 1)[1]
                    break
                if arg.startswith("-c") and len(arg) > 2:
                    chosen = arg[2:]
                    break
            chosen = chosen or environment.get("NIRI_CONFIG")
            if not chosen:
                base = environment.get("XDG_CONFIG_HOME")
                if not base or not os.path.isabs(base):
                    home = environment.get("HOME")
                    if not home:
                        fail(f"Cannot determine the config of niri PID {entry.name}.")
                    base = home + "/.config"
                chosen = base + "/niri/config.kdl"
            if not os.path.isabs(chosen):
                chosen = str((entry / "cwd").resolve() / chosen)
            found.append((entry.name, Path(os.path.normpath(chosen))))
        except (FileNotFoundError, ProcessLookupError):
            continue
        except (PermissionError, IndexError) as exc:
            fail(f"Cannot inspect running niri PID {entry.name}: {exc}")
    return found


def niri_validate(config, data):
    fd, name = tempfile.mkstemp(prefix=".vitrum-plus-validate-", suffix=".kdl", dir=config.parent)
    try:
        with os.fdopen(fd, "wb") as stream:
            stream.write(data)
        result = subprocess.run(["niri", "validate", "-c", name], stdout=subprocess.PIPE,
                                stderr=subprocess.STDOUT, text=True)
    finally:
        os.unlink(name)
    if result.returncode != 0:
        print(result.stdout[-3000:], file=sys.stderr)
        return False
    return True


def fsync_dir(path):
    fd = os.open(path, os.O_RDONLY | os.O_DIRECTORY)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def write_new(directory, name, data, mode):
    fd = os.open(directory / name, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, mode)
    with os.fdopen(fd, "wb") as stream:
        stream.write(data)
        stream.flush()
        os.fsync(stream.fileno())
    os.chmod(directory / name, mode)


def replace_config(config, expected_hash, data):
    current = config.read_bytes()
    if sha(current) != expected_hash:
        fail("The niri config changed during this run; nothing was replaced. Retry.")
    info = owned_file(config)
    fd, temporary = tempfile.mkstemp(prefix=".vitrum-plus-config-", dir=config.parent)
    try:
        with os.fdopen(fd, "wb") as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.chmod(temporary, info.st_mode & 0o777)
        os.replace(temporary, config)
        fsync_dir(config.parent)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)


HELD = []


def unlock(fd):
    if fd != -1:
        HELD.clear()
        os.close(fd)


def lock(base):
    if HELD:
        return -1
    path = base / ".cm1406-vitrum-plus.lock"
    no_symlinks(path)
    fd = os.open(path, os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW, 0o600)
    if os.fstat(fd).st_uid != os.getuid():
        fail(f"Lock file not owned by you: {path}")
    try:
        fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
    except BlockingIOError:
        fail("Another run of this installer is in progress.")
    HELD.append(fd)
    return fd


def runner():
    return shutil.which("qs") or shutil.which("quickshell")


def qml_dirs():
    dirs = []
    for tool in ("qtpaths6", "qtpaths"):
        if shutil.which(tool):
            result = subprocess.run([tool, "--query", "QT_INSTALL_QML"], stdout=subprocess.PIPE,
                                    stderr=subprocess.DEVNULL, text=True)
            if result.returncode == 0 and result.stdout.strip():
                dirs.append(Path(result.stdout.strip()))
    dirs += [Path("/usr/lib/qt6/qml"), Path("/usr/lib64/qt6/qml")]
    dirs += [Path(p) for p in os.environ.get("QML_IMPORT_PATH", "").split(":") if p]
    return list(dict.fromkeys(dirs))


def check_runtime_tools():
    problems = []
    if not runner():
        problems.append("Quickshell (qs) is missing")
    for module in ("QtQuick", "QtQuick/Shapes", "QtQuick/Effects", "QtQuick/Controls", "Qt/labs/folderlistmodel", "Quickshell/Wayland", "Quickshell/Wayland/_BackgroundEffect",
                   "Quickshell/Io"):
        if not any((d / module / "qmldir").is_file() for d in qml_dirs()):
            problems.append(f"QML module {module.replace('/', '.')} not found (qt6-declarative / quickshell)")
    for command in ("python3", "flock"):
        if not shutil.which(command):
            problems.append(f"{command} is missing")
    return problems


def installed_fonts():
    if not shutil.which("fc-list"):
        return set()
    result = subprocess.run(["fc-list", ":", "family"], stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, text=True)
    return {name.strip() for line in result.stdout.splitlines() for name in line.split(",") if name.strip()}


def pick_font(wanted):
    available = installed_fonts()
    found = [f for f in ("Inter",) + FONTS if f in available]
    backup = found[0] if found else "sans-serif"
    if wanted and wanted != BUNDLED:
        if wanted not in available:
            fail(f"Font {wanted!r} is not installed (fc-list). Nothing changed; no fonts are downloaded.")
        print(f"Font chosen: {wanted}  (bundled Open Runde is still installed for --font \"Open Runde\")")
        return wanted, backup
    print("Font chosen: Open Runde (bundled, SIL OFL 1.1, installed for you only)")
    print("Fallback if it cannot load: " + backup + "  (chain Inter > " + " > ".join(FONTS) + ")")
    return BUNDLED, backup


def bundled_fonts():
    files = {}
    for name, digest in FONT_FILES.items():
        data = base64.b64decode((PAYLOAD / "fonts" / (name + ".b64")).read_bytes())
        if sha(data) != digest:
            fail(f"Embedded font file {name} is corrupted; nothing changed.")
        files[name] = data
    return files


def fonts_target():
    return data_base() / "fonts" / "cm1406-vitrum-plus"


def system_conf_path():
    return config_base() / "fontconfig" / "conf.d" / SYSTEM_CONF_NAME


def make_dirs(path):
    missing = []
    probe = path
    while not os.path.lexists(probe):
        missing.append(probe)
        probe = probe.parent
    owned_dir(probe)
    for item in reversed(missing):
        item.mkdir(mode=0o755)
    return [str(p) for p in reversed(missing)]


def remove_created(created):
    for item in reversed(created or []):
        try:
            os.rmdir(item)
        except OSError:
            break


def refresh_fonts(path):
    if shutil.which("fc-cache") and path.is_dir():
        result = subprocess.run(["fc-cache", str(path)], stdout=subprocess.DEVNULL, stderr=subprocess.STDOUT)
        if result.returncode != 0:
            print(f"Warning: fc-cache {path} failed; fonts appear after the next fc-cache or login.")


def check_fonts_target():
    target = fonts_target()
    no_symlinks(target)
    if os.path.lexists(target):
        expected = {n: sha(d) for n, d in bundled_fonts().items()}
        if {k: sha(v) for k, v in tree(target).items()} != expected:
            fail(f"{target} exists with other files; nothing changed.")
    return target


def install_fonts():
    files = bundled_fonts()
    target = check_fonts_target()
    record = {"dir": str(target), "hashes": {n: sha(d) for n, d in files.items()}}
    if os.path.lexists(target):
        record.update(adopted=True, created=[])
        return record
    record["created"] = make_dirs(target.parent)
    stage = Path(tempfile.mkdtemp(prefix=".cm1406-vitrum-plus.fonts-", dir=target.parent))
    try:
        for name, content in files.items():
            write_new(stage, name, content, 0o644)
        os.chmod(stage, 0o755)
        fsync_dir(stage)
        os.rename(stage, target)
        fsync_dir(target.parent)
    except BaseException:
        if stage.exists():
            shutil.rmtree(stage)
        remove_created(record["created"])
        raise
    refresh_fonts(target)
    return record


def remove_fonts(record):
    if not record:
        return
    target = Path(record["dir"])
    if record.get("adopted"):
        print(f"Fonts in {target} were already there before; left in place.")
        return
    if not os.path.lexists(target):
        remove_created(record.get("created"))
        return
    try:
        present = {k: sha(v) for k, v in tree(target).items()}
    except Refusal as exc:
        print(f"Warning: {exc}; {target} left in place.")
        return
    if present != record["hashes"]:
        print(f"Warning: {target} was changed after install; left in place (delete by hand if unwanted).")
        return
    retired = Path(tempfile.mkdtemp(prefix=".cm1406-vitrum-plus.retired-fonts-", dir=target.parent))
    retired.rmdir()
    os.rename(target, retired)
    shutil.rmtree(retired)
    remove_created(record.get("created"))
    refresh_fonts(target.parent)
    print(f"Removed the bundled Open Runde fonts from {target}.")


def check_system_font():
    path = system_conf_path()
    no_symlinks(path)
    if os.path.lexists(path):
        owned_file(path)
        backup = path.with_name(path.name + ".before-cm1406-vitrum-plus")
        if path.read_bytes() != SYSTEM_CONF and os.path.lexists(backup):
            fail(f"{path} exists and {backup} too; move one away first. Nothing changed.")
    return path


def enable_system_font():
    path = check_system_font()
    record = {"path": str(path), "sha": sha(SYSTEM_CONF), "backup": None}
    if os.path.lexists(path) and path.read_bytes() == SYSTEM_CONF:
        record.update(adopted=True, created=[])
        return record
    record["created"] = make_dirs(path.parent)
    try:
        if os.path.lexists(path):
            backup = path.with_name(path.name + ".before-cm1406-vitrum-plus")
            data = path.read_bytes()
            os.rename(path, backup)
            record["backup"] = {"path": str(backup), "sha": sha(data)}
        fd, temporary = tempfile.mkstemp(prefix=".cm1406-vitrum-plus-", dir=path.parent)
        try:
            with os.fdopen(fd, "wb") as stream:
                stream.write(SYSTEM_CONF)
                stream.flush()
                os.fsync(stream.fileno())
            os.chmod(temporary, 0o644)
            os.link(temporary, path)
        finally:
            os.unlink(temporary)
        fsync_dir(path.parent)
    except BaseException:
        disable_system_font(record, quiet=True)
        raise
    print(f"Apps: default sans-serif is now Open Runde ({path}). Monospace (kitty) unchanged.")
    return record


def disable_system_font(record, quiet=False):
    if not record:
        return
    path = Path(record["path"])
    if record.get("adopted"):
        if not quiet:
            print(f"{path} was already there before; left in place.")
        return
    if os.path.lexists(path):
        if path.is_symlink() or not path.is_file() or sha(path.read_bytes()) != record["sha"]:
            print(f"Warning: {path} was edited after install; left in place.")
            return
        path.unlink()
    backup = record.get("backup")
    if backup and os.path.lexists(backup["path"]):
        if sha(Path(backup["path"]).read_bytes()) == backup["sha"]:
            os.rename(backup["path"], path)
        else:
            print(f"Warning: backup {backup['path']} changed; not restored.")
    remove_created(record.get("created"))
    if not quiet:
        print("Apps: default sans-serif font restored.")


APP_FONT_FILES = (
    ("GTK 3", ("gtk-3.0", "settings.ini"), "Settings", "gtk-font-name", "gtk"),
    ("GTK 4", ("gtk-4.0", "settings.ini"), "Settings", "gtk-font-name", "gtk"),
    ("fuzzel", ("fuzzel", "fuzzel.ini"), "main", "font", "fuzzel"),
    ("mako", ("mako", "config"), None, "font", "mako"),
)
BACKUP_SUFFIX = ".before-cm1406-vitrum-plus"


def font_value(style, old):
    old = (old or "").strip()
    if style == "fuzzel":
        size = re.search(r":size=([0-9]+(?:\.[0-9]+)?)", old)
        return BUNDLED + ":size=" + (size.group(1) if size else "12")
    size = re.search(r"\s([0-9]+(?:\.[0-9]+)?)$", old)
    return BUNDLED + " " + (size.group(1) if size else "11")


def set_ini_key(text, section, key, style):
    lines = text.split("\n")
    current = None
    found = []
    header = None
    for index, line in enumerate(lines):
        stripped = line.strip()
        if stripped.startswith("[") and stripped.endswith("]"):
            current = stripped[1:-1].strip()
            if current == section and header is None:
                header = index
            continue
        if current == section and re.match(r"\s*" + re.escape(key) + r"\s*=", line):
            found.append(index)
    if len(found) > 1:
        return None
    if found:
        old = lines[found[0]].split("=", 1)[1]
        lines[found[0]] = key + "=" + font_value(style, old)
        return "\n".join(lines)
    new_line = key + "=" + font_value(style, "")
    if section is None:
        return new_line + "\n" + text if text else new_line + "\n"
    if header is None:
        return text + ("" if text.endswith("\n") or not text else "\n") + ("\n" if text else "") + "[" + section + "]\n" + new_line + "\n"
    lines.insert(header + 1, new_line)
    return "\n".join(lines)


def atomic_put(path, data, mode):
    fd, temporary = tempfile.mkstemp(prefix=".cm1406-vitrum-plus-", dir=path.parent)
    try:
        with os.fdopen(fd, "wb") as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.chmod(temporary, mode)
        os.replace(temporary, path)
        fsync_dir(path.parent)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)


def plan_app_fonts():
    plans = []
    for label, parts, section, key, style in APP_FONT_FILES:
        path = config_base().joinpath(*parts)
        reason = ""
        original = None
        try:
            no_symlinks(path)
            if os.path.lexists(path):
                owned_file(path)
                original = path.read_bytes()
                text = original.decode("utf-8")
                if "\r" in text:
                    raise ValueError("CRLF line endings")
            else:
                text = ""
            if os.path.lexists(path.with_name(path.name + BACKUP_SUFFIX)):
                raise ValueError("an old backup " + path.name + BACKUP_SUFFIX + " is in the way")
            new_text = set_ini_key(text, section, key, style)
            if new_text is None:
                raise ValueError(f"{key}= appears more than once")
        except (Refusal, ValueError, UnicodeDecodeError, OSError) as exc:
            reason = str(exc)
            new_text = None
        plans.append({"label": label, "path": path, "original": original, "new": new_text, "reason": reason})
    return plans


def print_app_fonts(plans):
    for plan in plans:
        if plan["new"] is None:
            print(f"  {plan['label']}: skipped ({plan['reason']}), file left as is: {plan['path']}")
        elif plan["original"] is not None and plan["new"].encode() == plan["original"]:
            print(f"  {plan['label']}: already Open Runde, unchanged: {plan['path']}")
        else:
            print(f"  {plan['label']}: " + ("one line changed (backup kept, undone on rollback)" if plan["original"] is not None
                                             else "new file (removed on rollback)") + f": {plan['path']}")


def apply_app_fonts(plans):
    records = []
    try:
        for plan in plans:
            if plan["new"] is None or (plan["original"] is not None and plan["new"].encode() == plan["original"]):
                continue
            path = plan["path"]
            current = path.read_bytes() if os.path.lexists(path) else None
            if current != plan["original"]:
                print(f"  {plan['label']}: changed during this run, skipped.")
                continue
            record = {"label": plan["label"], "path": str(path), "written": sha(plan["new"].encode()), "backup": None,
                      "created": []}
            if plan["original"] is None:
                record["created"] = make_dirs(path.parent)
                fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o644)
                with os.fdopen(fd, "wb") as stream:
                    stream.write(plan["new"].encode())
                    stream.flush()
                    os.fsync(stream.fileno())
                fsync_dir(path.parent)
            else:
                backup = path.with_name(path.name + BACKUP_SUFFIX)
                write_new(path.parent, backup.name, plan["original"], 0o600)
                record["backup"] = {"path": str(backup), "sha": sha(plan["original"])}
                atomic_put(path, plan["new"].encode(), path.stat().st_mode & 0o777)
            records.append(record)
    except BaseException:
        undo_app_fonts(records, quiet=True)
        raise
    if records and any(r["label"] == "mako" for r in records) and shutil.which("makoctl"):
        subprocess.run(["makoctl", "reload"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    return records


def undo_app_fonts(records, quiet=False):
    reload_mako = False
    for record in reversed(records or []):
        path = Path(record["path"])
        try:
            if not os.path.lexists(path) or path.is_symlink() or sha(path.read_bytes()) != record["written"]:
                print(f"Warning: {path} was edited after install; left as is"
                      + (f" (original kept in {record['backup']['path']})." if record.get("backup") else "."))
                continue
            backup = record.get("backup")
            if backup:
                data = Path(backup["path"]).read_bytes()
                if sha(data) != backup["sha"]:
                    print(f"Warning: backup {backup['path']} changed; {path} left as is.")
                    continue
                atomic_put(path, data, path.stat().st_mode & 0o777)
                os.unlink(backup["path"])
            else:
                path.unlink()
                remove_created(record.get("created"))
            reload_mako = reload_mako or record["label"] == "mako"
            if not quiet:
                print(f"Restored {path}.")
        except OSError as exc:
            print(f"Warning: could not restore {path}: {exc}")
    if reload_mako and shutil.which("makoctl"):
        subprocess.run(["makoctl", "reload"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)


def undo_fonts(state, keep_inherited=False):
    steps = [lambda: undo_app_fonts([r for r in state.get("app_fonts") or [] if not (keep_inherited and r.get("inherited"))])]
    if not (keep_inherited and (state.get("system_font") or {}).get("inherited")):
        steps.append(lambda: disable_system_font(state.get("system_font")))
    if not (keep_inherited and (state.get("fonts") or {}).get("inherited")):
        steps.append(lambda: remove_fonts(state.get("fonts")))
    for step in steps:
        try:
            step()
        except (OSError, Refusal) as exc:
            print(f"Warning: font cleanup incomplete: {exc}")


def mako_path():
    return config_base() / "mako" / "config"


def plan_dnd():
    if not shutil.which("makoctl"):
        return {"skip": "makoctl not found"}
    path = mako_path()
    try:
        no_symlinks(path)
        if os.path.lexists(path):
            owned_file(path)
            current = path.read_bytes().decode("utf-8")
            if "\r" in current:
                raise ValueError("CRLF line endings")
        else:
            current = None
    except (Refusal, ValueError, UnicodeDecodeError, OSError) as exc:
        return {"skip": str(exc), "path": str(path)}
    if current is not None and DND_HEADER in current:
        return {"adopt": True, "path": str(path)}
    if not current:
        new = DND_SECTION
    else:
        new = current + ("" if current.endswith("\n") else "\n") + "\n" + DND_SECTION
    return {"path": str(path), "before": current, "new": new}


def print_dnd(plan):
    if "skip" in plan:
        print(f"  Do not disturb: skipped ({plan['skip']}); the tile stays greyed out.")
    elif plan.get("adopt"):
        print(f"  Do not disturb: already set up in {plan['path']}, unchanged.")
    else:
        print(f"  Do not disturb: 2 lines {'added at the end of' if plan['before'] else 'in a new'} {plan['path']} "
              "(removed on --downgrade or --rollback).")


def reload_mako():
    if shutil.which("makoctl"):
        subprocess.run(["makoctl", "reload"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)


def apply_dnd():
    plan = plan_dnd()
    if "skip" in plan:
        return None
    if plan.get("adopt"):
        return {"adopted": True, "path": plan["path"]}
    path = Path(plan["path"])
    data = plan["new"].encode()
    record = {"path": str(path), "before": plan["before"], "written": sha(data), "created": []}
    if plan["before"] is None:
        record["created"] = make_dirs(path.parent)
        try:
            write_new(path.parent, path.name, data, 0o644)
            fsync_dir(path.parent)
        except BaseException:
            remove_created(record["created"])
            raise
    else:
        atomic_put(path, data, path.stat().st_mode & 0o777)
    reload_mako()
    return record


def undo_dnd(record, quiet=False, keep_inherited=False):
    if not record or record.get("adopted") or (keep_inherited and record.get("inherited")):
        return
    path = Path(record["path"])
    try:
        if not os.path.lexists(path) or path.is_symlink() or sha(path.read_bytes()) != record["written"]:
            print(f"Warning: {path} was edited after install; left as is (delete the {DND_HEADER} section by hand if unwanted).")
            return
        if record["before"] is None:
            path.unlink()
            remove_created(record.get("created"))
        else:
            atomic_put(path, record["before"].encode(), path.stat().st_mode & 0o777)
        reload_mako()
        if not quiet:
            print(f"Restored {path} (do not disturb section removed).")
    except OSError as exc:
        print(f"Warning: could not restore {path}: {exc}")


def set_values(text, pairs):
    lines = text.split("\n") if text else []
    if lines and lines[-1] == "":
        lines.pop()
    for section, key, value in pairs:
        current = None
        found = []
        last = None
        first_header = None
        for index, line in enumerate(lines):
            stripped = line.strip()
            if stripped.startswith("[") and stripped.endswith("]"):
                current = stripped[1:-1].strip()
                if first_header is None:
                    first_header = index
                continue
            if current == section:
                last = index
                if re.match(r"\s*" + re.escape(key) + r"\s*=", line):
                    found.append(index)
        if len(found) > 1:
            return None
        if found:
            lines[found[0]] = key + "=" + value
        elif section is None:
            at = first_header if first_header is not None else len(lines)
            while at > 0 and lines[at - 1].strip() == "":
                at -= 1
            lines.insert(at, key + "=" + value)
        elif last is not None or any(l.strip() == "[" + section + "]" for l in lines):
            header = next(i for i, l in enumerate(lines) if l.strip() == "[" + section + "]")
            at = header + 1
            while at < len(lines) and not (lines[at].strip().startswith("[") and lines[at].strip().endswith("]")):
                at += 1
            while at > header + 1 and lines[at - 1].strip() == "":
                at -= 1
            lines.insert(at, key + "=" + value)
        else:
            if lines:
                lines.append("")
            lines.extend(["[" + section + "]", key + "=" + value])
    return "\n".join(lines) + "\n"


def plan_style():
    plans = []
    for label, parts, program, pairs in STYLE_FILES:
        path = config_base().joinpath(*parts)
        if not shutil.which(program):
            plans.append({"label": label, "path": str(path), "skip": program + " not installed"})
            continue
        try:
            no_symlinks(path)
            if os.path.lexists(path):
                owned_file(path)
                current = path.read_bytes().decode("utf-8")
                if "\r" in current:
                    raise ValueError("CRLF line endings")
            else:
                current = None
            new = set_values(current or "", pairs)
            if new is None:
                raise ValueError("a style key appears more than once")
        except (Refusal, ValueError, UnicodeDecodeError, OSError) as exc:
            plans.append({"label": label, "path": str(path), "skip": str(exc)})
            continue
        plans.append({"label": label, "path": str(path), "before": current, "new": new})
    return plans


def print_style(plans):
    for plan in plans:
        if "skip" in plan:
            print(f"  {plan['label']}: skipped ({plan['skip']}), file left as is.")
        elif plan["before"] == plan["new"]:
            print(f"  {plan['label']}: already in the macOS style, unchanged: {plan['path']}")
        else:
            print(f"  {plan['label']}: macOS colours and rounded corners " + ("in" if plan["before"] is not None else "in a new file")
                  + f" {plan['path']} (undone on --downgrade or --rollback).")


def reload_style(records):
    if any(r["label"] == "mako" for r in records):
        reload_mako()


def apply_style(plans):
    records = []
    try:
        for plan in plans:
            if "skip" in plan or plan["before"] == plan["new"]:
                continue
            path = Path(plan["path"])
            current = path.read_bytes().decode("utf-8") if os.path.lexists(path) else None
            if current != plan["before"]:
                print(f"  {plan['label']}: changed during this run, skipped.")
                continue
            data = plan["new"].encode()
            record = {"label": plan["label"], "path": str(path), "before": plan["before"], "written": sha(data), "created": []}
            if plan["before"] is None:
                record["created"] = make_dirs(path.parent)
                try:
                    write_new(path.parent, path.name, data, 0o644)
                    fsync_dir(path.parent)
                except BaseException:
                    remove_created(record["created"])
                    raise
            else:
                atomic_put(path, data, path.stat().st_mode & 0o777)
            records.append(record)
    except BaseException:
        undo_style(records, quiet=True)
        raise
    reload_style(records)
    return records


def undo_style(records, quiet=False):
    done = []
    for record in reversed(records or []):
        path = Path(record["path"])
        try:
            if not os.path.lexists(path) or path.is_symlink() or sha(path.read_bytes()) != record["written"]:
                print(f"Warning: {path} was edited after install; left as is (its macOS style lines stay).")
                continue
            if record["before"] is None:
                path.unlink()
                remove_created(record.get("created"))
            else:
                atomic_put(path, record["before"].encode(), path.stat().st_mode & 0o777)
            done.append(record)
            if not quiet:
                print(f"Restored {path} (macOS style removed).")
        except OSError as exc:
            print(f"Warning: could not restore {path}: {exc}")
    reload_style(done)


def resolve_config(args):
    if args.config:
        return absolute(args.config, "--config")
    if os.environ.get("NIRI_CONFIG"):
        return absolute(os.environ["NIRI_CONFIG"], "NIRI_CONFIG")
    base = os.environ.get("XDG_CONFIG_HOME") or str(Path.home() / ".config")
    return absolute(base, "XDG_CONFIG_HOME") / "niri" / "config.kdl"


def config_base():
    return absolute(os.environ.get("XDG_CONFIG_HOME") or str(Path.home() / ".config"), "XDG_CONFIG_HOME")


def data_base():
    return absolute(os.environ.get("XDG_DATA_HOME") or str(Path.home() / ".local/share"), "XDG_DATA_HOME")


def kdl_string(value):
    if any(ord(c) < 32 for c in value):
        fail("Control characters in paths are not supported.")
    return json.dumps(value, ensure_ascii=False)


def analyse(text, args, base):
    if "\r" in text:
        fail("CRLF line endings in the niri config: refusing to guess.")
    if "/*" in text:
        fail("Block comments (/* */) in the niri config: refusing to guess which lines are active.")
    lines = text.split("\n")
    if any(re.match(r"\s*include\b", line) for line in lines):
        fail("The niri config uses include: other files could start bars or wallpapers. Refusing to guess.")
    if BEGIN in text or END in text or OFF in text:
        fail("Vitrum Plus markers already exist in the config; use --status or --rollback.")
    startup = [line for line in lines if re.match(r"\s*spawn(-sh)?-at-startup\b", line)]
    for line in startup:
        if re.search(r"\b(qs|quickshell)\b", line):
            fail(f"Another Quickshell autostart exists: {line.strip()}")
    walls = [line for line in startup if "swaybg" in line or "swww" in line or "wpaperd" in line or "hyprpaper" in line]
    if walls == [WALL_EGL] and lines.count(WALL_EGL) == 1:
        default = "fond"
    elif walls == [WALL_SOLID] and lines.count(WALL_SOLID) == 1:
        default = "color"
    else:
        fail("Wallpaper autostart not recognized exactly (expected one swaybg line from install-niri or "
             "install-niri-config-hyprland). Nothing changed.")
    suspend = [walls[0]]
    waybars = [line for line in startup if "waybar" in line]
    if args.keep_waybar:
        fallback = False
    else:
        if waybars != [WAYBAR] or lines.count(WAYBAR) != 1:
            fail("Waybar autostart not recognized exactly (expected one line: spawn-at-startup \"waybar\"). "
                 "Use --keep-waybar to leave Waybar alone.")
        suspend.append(WAYBAR)
        fallback = True
    dock_root = base / "tarkin-niri-dock"
    dock = None
    if os.path.lexists(dock_root) or "// BEGIN TARKIN NIRI DOCK" in text or "// END TARKIN NIRI DOCK" in text:
        owned_dir(dock_root)
        state_file = dock_root / "state.json"
        owned_file(state_file)
        state = json.loads(state_file.read_text())
        if state.get("owner") != DOCK_TOKEN or not isinstance(state.get("block"), str):
            fail(f"Unrecognized dock state in {dock_root}; nothing changed.")
        block = state["block"]
        if text.count(block) != 1 or text.count("// BEGIN TARKIN NIRI DOCK") != 1 or text.count("// END TARKIN NIRI DOCK") != 1:
            fail("Dock KDL block differs from its installer record; nothing changed.")
        spawn = "spawn-at-startup " + json.dumps(str(dock_root / "run"), ensure_ascii=False)
        if block.count("\n" + spawn + "\n") != 1 or lines.count(spawn) != 1:
            fail("Dock autostart line not recognized exactly; nothing changed.")
        if Path(state.get("config", "")) != args.config_path:
            fail(f"The dock was installed for {state.get('config')}, not {args.config_path}.")
        pins = (dock_root / "pins-state.json").exists()
        if not args.replace_dock:
            fail("The Tarkin niri dock is installed" + (" with right-click pins" if pins else "") + ". "
                 "Any KDL change makes its pin menu refuse to run, and keeping both docks duplicates the UI. "
                 "Rerun with --replace-dock: its files and pins stay untouched (dormant) and come back exactly "
                 "on --rollback.")
        suspend.append(spawn)
        dock = {"root": str(dock_root), "pins": pins}
    elif args.replace_dock:
        fail("--replace-dock given but no Tarkin niri dock is installed.")
    return default, suspend, fallback, dock


def core_block(root, version):
    return (BEGIN + "\n" + "spawn-at-startup " + kdl_string(str(root / "run")) + "\n"
            + {1: "", 2: RULE_V2, 3: RULE_V3, 4: RULE_V3, 5: RULE_V3, 6: RULE_V3, 7: RULE_V3, 8: RULE_V8, 9: RULE_V8, 10: RULE_V8}[version] + END + "\n")


def build_candidate(text, suspend, root):
    lines = text.split("\n")
    for line in suspend:
        index = lines.index(line)
        lines[index] = OFF + line
    candidate = "\n".join(lines)
    separator = "" if candidate.endswith("\n") else "\n"
    block = core_block(root, 10)
    return candidate + separator + "\n" + block, separator + "\n" + block


def swap_block(state, version):
    root = Path(state["root"])
    old = core_block(root, VERSIONS[state["owner"]])
    block = state["block"]
    if not block.endswith(old) or block[:-len(old)] not in ("\n", "\n\n"):
        fail("Unrecognized managed block in the install record; nothing changed.")
    return block[:-len(old)] + core_block(root, version)


def tree(path):
    found = {}
    for item in sorted(path.rglob("*")):
        relative = str(item.relative_to(path))
        if item.is_symlink():
            fail(f"Symlink inside the install: {item}")
        if item.is_dir():
            owned_dir(item)
        else:
            owned_file(item)
            found[relative] = item.read_bytes()
    return found


def render_run(settings, name="run.in"):
    template = (PAYLOAD / name).read_text()
    for key, value in settings.items():
        template = template.replace("@" + key + "@", shlex.quote(value))
    if re.search(r"@[A-Z]+@", template):
        fail("Internal template error.")
    return template.encode()


def macshell_files():
    data = base64.b64decode((PAYLOAD / "macshell.tar.b64").read_bytes())
    if sha(data) != MACSHELL_SHA:
        fail("Embedded widget files are corrupted; nothing changed.")
    found = {}
    with tarfile.open(fileobj=io.BytesIO(data), mode="r:gz") as archive:
        for member in archive.getmembers():
            name = member.name
            if member.isdir():
                continue
            if not member.isfile() or name.startswith("/") or ".." in Path(name).parts or not name.startswith("macshell/"):
                fail("Unexpected entry in the embedded widget files.")
            found[name] = archive.extractfile(member).read()
    return found


def write_tree(stage, files):
    for name, content in files.items():
        target = stage / name
        for parent in reversed(target.relative_to(stage).parents):
            if str(parent) != "." and not (stage / parent).exists():
                (stage / parent).mkdir(mode=0o700)
        write_new(target.parent, target.name, content, 0o700 if name == "run" else 0o600)


def payload_files(settings):
    files = {
        "run": render_run(settings),
        "shell.qml": (PAYLOAD / "shell.qml").read_bytes(),
        "helper.py": (PAYLOAD / "helper.py").read_bytes(),
    }
    files.update(macshell_files())
    subprocess.run(["bash", "-n"], input=files["run"], check=True)
    compile(files["helper.py"], "helper.py", "exec")
    return files


def load_install(root):
    owned_dir(root)
    names = {p.name for p in root.iterdir()}
    owned_file(root / "state.json")
    state = json.loads((root / "state.json").read_text())
    if state.get("owner") not in VERSIONS:
        fail(f"Unrelated directory: {root}")
    allowed = set(OWNED) | {"state.json"}
    if state["owner"] == TOKEN_V2 and "v1" in state:
        allowed.add("v1")
    if state["owner"] in (TOKEN_V3, TOKEN_V4, TOKEN_V5, TOKEN_V6, TOKEN_V7, TOKEN_V8, TOKEN_V9, TOKEN) and "previous" in state:
        allowed.add("previous")
    if state["owner"] in (TOKEN_V6, TOKEN_V7, TOKEN_V8, TOKEN_V9, TOKEN):
        allowed.add("macshell")
    if names != allowed:
        fail(f"Unexpected files in {root}; nothing changed.")
    if state["owner"] in (TOKEN_V6, TOKEN_V7, TOKEN_V8, TOKEN_V9, TOKEN):
        found = {"macshell/" + k: sha(v) for k, v in tree(root / "macshell").items()}
        if found != {k: v for k, v in state["hashes"].items() if k.startswith("macshell/")}:
            fail(f"Widget files in {root / 'macshell'} were edited; nothing changed.")
    for name in OWNED:
        owned_file(root / name)
        if sha((root / name).read_bytes()) != state["hashes"][name]:
            fail(f"Owned file was edited: {root / name}; nothing changed.")
    if state["hashes"]["original.kdl"] != state["original_sha"]:
        fail("Invalid install record.")
    if "v1" in allowed:
        saved = root / "v1"
        owned_dir(saved)
        if {p.name for p in saved.iterdir()} != set(V1_FILES):
            fail(f"Unexpected files in {saved}; nothing changed.")
        for name in V1_FILES:
            owned_file(saved / name)
            if sha((saved / name).read_bytes()) != state["v1"]["hashes"][name]:
                fail(f"Saved v1 file was edited: {saved / name}; nothing changed.")
    if "previous" in allowed:
        saved = tree(root / "previous")
        if {k: sha(v) for k, v in saved.items()} != state["previous"]["hashes"]:
            fail(f"Saved previous version in {root / 'previous'} was edited; nothing changed.")
    return state


def runtime_dir():
    value = os.environ.get("XDG_RUNTIME_DIR")
    if not value:
        return None
    path = Path(value) / "cm1406-vitrum-plus"
    return path if path.is_dir() and not path.is_symlink() and path.stat().st_uid == os.getuid() else None


def running_pid():
    path = runtime_dir()
    if path is None or not (path / "pid").is_file():
        return None
    text = (path / "pid").read_text().strip()
    if not re.fullmatch(r"[1-9][0-9]*", text):
        return None
    process = Path("/proc") / text
    try:
        if process.stat().st_uid != os.getuid():
            return None
        args = [os.fsdecode(a) for a in (process / "cmdline").read_bytes().split(b"\0") if a]
    except OSError:
        return None
    if len(args) == 3 and Path(args[0]).name in ("qs", "quickshell") and args[1:] == ["--path", str(path / "live" / "shell.qml")]:
        return int(text)
    return None


def reverse_patch(text, state):
    block = state["block"]
    if text.count(block) != 1:
        fail("The Vitrum Plus block was edited or duplicated; restore it, or edit the config by hand "
             f"from the original copy {state['root']}/original.kdl.")
    text = text.replace(block, "", 1)
    lines = text.split("\n")
    for line in state["suspended"]:
        if lines.count(OFF + line) != 1:
            fail(f"Suspended line was edited: {OFF + line}")
        lines[lines.index(OFF + line)] = line
    return "\n".join(lines)


def do_install(args):
    base = config_base()
    root = base / "cm1406-vitrum-plus"
    config = args.config_path
    if os.path.lexists(root):
        state = load_install(root)
        if state["owner"] == TOKEN and (args.system_font or args.no_system_font):
            do_system_font(args, base, root, state)
        elif state["owner"] != TOKEN:
            print(f"An earlier Vitrum Plus (v{VERSIONS[state['owner']]}) is installed in {root}. Upgrade it with: bash "
                  + shlex.quote(SOURCE) + " --upgrade")
        else:
            print(f"Already installed in {root}. Use --status, --restart or --rollback.")
        return
    owned_dir(base)
    info = owned_file(config)
    owned_dir(config.parent)
    if not os.access(config, os.W_OK) or not os.access(config.parent, os.W_OK):
        fail(f"Config and its directory must be writable: {config}")
    active = running_targets()
    for pid, selected in active:
        if selected != config:
            fail(f"Running niri PID {pid} uses {selected}, not {config}. Rerun with --config {selected}.")
    if os.environ.get("NIRI_SOCKET") and not active:
        fail("NIRI_SOCKET is set but the running niri config could not be verified.")
    if not shutil.which("niri"):
        fail("niri is missing from PATH; KDL validation is required.")
    original = config.read_bytes()
    try:
        text = original.decode("utf-8")
    except UnicodeDecodeError:
        fail("The niri config is not valid UTF-8.")
    default, suspend, fallback, dock = analyse(text, args, base)
    candidate, block = build_candidate(text, suspend, root)
    candidate_bytes = candidate.encode()
    data = data_base() / "cm1406-vitrum-plus"
    font, backup_font = pick_font(args.font)
    settings = {"OUTPUT": args.output, "DEFAULT": default,
                "PINS": dock["root"] if dock and dock["pins"] else "",
                "DATA": str(data), "FALLBACK": "1" if fallback else "0", "FONT": font, "FONTB": backup_font}
    files = payload_files(settings)
    files["original.kdl"] = original
    problems = check_runtime_tools()
    print(f"niri config: {config}")
    print(f"Wallpaper at login: {'~/Pictures/fond.jpg if present, else solid #0b3d91' if default == 'fond' else 'solid #0b3d91'}, or your earlier v1 choice if one is saved.")
    print("Autostart lines suspended (commented, restored on rollback):")
    for line in suspend:
        print("  " + line)
    print("Kept unchanged: tarkin-comfort-start (hypridle/lock), Super+L tarkin-lock, binds, GPU/EGL launcher.")
    if dock:
        print(f"Tarkin dock: dormant, files untouched in {dock['root']}." + (
            " Pinned apps are shown read-only in the Vitrum dock; editing pins needs --rollback." if dock["pins"] else ""))
    if args.keep_waybar:
        print("Waybar: kept. Vitrum bar and dock stack beside it.")
    else:
        print("Waybar: suspended; it restarts automatically if Quickshell fails within 20 s of login.")
    print(f"Private files: {root}  Wallpaper copies: {data}")
    print(f"Bundled fonts: {fonts_target()} (removed on rollback)")
    plans = []
    if args.app_fonts:
        print("Open Runde everywhere (undo only this with --no-system-font --apply; kitty/terminals keep their monospace):")
        print(f"  fontconfig sans-serif: {system_conf_path()}")
        plans = plan_app_fonts()
        print_app_fonts(plans)
        print("  Waybar fallback: Open Runde through a private style that imports yours (your style.css is not edited).")
    else:
        print("--no-system-font: only the Vitrum Plus shell uses Open Runde; app settings are not touched.")
    print("Control Center:")
    print_dnd(plan_dnd())
    style_plans = plan_style() if args.app_style else []
    if args.app_style:
        print("macOS style for notifications and fuzzel (--no-app-style to skip):")
        print_style(style_plans)
    check_fonts_target()
    if args.app_fonts:
        check_system_font()
    if problems:
        fail("Missing requirements: " + "; ".join(problems) + ". Nothing changed; no packages are installed.")
    if not niri_validate(config, original):
        fail("niri rejects the current config; fix it first. Nothing changed.")
    if not niri_validate(config, candidate_bytes):
        fail("niri rejects the modified config; nothing changed.")
    print("niri validate: current and modified configs accepted.")
    if not args.apply:
        print("Dry-run: nothing written. Apply with:")
        print("  bash " + shlex.quote(SOURCE) + " --apply" + (" --replace-dock" if dock else "") +
              (" --keep-waybar" if args.keep_waybar else "") + (" --no-system-font" if not args.app_fonts else "") +
              (" --no-app-style" if not args.app_style else "") +
              (" --font " + shlex.quote(args.font) if args.font else "") +
              (" --config " + shlex.quote(str(config)) if args.config else ""))
        return
    fd = lock(base)
    font_state = {}
    try:
        if os.path.lexists(root):
            fail(f"{root} appeared during this run; nothing changed.")
        try:
            font_state["fonts"] = install_fonts()
            if args.app_fonts:
                font_state["system_font"] = enable_system_font()
                font_state["app_fonts"] = apply_app_fonts(plans)
            font_state["dnd"] = apply_dnd()
            font_state["style"] = apply_style(plan_style() if args.app_style else [])
        except BaseException:
            undo_style(font_state.get("style"), quiet=True)
            undo_dnd(font_state.get("dnd"), quiet=True)
            undo_fonts(font_state)
            raise
        stage = Path(tempfile.mkdtemp(prefix=".cm1406-vitrum-plus.stage-", dir=base))
        try:
            write_tree(stage, files)
            state = {"owner": TOKEN, "config": str(config), "root": str(root),
                     "original_sha": sha(original), "candidate_sha": sha(candidate_bytes),
                     "suspended": suspend, "block": block, "settings": settings,
                     "dock": dock, "hashes": {n: sha(c) for n, c in files.items()},
                     "fonts": font_state["fonts"], "system_font": font_state.get("system_font"),
                     "app_fonts": font_state.get("app_fonts", []), "dnd": font_state.get("dnd"),
                     "style": font_state.get("style", []),
                     "installed": time.strftime("%Y-%m-%dT%H:%M:%S%z")}
            write_new(stage, "state.json", (json.dumps(state, indent=2, ensure_ascii=False) + "\n").encode(), 0o600)
            fsync_dir(stage)
            os.rename(stage, root)
            fsync_dir(base)
        except BaseException:
            if stage.exists():
                shutil.rmtree(stage)
            undo_style(font_state.get("style"), quiet=True)
            undo_dnd(font_state.get("dnd"), quiet=True)
            undo_fonts(font_state)
            raise
        try:
            backup = config.with_name(config.name + ".before-cm1406-vitrum-plus-" + time.strftime("%Y%m%d-%H%M%S"))
            if not os.path.lexists(backup):
                write_new(config.parent, backup.name, original, 0o600)
            replace_config(config, sha(original), candidate_bytes)
        except BaseException:
            shutil.rmtree(root)
            undo_style(font_state.get("style"), quiet=True)
            undo_dnd(font_state.get("dnd"), quiet=True)
            undo_fonts(font_state)
            raise
    finally:
        unlock(fd)
    print("Installed. Nothing was started, stopped or restarted.")
    print("It appears at the next niri login, or now with: bash " + shlex.quote(SOURCE) + " --restart")
    print("Try it now without installing anything: bash " + shlex.quote(SOURCE) + " --preview")
    print("Undo: bash " + shlex.quote(SOURCE) + " --rollback --apply")


def do_system_font(args, base, root, state):
    enable = bool(args.system_font)
    if any(r.get("inherited") for r in state.get("app_fonts") or []) or (state.get("dnd") or {}).get("inherited") \
            or (state.get("system_font") or {}).get("inherited"):
        fail("These font settings belong to the saved previous version (this install was upgraded). "
             "Use --downgrade --apply, change them there, then --upgrade --apply.")
    if enable == bool(state.get("system_font") or state.get("app_fonts")):
        print("Open Runde for apps is already " + ("on." if enable else "off (shell only)."))
        return
    plans = []
    if enable:
        check_system_font()
        print("Would set Open Runde for apps (kitty/terminals keep their monospace):")
        print(f"  fontconfig sans-serif: {system_conf_path()}")
        plans = plan_app_fonts()
        print_app_fonts(plans)
    else:
        print("Would undo the app font changes and restore the backups; the shell keeps Open Runde.")
    if not args.apply:
        print("Dry-run: nothing written. Apply with:")
        print("  bash " + shlex.quote(SOURCE) + (" --system-font" if enable else " --no-system-font") + " --apply")
        return
    fd = lock(base)
    try:
        if json.loads((root / "state.json").read_text()) != state:
            fail("The install changed during this run; nothing changed. Retry.")
        new_state = dict(state)
        undo_style(state.get("style"), quiet=True)
        new_state["style"] = []
        undo_dnd(state.get("dnd"), quiet=True)
        new_state["dnd"] = None
        if enable:
            new_state["system_font"] = enable_system_font()
            try:
                new_state["app_fonts"] = apply_app_fonts(plan_app_fonts())
            except BaseException:
                disable_system_font(new_state["system_font"], quiet=True)
                new_state["dnd"] = apply_dnd()
                if state.get("style"):
                    apply_style(plan_style())
                raise
        else:
            undo_app_fonts(state.get("app_fonts"))
            disable_system_font(state.get("system_font"))
            new_state["system_font"] = None
            new_state["app_fonts"] = []
        new_state["dnd"] = apply_dnd()
        if state.get("style"):
            new_state["style"] = apply_style(plan_style())
        fd2, temporary = tempfile.mkstemp(prefix=".state-", dir=root)
        try:
            with os.fdopen(fd2, "wb") as stream:
                stream.write((json.dumps(new_state, indent=2, ensure_ascii=False) + "\n").encode())
                stream.flush()
                os.fsync(stream.fileno())
            os.replace(temporary, root / "state.json")
            fsync_dir(root)
        finally:
            if os.path.exists(temporary):
                os.unlink(temporary)
    finally:
        unlock(fd)
    print("Done. Apps pick it up when they restart (or at the next login). Vitrum Plus itself is unchanged.")


def do_rollback(args):
    base = config_base()
    root = base / "cm1406-vitrum-plus"
    if not os.path.lexists(root):
        print("Vitrum Plus is not installed; nothing to roll back.")
        return
    state = load_install(root)
    config = Path(state["config"])
    if args.config and args.config_path != config:
        fail(f"Installed for {config}, not {args.config_path}.")
    owned_file(config)
    current = config.read_bytes()
    original = (root / "original.kdl").read_bytes()
    exact = sha(current) == state["candidate_sha"]
    if exact:
        restored = original
        print("Config unchanged since install: the exact original bytes will be restored.")
    else:
        restored = reverse_patch(current.decode("utf-8"), state).encode()
        if sha(restored) == state["original_sha"]:
            print("Config edited only inside the managed lines: exact original restored.")
        else:
            print("Config was edited after install: only the Vitrum Plus changes are undone; your edits are kept.")
            if state.get("dock") and state["dock"].get("pins"):
                print("Warning: the result differs from the pre-install file, so the dock pin menu will refuse "
                      "until the config matches it again (its own safety check).")
    if shutil.which("niri") and not niri_validate(config, restored):
        fail("niri rejects the restored config; nothing changed.")
    if not args.apply:
        print("Dry-run: would restore the autostart lines, remove the managed block and " + str(root) +
              (", the bundled fonts" if state.get("fonts") else "") +
              (", the --system-font setting" if state.get("system_font") else "") +
              (", the do not disturb lines in mako" if (state.get("dnd") or {}).get("written") else "") +
              (", the macOS style of mako/fuzzel" if state.get("style") else "") +
              (", the wpa_supplicant group line (sudo)" if state.get("wifi_access") else "") +
              (", the brightness udev rule (sudo)" if state.get("light_access") else "") + ".")
        print("Apply: bash " + shlex.quote(SOURCE) + " --rollback --apply")
        return
    if state.get("owner") in (TOKEN_V9, TOKEN):
        state = undo_access(state, root, False)
    elif state.get("wifi_access"):
        undo_wifi_access(state["wifi_access"])
        state = dict(state, wifi_access=None)
        save_state(root, state)
    fd = lock(base)
    try:
        replace_config(config, sha(current), restored)
        retired = Path(tempfile.mkdtemp(prefix=".cm1406-vitrum-plus.retired-", dir=base))
        retired.rmdir()
        os.rename(root, retired)
        shutil.rmtree(retired)
        undo_style(state.get("style"))
        undo_dnd(state.get("dnd"))
        undo_fonts(state)
    finally:
        unlock(fd)
    print("Rolled back. Waybar, dock and swaybg autostarts return at the next niri login.")
    print("Wallpaper copies kept in " + state["settings"]["DATA"] + " (delete by hand if unwanted).")
    if running_pid():
        print("Vitrum Plus is still on screen until logout; stop it now with: bash " + shlex.quote(SOURCE) + " --stop")


WPA_DIR = Path("/etc/wpa_supplicant")
WPA_PLAIN = re.compile(r"ctrl_interface=(DIR=)?/run/wpa_supplicant[ \t]*")


def sudo(command, data=None):
    try:
        return subprocess.run(["sudo", "--"] + command, input=data, capture_output=True, timeout=120)
    except (OSError, subprocess.SubprocessError) as exc:
        fail(f"sudo failed: {exc}")


def wifi_access_target():
    found = sorted(WPA_DIR.glob("wpa_supplicant-*.conf"))
    if len(found) != 1:
        fail("Expected exactly one /etc/wpa_supplicant/wpa_supplicant-<interface>.conf (wpa_supplicant@<interface> setup); "
             f"found {len(found)}. Nothing changed.")
    conf = found[0]
    iface = conf.name[len("wpa_supplicant-"):-len(".conf")]
    if not re.fullmatch(r"[A-Za-z0-9_.-]{1,15}", iface):
        fail("Unexpected wpa_supplicant interface name; nothing changed.")
    return conf, iface


def wifi_group():
    import grp
    names = set()
    for gid in os.getgroups():
        try:
            names.add(grp.getgrgid(gid).gr_name)
        except KeyError:
            continue
    for name in ("wheel", "network", "netdev"):
        if name in names:
            return name
    fail("Your user is in none of the groups wheel, network or netdev; nothing changed.")


def restart_wpa(iface):
    unit = f"wpa_supplicant@{iface}.service"
    if subprocess.run(["systemctl", "is-active", "--quiet", unit]).returncode == 0:
        result = sudo(["systemctl", "restart", unit])
        if result.returncode != 0:
            print(f"Warning: could not restart {unit}; reboot to apply.")
        else:
            print(f"Restarted {unit} (Wi-Fi reconnects in a few seconds).")


def plan_wifi_access():
    conf, iface = wifi_access_target()
    group = wifi_group()
    backup = conf.with_name(conf.name + BACKUP_SUFFIX)
    read = sudo(["cat", str(conf)])
    if read.returncode != 0:
        fail(f"Could not read {conf} with sudo; nothing changed.")
    before = read.stdout
    try:
        text = before.decode("utf-8")
    except UnicodeDecodeError:
        fail(f"{conf} is not UTF-8; nothing changed.")
    lines = text.split("\n")
    hits = [i for i, line in enumerate(lines) if line.strip().startswith("ctrl_interface=")]
    if len(hits) != 1:
        fail(f"{conf} must have exactly one ctrl_interface= line; nothing changed.")
    if not WPA_PLAIN.fullmatch(lines[hits[0]].strip()):
        fail(f"{conf} already has a custom ctrl_interface ({lines[hits[0]].strip()}); left as is.")
    lines[hits[0]] = f"ctrl_interface=DIR=/run/wpa_supplicant GROUP={group}"
    return {"conf": conf, "iface": iface, "backup": backup, "before": before, "new": "\n".join(lines).encode(), "group": group}


def apply_wifi_access(plan):
    if sudo(["test", "-e", str(plan["backup"])]).returncode == 0:
        fail(f"An old backup {plan['backup']} is in the way; nothing changed.")
    if sudo(["cp", "-p", "--", str(plan["conf"]), str(plan["backup"])]).returncode != 0:
        fail("Could not save the backup; nothing changed.")
    result = sudo(["tee", "--", str(plan["conf"])], plan["new"])
    check = sudo(["cat", str(plan["conf"])])
    if result.returncode != 0 or check.stdout != plan["new"]:
        sudo(["cp", "-p", "--", str(plan["backup"]), str(plan["conf"])])
        sudo(["rm", "-f", "--", str(plan["backup"])])
        fail("Could not write the wpa_supplicant config; restored.")
    restart_wpa(plan["iface"])
    return {"conf": str(plan["conf"]), "iface": plan["iface"], "backup": str(plan["backup"]), "group": plan["group"],
            "before": sha(plan["before"]), "written": sha(plan["new"])}


def undo_wifi_access(record, strict=True):
    if not record:
        return True
    conf, backup = record["conf"], record["backup"]
    current = sudo(["cat", conf])
    saved = sudo(["cat", backup])
    if current.returncode != 0 or saved.returncode != 0:
        if strict:
            fail(f"Could not read {conf} or its backup with sudo; nothing changed.")
        return False
    if sha(current.stdout) != record["written"] or sha(saved.stdout) != record["before"]:
        print(f"Warning: {conf} or its backup changed since --wifi-access (tarkin-wifi rewrites it); left as is, "
              f"backup kept in {backup}.")
        return True
    if sudo(["cp", "-p", "--", backup, conf]).returncode != 0 or sudo(["rm", "-f", "--", backup]).returncode != 0:
        if strict:
            fail(f"Could not restore {conf}; nothing else changed.")
        return False
    print(f"Restored {conf} (Wi-Fi control from the shell removed).")
    restart_wpa(record["iface"])
    return True


def save_state(root, state):
    fd2, temporary = tempfile.mkstemp(prefix=".state-", dir=root)
    try:
        with os.fdopen(fd2, "wb") as stream:
            stream.write((json.dumps(state, indent=2, ensure_ascii=False) + "\n").encode())
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, root / "state.json")
        fsync_dir(root)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)


SYS_CLASS = Path(os.environ.get("VP_TEST_SYS_CLASS") or "/sys/class")
UDEV_DIR = Path(os.environ.get("VP_TEST_UDEV_DIR") or "/etc/udev/rules.d")
UDEV_NAME = "90-cm1406-vitrum-light.rules"
LIGHT_GROUP = "video"


def user_groups():
    import grp
    names = set()
    for gid in os.getgroups():
        try:
            names.add(grp.getgrgid(gid).gr_name)
        except KeyError:
            continue
    return names


def light_devices():
    found = []
    for kind, pattern in (("leds", "*kbd_backlight*"), ("backlight", "*")):
        try:
            entries = sorted((SYS_CLASS / kind).glob(pattern))
        except OSError:
            entries = []
        for device in entries:
            target = device / "brightness"
            if target.is_file() and (device / "max_brightness").is_file():
                found.append((kind, target))
    return found


def light_rule(kinds):
    lines = []
    for kind in ("leds", "backlight"):
        if kind in kinds:
            match = 'SUBSYSTEM=="leds", KERNEL=="*kbd_backlight*"' if kind == "leds" else 'SUBSYSTEM=="backlight"'
            lines.append(f'ACTION=="add", {match}, RUN+="/usr/bin/chgrp {LIGHT_GROUP} /sys%p/brightness", '
                         f'RUN+="/usr/bin/chmod g+w /sys%p/brightness"')
    return ("\n".join(lines) + "\n").encode()


def plan_light():
    devices = light_devices()
    if not devices:
        return {"skip": "no keyboard or screen backlight found"}
    locked = [(kind, path) for kind, path in devices if not os.access(path, os.W_OK)]
    if not locked:
        return {"skip": "keyboard and screen brightness are already writable by you", "done": True}
    if LIGHT_GROUP not in user_groups():
        return {"skip": f"your user is not in the {LIGHT_GROUP} group"}
    rule = UDEV_DIR / UDEV_NAME
    if sudo(["test", "-e", str(rule)]).returncode == 0:
        return {"skip": f"{rule} already exists (not ours); left as is"}
    return {"rule": rule, "data": light_rule({kind for kind, _ in locked}), "devices": locked}


def describe_light(plan):
    if "skip" in plan:
        print("  Brightness (keyboard, screen): skipped, " + plan["skip"] + ".")
        return
    print(f"  Brightness: new udev rule {plan['rule']} (root only, needs sudo):")
    for line in plan["data"].decode().splitlines():
        print("    " + line)
    print(f"  Now: group {LIGHT_GROUP} + write for the group on " + ", ".join(str(p) for _, p in plan["devices"]) + ".")
    print("  The keyboard and screen sliders then write the brightness file directly (no logind needed).")


def stat_of(path):
    info = os.stat(path)
    return {"gid": info.st_gid, "mode": stat.S_IMODE(info.st_mode)}


def apply_light(plan):
    import grp
    group_id = grp.getgrnam(LIGHT_GROUP).gr_gid
    rule = str(plan["rule"])
    record = {"rule": rule, "written": sha(plan["data"]), "group": LIGHT_GROUP, "devices": []}
    try:
        if sudo(["test", "-e", rule]).returncode == 0:
            fail(f"{rule} appeared during this run; nothing changed.")
        result = sudo(["tee", "--", rule], plan["data"])
        check = sudo(["cat", rule])
        if result.returncode != 0 or check.stdout != plan["data"]:
            sudo(["rm", "-f", "--", rule])
            fail(f"Could not write {rule}; nothing changed.")
        sudo(["chmod", "644", "--", rule])
        record["rule_written"] = True
        for _, path in plan["devices"]:
            before = stat_of(path)
            entry = dict(before, path=str(path))
            if sudo(["chgrp", LIGHT_GROUP, "--", str(path)]).returncode != 0 or \
                    sudo(["chmod", "g+w", "--", str(path)]).returncode != 0:
                sudo(["chgrp", str(before["gid"]), "--", str(path)])
                sudo(["chmod", format(before["mode"], "o"), "--", str(path)])
                fail(f"Could not open {path} to the {LIGHT_GROUP} group; undone.")
            after = stat_of(path)
            entry.update(set_gid=after["gid"], set_mode=after["mode"])
            record["devices"].append(entry)
            if after["gid"] != group_id:
                fail(f"{path} did not take the {LIGHT_GROUP} group; undone.")
    except BaseException:
        undo_light(record, strict=False, quiet=True)
        raise
    reload_udev()
    print(f"Wrote {rule}; brightness files now writable by the {LIGHT_GROUP} group.")
    return record


def reload_udev():
    if not os.environ.get("VP_TEST_UDEV_DIR") and shutil.which("udevadm") and os.path.exists("/run/udev/control"):
        sudo(["udevadm", "control", "--reload"])


def undo_light(record, strict=True, quiet=False):
    if not record:
        return True
    clean = True
    for entry in reversed(record.get("devices") or []):
        path = entry["path"]
        try:
            now = stat_of(path)
        except OSError:
            continue
        if now != {"gid": entry["set_gid"], "mode": entry["set_mode"]}:
            if not quiet:
                print(f"Note: {path} changed since --system-access; left as is (back to normal at the next boot).")
            continue
        if sudo(["chgrp", str(entry["gid"]), "--", path]).returncode != 0 or \
                sudo(["chmod", format(entry["mode"], "o"), "--", path]).returncode != 0:
            clean = False
    rule = record.get("rule")
    if rule and record.get("rule_written", True):
        current = sudo(["cat", rule])
        if current.returncode == 0:
            if sha(current.stdout) != record["written"]:
                print(f"Warning: {rule} was edited after --system-access; left as is.")
            elif sudo(["rm", "-f", "--", rule]).returncode != 0:
                clean = False
            elif not quiet:
                print(f"Removed {rule} (brightness files back to root only).")
    if not clean and strict:
        fail("Could not fully undo the brightness access; run the same command again.")
    reload_udev()
    return clean


def plan_wifi_soft(state):
    if state.get("wifi_access"):
        return {"skip": "already on" + (" (set up by an older version)" if state["wifi_access"].get("inherited") else ""), "done": True}
    try:
        conf, iface = wifi_access_target()
        group = wifi_group()
    except Refusal as exc:
        return {"skip": str(exc).replace(" Nothing changed.", "").replace("; nothing changed.", "")}
    return {"conf": conf, "iface": iface, "group": group}


def describe_wifi(plan):
    if "skip" in plan:
        print("  Wi-Fi (wpa_supplicant): skipped, " + plan["skip"] + ".")
        return
    conf, iface, group = plan["conf"], plan["iface"], plan["group"]
    print(f"  Wi-Fi: one line in {conf} (root only, needs sudo):")
    print("    ctrl_interface=/run/wpa_supplicant  ->  "
          f"ctrl_interface=DIR=/run/wpa_supplicant GROUP={group}")
    print(f"    Backup: {conf}{BACKUP_SUFFIX} (root only). Then wpa_supplicant@{iface} restarts (Wi-Fi drops for a few seconds).")
    print("    The Control Center can then list, join and forget networks with wpa_cli, as members of " + group + ".")


def do_system_access(args, enable):
    base = config_base()
    root = base / "cm1406-vitrum-plus"
    if not os.path.lexists(root):
        fail("Vitrum Plus v10 is not installed.")
    state = load_install(root)
    if state["owner"] != TOKEN:
        fail("Upgrade to v10 first (--upgrade --apply).")
    flag = "--wifi-access" if args.wifi_access or args.no_wifi_access else "--system-access"
    if enable:
        light = ({"skip": "already on" + (" (set up by v9)" if state["light_access"].get("inherited") else ""), "done": True}
                 if state.get("light_access") else plan_light())
        wifi = plan_wifi_soft(state)
        todo = [p for p in (light, wifi) if "skip" not in p]
        if not todo:
            if light.get("done") and wifi.get("done"):
                print("Wi-Fi control from the shell is already on; brightness access: " + light["skip"] + ".")
                return
            describe_light(light)
            describe_wifi(wifi)
            if wifi.get("done") or light.get("done"):
                print("Nothing more to do: the rest is already on.")
                return
            fail("Nothing to set up (see above); nothing changed.")
        print("System access for the Control Center (sudo asked once per step):")
        describe_light(light)
        describe_wifi(wifi)
        print("Undo: --no-system-access --apply, --downgrade --apply or --rollback --apply.")
    else:
        own_wifi = state.get("wifi_access") and not state["wifi_access"].get("inherited")
        own_light = state.get("light_access") and not state["light_access"].get("inherited")
        if state.get("light_access") and not own_light or state.get("wifi_access") and not own_wifi:
            print("Some access was set up by an older version (kept on upgrade): undo it with --rollback --apply, or "
                  "--downgrade --apply then that version's script with --no-system-access --apply "
                  "(--no-wifi-access for v8).")
        if not own_light and not own_wifi:
            print("System access set up by v10: none, nothing to undo.")
            return
        if own_light:
            print(f"Would remove {state['light_access']['rule']} and give the brightness files back to their owner (sudo).")
        if own_wifi:
            print(f"Would restore {state['wifi_access']['conf']} from its backup (sudo) and restart wpa_supplicant.")
    if not args.apply:
        print("Dry-run: nothing written. Apply with:")
        print("  bash " + shlex.quote(SOURCE) + (" " if enable else " --no-") + flag[2:] + " --apply")
        return
    fd = lock(base)
    try:
        if json.loads((root / "state.json").read_text()) != state:
            fail("The install changed during this run; nothing changed. Retry.")
        new_state = dict(state)
        if enable:
            problems = []
            if "skip" not in light:
                new_state["light_access"] = apply_light(light)
                save_state(root, new_state)
            if "skip" not in wifi:
                try:
                    new_state["wifi_access"] = apply_wifi_access(plan_wifi_access())
                    save_state(root, new_state)
                except Refusal as exc:
                    if "skip" in light:
                        raise
                    problems.append("Wi-Fi: " + str(exc))
            for problem in problems:
                print("Skipped " + problem)
        else:
            if own_light:
                undo_light(state["light_access"])
                new_state["light_access"] = None
                save_state(root, new_state)
            if own_wifi:
                undo_wifi_access(state["wifi_access"])
                new_state["wifi_access"] = None
        save_state(root, new_state)
    finally:
        unlock(fd)
    print("Done." + (" Brightness sliders work at once; nothing to restart." if enable and "skip" not in light else ""))


def undo_access(state, root, keep_inherited):
    changed = False
    if state.get("light_access") and not (keep_inherited and state["light_access"].get("inherited")):
        undo_light(state["light_access"])
        state = dict(state, light_access=None)
        changed = True
    if state.get("wifi_access") and not (keep_inherited and state["wifi_access"].get("inherited")):
        undo_wifi_access(state["wifi_access"])
        state = dict(state, wifi_access=None)
        changed = True
    if changed:
        save_state(root, state)
    return state


def do_diagnose(args):
    root = config_base() / "cm1406-vitrum-plus"
    print("Vitrum Plus diagnose (send this text as is).")
    if os.path.lexists(root):
        state = load_install(root)
        print(f"Installed: v{VERSIONS[state['owner']]} in {root}.")
        print("Brightness access: " + ("on, " + state["light_access"]["rule"] if state.get("light_access") else "off"))
        print("Wi-Fi control: " + ("on, " + state["wifi_access"]["conf"] if state.get("wifi_access") else "off"))
    else:
        print("Not installed.")
    pid = running_pid()
    print(f"Running: PID {pid}." if pid else "Not running in this session.")
    for kind, path in light_devices():
        try:
            info = os.stat(path)
            import grp
            group = grp.getgrgid(info.st_gid).gr_name
        except (OSError, KeyError):
            group = "?"
        print(f"{kind}: {path} group {group} mode {format(stat.S_IMODE(os.stat(path).st_mode), 'o') if path.exists() else '?'} "
              + ("writable" if os.access(path, os.W_OK) else "not writable by you"))
    print("Session: XDG_SESSION_ID=" + (os.environ.get("XDG_SESSION_ID") or "(empty)") + ", groups: " + " ".join(sorted(user_groups())))
    runtime = runtime_dir()
    log_file = runtime / "helper.log" if runtime is not None else None
    if log_file is None or not log_file.is_file():
        print("No helper log yet (" + (str(log_file) if log_file else "XDG_RUNTIME_DIR/cm1406-vitrum-plus/helper.log") + ").")
        return
    lines = log_file.read_text(errors="replace").splitlines()
    print(f"Last {min(args.lines, len(lines))} lines of {log_file}:")
    for line in lines[-args.lines:]:
        print("  " + line)


def do_status(args):
    root = config_base() / "cm1406-vitrum-plus"
    if not os.path.lexists(root):
        print("Not installed.")
    else:
        state = load_install(root)
        config = Path(state["config"])
        current = sha(config.read_bytes()) if config.is_file() else ""
        version = {1: "v1 (first dock)", 2: "v2 (liquid glass dock)", 3: "v3 (bar and panels)",
                   4: "v4 (desktop widgets)", 5: "v5 (Open Runde font)", 6: "v6 (MacShell widgets)",
                   7: "v7 (macOS-style interface)", 8: "v8 (macOS Liquid Glass, lighter)",
                   9: "v9 (working controls, self-healing helper)",
                   10: "v10 (same look, far fewer wakeups, faster start)"}[VERSIONS[state["owner"]]]
        print(f"Installed {version} in {root} for {config}.")
        if state["owner"] == TOKEN:
            print("Saved previous version for --downgrade: " + (
                "v" + str(VERSIONS[state["previous"]["owner"]]) + "." if "previous" in state else "no (installed directly as v10)."))
            print("Font: " + state["settings"].get("FONT", "") + (" (bundled in " + state["fonts"]["dir"] + ")" if state.get("fonts") else ""))
            print("--system-font: " + ("on (" + state["system_font"]["path"] + ")" if state.get("system_font") else "off"))
            dnd = state.get("dnd") or {}
            print("Do not disturb (mako): " + (("kept from the previous version in " if dnd.get("inherited") else "set up in ") + dnd["path"] if dnd.get("written") else
                                               "already set up before Vitrum" if dnd.get("adopted") else "not set up (tile greyed out)"))
            print("macOS style: " + (", ".join(r["label"] for r in state.get("style") or []) or "not applied")
                  + (" (kept from the previous version)" if any(r.get("inherited") for r in state.get("style") or []) else ""))
            print("Wi-Fi control (wpa_supplicant group): " + ("on, " + state["wifi_access"]["conf"] if state.get("wifi_access") else "off")
                  + (" (set up by an older version)" if (state.get("wifi_access") or {}).get("inherited") else ""))
            print("Brightness access (udev rule): " + ("on, " + state["light_access"]["rule"] if state.get("light_access") else "off")
                  + (" (set up by v9)" if (state.get("light_access") or {}).get("inherited") else ""))
        print("Config: " + ("unchanged since install (exact rollback)." if current == state["candidate_sha"]
                            else "edited since install (rollback keeps your edits)."))
    pid = running_pid()
    print(f"Running: PID {pid}." if pid else "Not running in this session.")


def do_stop(args):
    pid = running_pid()
    if not pid:
        print("No verified Vitrum Plus instance is running; nothing signalled.")
        return
    os.kill(pid, signal.SIGTERM)
    print(f"Stopped Vitrum Plus (PID {pid}). Other bars and windows were not touched.")


def check_target(config):
    owned_file(config)
    owned_dir(config.parent)
    if not os.access(config, os.W_OK) or not os.access(config.parent, os.W_OK):
        fail(f"Config and its directory must be writable: {config}")
    active = running_targets()
    for pid, selected in active:
        if selected != config:
            fail(f"Running niri PID {pid} uses {selected}, not {config}.")
    if os.environ.get("NIRI_SOCKET") and not active:
        fail("NIRI_SOCKET is set but the running niri config could not be verified.")
    if not shutil.which("niri"):
        fail("niri is missing from PATH; KDL validation is required.")


def switch_install(base, root, files, saved, config, current, new_text):
    fd = lock(base)
    try:
        stage = Path(tempfile.mkdtemp(prefix=".cm1406-vitrum-plus.stage-", dir=base))
        retired = None
        try:
            write_tree(stage, files)
            for folder, content_map in (saved or {}).items():
                for relative, content in content_map.items():
                    target = stage / folder / relative
                    for parent in reversed(target.relative_to(stage).parents):
                        if str(parent) != "." and not (stage / parent).exists():
                            (stage / parent).mkdir(mode=0o700)
                    write_new(target.parent, target.name, content,
                              0o700 if target.name == "run" else 0o600)
                    fsync_dir(target.parent)
            fsync_dir(stage)
            if sha(config.read_bytes()) != sha(current):
                fail("The niri config changed during this run; nothing was replaced. Retry.")
            retired = Path(tempfile.mkdtemp(prefix=".cm1406-vitrum-plus.retired-", dir=base))
            retired.rmdir()
            os.rename(root, retired)
            try:
                os.rename(stage, root)
                fsync_dir(base)
                replace_config(config, sha(current), new_text.encode())
            except BaseException:
                if root.exists() and not stage.exists():
                    os.rename(root, stage)
                os.rename(retired, root)
                fsync_dir(base)
                retired = None
                raise
        finally:
            if stage.exists():
                shutil.rmtree(stage)
        if retired is not None:
            shutil.rmtree(retired)
    finally:
        unlock(fd)


def do_upgrade(args):
    base = config_base()
    root = base / "cm1406-vitrum-plus"
    if not os.path.lexists(root):
        fail("Vitrum Plus is not installed; for a fresh install use --apply.")
    state = load_install(root)
    if state["owner"] == TOKEN:
        print("Already Vitrum Plus v10. Restart it with --restart if needed."
              + ("" if state.get("system_font") else " App-wide font: --system-font --apply."))
        return
    version = VERSIONS[state["owner"]]
    shell = (root / "shell.qml").read_bytes()
    helper = (root / "helper.py").read_bytes()
    known = {1: (V1_SHELL, V1_HELPER, "run-v1.in"), 2: (V2_SHELL, V2_HELPER, "run-v2.in"),
             3: (V3_SHELL, V3_HELPER, "run-v3.in"), 4: (V4_SHELL, V4_HELPER, "run-v4.in"),
             5: (V5_SHELL, V5_HELPER, "run-v5.in"), 6: (V6_SHELL, V6_HELPER, "run.in"),
             7: (V7_SHELL, V7_HELPER, "run.in"), 8: (V8_SHELL, V8_HELPER, "run.in"),
             9: (V9_SHELL, V9_HELPER, "run.in")}[version]
    if sha(shell) != known[0] or sha(helper) != known[1]:
        fail(f"Installed shell.qml/helper.py are not the known v{version} files; nothing changed.")
    if (root / "run").read_bytes() != render_run(state["settings"], known[2]):
        fail(f"Installed run script differs from the v{version} template; nothing changed.")
    previous = {k: v for k, v in tree(root).items() if k != "original.kdl"}
    config = Path(state["config"])
    if args.config and args.config_path != config:
        fail(f"Installed for {config}, not {args.config_path}.")
    check_target(config)
    current = config.read_bytes()
    text = current.decode("utf-8")
    if text.count(state["block"]) != 1:
        fail("The Vitrum Plus block in the niri config was edited or duplicated; nothing changed.")
    for line in state["suspended"]:
        if text.split("\n").count(OFF + line) != 1:
            fail(f"Suspended line was edited: {OFF + line}")
    block = swap_block(state, 10)
    new_text = text.replace(state["block"], block, 1)
    font, backup_font = pick_font(args.font)
    settings = dict(state["settings"], FONT=font, FONTB=backup_font)
    files = payload_files(settings)
    files["original.kdl"] = (root / "original.kdl").read_bytes()
    problems = check_runtime_tools()
    exact = sha(current) == state["candidate_sha"]
    new_state = {k: v for k, v in state.items()
                 if k not in ("owner", "block", "candidate_sha", "hashes", "v1", "previous", "upgraded", "settings",
                              "fonts", "system_font", "app_fonts", "dnd", "style", "wifi_access", "light_access")}
    new_state.update({"owner": TOKEN, "block": block, "settings": settings,
                      "candidate_sha": sha(new_text.encode()) if exact else "edited-before-upgrade",
                      "hashes": {n: sha(c) for n, c in files.items()},
                      "previous": {"owner": state["owner"], "hashes": {k: sha(v) for k, v in previous.items()},
                                   "block": state["block"]},
                      "upgraded": time.strftime("%Y-%m-%dT%H:%M:%S%z")})
    if state.get("wifi_access"):
        new_state["wifi_access"] = dict(state["wifi_access"], inherited=True)
    if state.get("light_access"):
        new_state["light_access"] = dict(state["light_access"], inherited=True)
    print(f"Upgrade v{version} -> v10 in {root} for {config}.")
    print(f"v{version} files verified (known hashes). They are kept in {root / 'previous'} for --downgrade.")
    print("niri config: " + ("unchanged (same rules as v8)." if version in (8, 9) else
                             "only the managed block changes (dock and panels keep xray false, the bar uses the cheaper "
                             "wallpaper blur, fuzzel gets niri blur)."))
    inherit_fonts = bool(state.get("fonts"))
    inherit_system = bool(state.get("system_font"))
    inherit_apps = bool(state.get("app_fonts"))
    print(f"Bundled fonts: {fonts_target()}" + (f" (already installed by v{version}, kept)" if inherit_fonts else " (removed on --downgrade or --rollback)"))
    plans = []
    if inherit_apps:
        print(f"Open Runde for apps: already set by v{version}, kept as is.")
    elif args.app_fonts:
        print("Open Runde everywhere (undo only this with --no-system-font --apply; kitty/terminals keep their monospace):")
        print(f"  fontconfig sans-serif: {system_conf_path()}" + (f" (already set by v{version})" if inherit_system else ""))
        plans = plan_app_fonts()
        print_app_fonts(plans)
        print("  Waybar fallback: Open Runde through a private style that imports yours (your style.css is not edited).")
    inherit_dnd = version in (7, 8, 9)
    inherit_style = version in (8, 9)
    print("Control Center:")
    if inherit_dnd:
        print(f"  Do not disturb: as set by v{version}, kept.")
    else:
        print_dnd(plan_dnd())
    if state.get("wifi_access"):
        print(f"  Wi-Fi control (wpa_supplicant): as set by v{version if version == 8 else '8 or 9'}, kept.")
    if state.get("light_access"):
        print("  Brightness access (udev rule): as set by v9, kept.")
    print("  Brightness sliders: write the brightness file when allowed; if not, run --system-access --apply after the upgrade.")
    style_plans = plan_style() if args.app_style and not inherit_style else []
    if inherit_style:
        print(f"macOS style for notifications and fuzzel: as set by v{version}, kept.")
    elif args.app_style:
        print("macOS style for notifications and fuzzel (--no-app-style to skip):")
        print_style(style_plans)
    if not inherit_fonts:
        check_fonts_target()
    if args.app_fonts and not inherit_system:
        check_system_font()
    print("Kept: wallpaper copies and choice in " + state["settings"]["DATA"] + ", suspended lines, original copy, "
          "Tarkin dock files and pins, lock and idle helpers.")
    if problems:
        fail("Missing requirements: " + "; ".join(problems) + ". Nothing changed; no packages are installed.")
    if not niri_validate(config, current):
        fail("niri rejects the current config; fix it first. Nothing changed.")
    if not niri_validate(config, new_text.encode()):
        fail("niri rejects the upgraded config; nothing changed.")
    print("niri validate: current and upgraded configs accepted.")
    if not args.apply:
        print("Dry-run: nothing written. Apply with:")
        print("  bash " + shlex.quote(SOURCE) + " --upgrade --apply" + (" --no-system-font" if not args.app_fonts else "")
              + (" --no-app-style" if not args.app_style else "")
              + (" --font " + shlex.quote(args.font) if args.font else ""))
        return
    font_state = {}
    fd = lock(base)
    try:
        if json.loads((root / "state.json").read_text()) != state:
            fail("The install changed during this run; nothing changed. Retry.")
        if inherit_fonts:
            check_fonts_target()
            font_state["fonts"] = dict(state["fonts"], inherited=True)
        else:
            font_state["fonts"] = install_fonts()
        if inherit_system:
            font_state["system_font"] = dict(state["system_font"], inherited=True)
        elif args.app_fonts:
            font_state["system_font"] = enable_system_font()
        if inherit_apps:
            font_state["app_fonts"] = [dict(r, inherited=True) for r in state["app_fonts"]]
        elif args.app_fonts:
            font_state["app_fonts"] = apply_app_fonts(plans)
        if inherit_dnd:
            font_state["dnd"] = dict(state["dnd"], inherited=True) if state.get("dnd") else None
        else:
            font_state["dnd"] = apply_dnd()
        if inherit_style:
            font_state["style"] = [dict(r, inherited=True) for r in state.get("style") or []]
        else:
            font_state["style"] = apply_style(plan_style() if args.app_style else [])
        new_state.update(fonts=font_state["fonts"], system_font=font_state.get("system_font"),
                         app_fonts=font_state.get("app_fonts", []), dnd=font_state.get("dnd"),
                         style=font_state.get("style", []))
        files["state.json"] = (json.dumps(new_state, indent=2, ensure_ascii=False) + "\n").encode()
        switch_install(base, root, files, {"previous": previous}, config, current, new_text)
    except BaseException:
        undo_style([r for r in font_state.get("style") or [] if not r.get("inherited")], quiet=True)
        undo_dnd(font_state.get("dnd"), quiet=True, keep_inherited=True)
        undo_fonts(font_state, keep_inherited=True)
        raise
    finally:
        unlock(fd)
    print("Upgraded. Nothing was stopped or started.")
    if not state.get("wifi_access") and not state.get("light_access"):
        print("Keyboard and screen brightness, Wi-Fi with wpa_supplicant (sudo, once): bash " + shlex.quote(SOURCE) + " --system-access --apply")
    print("See it now: bash " + shlex.quote(SOURCE) + " --restart   (or at the next login)")
    print(f"Back to v{version}: bash " + shlex.quote(SOURCE) + " --downgrade --apply")


def do_downgrade(args):
    base = config_base()
    root = base / "cm1406-vitrum-plus"
    if not os.path.lexists(root):
        fail("Vitrum Plus is not installed.")
    state = load_install(root)
    if state["owner"] != TOKEN or "previous" not in state:
        fail("No saved previous version here (installed directly as v10, or not v10). Use --rollback --apply instead.")
    previous = tree(root / "previous")
    old_state = json.loads(previous["state.json"])
    old_version = VERSIONS.get(old_state.get("owner"))
    if (old_version not in (1, 2, 3, 4, 5, 6, 7, 8, 9) or old_state.get("block") != state["previous"]["block"]
            or old_state["hashes"].get("original.kdl") != state["hashes"]["original.kdl"]
            or any(sha(previous[n]) != old_state["hashes"][n] for n in ("run", "shell.qml", "helper.py"))):
        fail("Saved previous record does not match; nothing changed.")
    config = Path(state["config"])
    if args.config and args.config_path != config:
        fail(f"Installed for {config}, not {args.config_path}.")
    check_target(config)
    current = config.read_bytes()
    text = current.decode("utf-8")
    if text.count(state["block"]) != 1:
        fail("The Vitrum Plus block in the niri config was edited or duplicated; nothing changed.")
    new_text = text.replace(state["block"], state["previous"]["block"], 1)
    print(f"Downgrade v10 -> v{old_version} in {root} for {config}: the exact saved files come back.")
    if state.get("light_access") and not state["light_access"].get("inherited"):
        print("The brightness udev rule is removed (sudo).")
    print("Changes made by v10 are undone" + (f" (the v{old_version} font files and settings stay, v{old_version} uses them)." if (state.get("fonts") or {}).get("inherited") else "."))
    if not niri_validate(config, new_text.encode()):
        fail("niri rejects the downgraded config; nothing changed.")
    if not args.apply:
        print("Dry-run: nothing written. Apply with:")
        print("  bash " + shlex.quote(SOURCE) + " --downgrade --apply")
        return
    state = undo_access(state, root, True)
    files = {name: previous[name] for name in V1_FILES}
    files["original.kdl"] = (root / "original.kdl").read_bytes()
    nested = {}
    for key, content in previous.items():
        if "/" in key:
            folder, _, rest = key.partition("/")
            nested.setdefault(folder, {})[rest] = content
    fd = lock(base)
    try:
        if json.loads((root / "state.json").read_text()) != state:
            fail("The install changed during this run; nothing changed. Retry.")
        switch_install(base, root, files, nested or None, config, current, new_text)
        undo_style([r for r in state.get("style") or [] if not r.get("inherited")])
        undo_dnd(state.get("dnd"), keep_inherited=True)
        undo_fonts(state, keep_inherited=True)
    finally:
        unlock(fd)
    print(f"Back to v{old_version}. See it now: bash " + shlex.quote(SOURCE) + " --restart   (or at the next login)")
    print("Upgrade again later: bash " + shlex.quote(SOURCE) + " --upgrade --apply")


def do_restart(args):
    root = config_base() / "cm1406-vitrum-plus"
    if not os.path.lexists(root):
        fail("Vitrum Plus is not installed.")
    load_install(root)
    if not os.environ.get("NIRI_SOCKET") or not shutil.which("niri"):
        fail("Run --restart from a terminal inside niri.")
    pid = running_pid()
    if pid:
        os.kill(pid, signal.SIGTERM)
        print(f"Stopped Vitrum Plus (PID {pid}).")
    runtime = runtime_dir()
    if runtime is not None and (runtime / "lock").is_file():
        fd = os.open(runtime / "lock", os.O_RDONLY | os.O_NOFOLLOW)
        try:
            for _ in range(50):
                try:
                    fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
                    fcntl.flock(fd, fcntl.LOCK_UN)
                    break
                except BlockingIOError:
                    time.sleep(0.2)
            else:
                fail("The previous instance is still shutting down; retry in a few seconds.")
        finally:
            os.close(fd)
    subprocess.run(["niri", "msg", "action", "spawn", "--", str(root / "run")], check=True,
                   stdout=subprocess.DEVNULL)
    print("Started again through niri (same as at login). Other bars and windows were not touched.")


def do_preview(args):
    if not os.environ.get("NIRI_SOCKET") or not os.environ.get("WAYLAND_DISPLAY"):
        fail("Run --preview from a terminal inside niri.")
    runtime = os.environ.get("XDG_RUNTIME_DIR")
    if not runtime or not os.path.isdir(runtime):
        fail("XDG_RUNTIME_DIR is missing.")
    display = os.environ["WAYLAND_DISPLAY"]
    socket_path = display if display.startswith("/") else os.path.join(runtime, display)
    if not stat.S_ISSOCK(os.stat(socket_path).st_mode):
        fail("Wayland socket unavailable.")
    problems = check_runtime_tools()
    if problems:
        fail("; ".join(problems))
    work = Path(tempfile.mkdtemp(prefix="cm1406-vitrum-plus-preview.", dir=runtime))
    try:
        for name in ("shell.qml", "helper.py"):
            shutil.copyfile(PAYLOAD / name, work / name)
        write_tree(work, macshell_files())
        for name in ("runtime", "cache", "data", "fonts"):
            (work / name).mkdir(mode=0o700)
        for name, content in bundled_fonts().items():
            write_new(work / "fonts", name, content, 0o600)
        escape = lambda value: value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
        fonts_conf = ('<?xml version="1.0"?>\n<!DOCTYPE fontconfig SYSTEM "urn:fontconfig:fonts.dtd">\n<fontconfig>\n'
                      f'  <include ignore_missing="yes">{escape(os.environ.get("FONTCONFIG_FILE") or "/etc/fonts/fonts.conf")}</include>\n'
                      f'  <dir>{escape(str(work / "fonts"))}</dir>\n'
                      f'  <cachedir>{escape(str(work / "cache" / "fontconfig"))}</cachedir>\n</fontconfig>\n')
        write_new(work, "fonts.conf", fonts_conf.encode(), 0o600)
        font = args.font or BUNDLED
        if font != BUNDLED and font not in installed_fonts():
            fail(f"Font {font!r} is not installed (fc-list).")
        pins_root = config_base() / "tarkin-niri-dock"
        pins = str(pins_root) if (pins_root / "pins.json").is_file() else ""
        default = "color"
        config = args.config_path
        if config.is_file():
            lines = config.read_text(errors="replace").split("\n")
            default = "fond" if WALL_EGL in lines or OFF + WALL_EGL in lines else "color"
        environment = dict(os.environ,
                           VP_HELPER=str(work / "helper.py"), VP_OUTPUT=args.output,
                           VP_TOP=str(args.top_offset), VP_BOTTOM=str(args.bottom_offset),
                           VP_RESERVE="0", VP_PREVIEW="1", VP_DEFAULT=default, VP_DATA=str(work / "data"), VP_FONT=font,
                           FONTCONFIG_FILE=str(work / "fonts.conf"),
                           VP_PINS_ROOT=pins,
                           VP_APP_RUNTIME=runtime,
                           VP_APP_CACHE=os.environ.get("XDG_CACHE_HOME") or str(Path.home() / ".cache"),
                           VP_APP_WAYLAND=display, XDG_RUNTIME_DIR=str(work / "runtime"),
                           XDG_CACHE_HOME=str(work / "cache"), WAYLAND_DISPLAY=socket_path)
        print(f"Preview on {args.output}: top {args.top_offset} px, bottom {args.bottom_offset} px, above the current bars.")
        print("Right-click the bare desktop: wallpaper and MacShell widgets (preview only, nothing saved).")
        print("Close the preview or press Ctrl+C: applications you opened stay open.")
        child = subprocess.Popen([runner(), "--path", str(work / "shell.qml")], env=environment,
                                 start_new_session=True)
        try:
            child.wait()
        except KeyboardInterrupt:
            pass
        finally:
            if child.poll() is None:
                os.killpg(child.pid, signal.SIGTERM)
                try:
                    child.wait(timeout=5)
                except subprocess.TimeoutExpired:
                    os.killpg(child.pid, signal.SIGKILL)
                    child.wait()
    finally:
        shutil.rmtree(work, ignore_errors=True)


def main():
    parser = argparse.ArgumentParser(
        prog="install-vitrum-plus-niri.sh",
        description="Vitrum Plus v10 for niri on the CM1406: macOS Liquid Glass menu bar, Control Center with working Wi-Fi, "
                    "Bluetooth, sound, brightness and keyboard light, a helper that restarts itself, Spotlight, menus, HUD, "
                    "notifications and fuzzel, "
                    "liquid glass dock, MacShell desktop widgets and the bundled Open Runde font for the shell and apps. "
                    "User-only, no packages, no root. Default is a read-only check.")
    parser.add_argument("--apply", action="store_true", help="write the change (default: dry-run check)")
    parser.add_argument("--dry-run", action="store_true", help="check only (default)")
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--rollback", action="store_true", help="undo the install (with --apply)")
    mode.add_argument("--preview", action="store_true", help="temporary foreground preview; Ctrl+C stops it")
    mode.add_argument("--status", action="store_true", help="show install and running state")
    mode.add_argument("--stop", action="store_true", help="stop only the verified Vitrum Plus instance")
    mode.add_argument("--restart", action="store_true", help="stop the verified instance and start the installed one now")
    mode.add_argument("--upgrade", action="store_true", help="upgrade an installed v1 to v9 to v10 (with --apply)")
    mode.add_argument("--diagnose", action="store_true", help="print install state, brightness access and the last helper log lines")
    mode.add_argument("--downgrade", action="store_true", help="go back to the saved previous version (with --apply)")
    parser.add_argument("--config", help="absolute niri config path (default: NIRI_CONFIG or ~/.config/niri/config.kdl)")
    parser.add_argument("--output", default="eDP-1", help="screen name (default eDP-1)")
    parser.add_argument("--replace-dock", action="store_true", help="suspend the Tarkin niri dock (files and pins untouched)")
    parser.add_argument("--font", help="font family to use (default: bundled Open Runde; any other must already be installed)")
    parser.add_argument("--system-font", action="store_true",
                        help="Open Runde for apps too (default on install/upgrade; alone on an installed v10 turns it back on)")
    parser.add_argument("--no-system-font", action="store_true",
                        help="shell font only: skip, or undo, the app font changes (fontconfig, GTK, fuzzel, mako)")
    parser.add_argument("--keep-waybar", action="store_true", help="leave the Waybar autostart in place")
    parser.add_argument("--system-access", action="store_true",
                        help="let the Control Center set keyboard and screen brightness (udev rule) and drive wpa_supplicant "
                             "(one root-only line); needs sudo; with --apply")
    parser.add_argument("--no-system-access", action="store_true", help="undo --system-access (with --apply)")
    parser.add_argument("--wifi-access", action="store_true", help="same as --system-access")
    parser.add_argument("--no-wifi-access", action="store_true", help="same as --no-system-access")
    parser.add_argument("--lines", type=int, default=60, help=argparse.SUPPRESS)
    parser.add_argument("--no-app-style", action="store_true",
                        help="install or upgrade without the macOS colours and corners for mako and fuzzel")
    parser.add_argument("--top-offset", type=int, default=56, help=argparse.SUPPRESS)
    parser.add_argument("--bottom-offset", type=int, default=104, help=argparse.SUPPRESS)
    args = parser.parse_args(sys.argv[2:])
    if os.geteuid() == 0 or os.environ.get("SUDO_USER"):
        fail("Run as your normal user, without sudo.")
    if args.apply and args.dry_run:
        fail("Choose either --apply or --dry-run.")
    args.app_fonts = not args.no_system_font
    args.app_style = not args.no_app_style
    if args.no_app_style and not (args.upgrade or not (args.rollback or args.downgrade or args.preview or args.restart
                                                        or args.stop or args.status)):
        fail("--no-app-style goes with a fresh install or --upgrade.")
    if args.system_font and args.no_system_font:
        fail("Choose either --system-font or --no-system-font.")
    if args.no_system_font and (args.rollback or args.downgrade or args.preview or args.restart or args.stop or args.status):
        fail("--no-system-font goes with a fresh install, --upgrade, or alone on an installed v10.")
    if args.system_font and (args.rollback or args.downgrade or args.preview or args.restart or args.stop or args.status):
        fail("--system-font goes with a fresh install, --upgrade, or alone on an installed v10.")
    if not re.fullmatch(r"[A-Za-z0-9_.:-]{1,64}", args.output):
        fail("Use a simple output name such as eDP-1.")
    if not (0 <= args.top_offset <= 4096 and 0 <= args.bottom_offset <= 4096):
        fail("Offsets must be between 0 and 4096.")
    args.config_path = resolve_config(args)
    want = args.system_access or args.wifi_access
    drop = args.no_system_access or args.no_wifi_access
    if want and drop:
        fail("Choose either --system-access or --no-system-access.")
    if want or drop:
        if args.upgrade or args.rollback or args.downgrade or args.preview or args.restart or args.stop or args.status \
                or args.diagnose or args.system_font or args.no_system_font:
            fail("--system-access / --no-system-access (or --wifi-access) go alone (with --apply).")
        do_system_access(args, bool(want))
        return
    if not 1 <= args.lines <= 2000:
        fail("--lines must be between 1 and 2000.")
    if args.preview:
        do_preview(args)
    elif args.status:
        do_status(args)
    elif args.diagnose:
        do_diagnose(args)
    elif args.stop:
        do_stop(args)
    elif args.restart:
        do_restart(args)
    elif args.upgrade:
        do_upgrade(args)
    elif args.downgrade:
        do_downgrade(args)
    elif args.rollback:
        do_rollback(args)
    else:
        do_install(args)


try:
    main()
except Refusal as exc:
    print("Refused: " + str(exc), file=sys.stderr)
    sys.exit(2)
except (OSError, ValueError, KeyError, TypeError, json.JSONDecodeError, subprocess.SubprocessError) as exc:
    print("Error: " + str(exc), file=sys.stderr)
    sys.exit(1)
VITRUM_INSTALLER_EOF
status=0
python3 "$work/installer.py" "$work" "$@" || status=$?
exit "$status"
